            }
            $objStream.SetLength($objStream.Length - 7)
        } finally {
            $objStream.Dispose()
        }
    }
    if ($SemanticCase -ceq 'resource.archive.above') {
        $objStream = New-Object System.IO.FileStream(
            $LiteralPath,
            [System.IO.FileMode]::Open,
            [System.IO.FileAccess]::Write,
            [System.IO.FileShare]::None
        )
