    $strRecipe = if ($script:hashtableTerraformArchiveRecipes.ContainsKey($Case.Id)) {
        $script:hashtableTerraformArchiveRecipes[$Case.Id]
    } else { 'archive.valid.exact' }
    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    $objContext = $null
    $objCandidate = $null
    $objFailure = $null
    $objObservation = $null
    $listCleanup = New-Object 'System.Collections.Generic.List[string]'
    $strBeforeCleanup = 'absent'
    $strArchivePath = $null
    $hashtableSuppliedLabels = [ordered]@{}
    $objEnvironment = $null
    $objPreexistingBefore = $null
    $strObservedCandidate = $null
    try {
        if ($Case.Id -cin @('T1A-E-09', 'T1A-E-10', 'T1A-E-26', 'T1A-W-04', 'T1A-L-03', 'T1A-L-04')) {
            $strProbePath = [System.IO.Path]::Combine($hashtableLayout.CaseRoot, 'primitive-probe')
            $boolDirectory = $Case.Id -cne 'T1A-W-04'
            $strTarget = if ($Case.Id -ceq 'T1A-L-04') { [System.IO.Path]::Combine($hashtableLayout.CaseRoot, 'absent-target') }
                elseif ($boolDirectory) { $hashtableLayout.SentinelDirectory } else { $hashtableLayout.SentinelFile }
            if (-not (& $script:scriptBlockNewSymbolicLink -LinkPath $strProbePath -TargetPath $strTarget -Directory $boolDirectory)) {
                & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'available-link-creation-failed'
            }
            if (([System.IO.File]::GetAttributes($strProbePath) -band [System.IO.FileAttributes]::Directory) -ne 0) {
                [System.IO.Directory]::Delete($strProbePath, $false)
            } else { [System.IO.File]::Delete($strProbePath) }
        }
        $strParent = $hashtableLayout.Trusted
        if ($boolDirectoryCase -and $Case.Fixture.Invocation -ceq 'context-create') {
            $strParent += [System.IO.Path]::DirectorySeparatorChar
        }
        $objContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $strParent
        $strObservedCandidate = $objContext.CandidateDirectoryPath
        if ($Case.Fixture.Invocation -cne 'context-create') {
            $objArchiveLeaf = $Case.Fixture.Parameters.PSObject.Properties['ArchiveLeaf']
            $strArchiveLeaf = if ($null -ne $objArchiveLeaf) { [string]$objArchiveLeaf.Value } else { 'artifact.zip' }
            $strArchivePath = [System.IO.Path]::Combine($objContext.DownloadDirectoryPath, $strArchiveLeaf)
            $objArchiveEvidence = if ($strRecipe -ceq 'archive.raw-resource') {
                & $script:scriptBlockNewTerraformRawZip -LiteralPath $strArchivePath -CaseId $Case.Id
            } else { & $script:scriptBlockNewZipFixture -LiteralPath $strArchivePath -SemanticCase $strRecipe }
            if ($Case.Id -ceq 'T1A-W-01') { [System.IO.File]::Delete($strArchivePath) }
            if ($strRecipe -ceq 'archive.invalid.header') {
                [System.IO.File]::WriteAllBytes($strArchivePath, (New-Object byte[] 32))
                $objArchiveEvidence = & $script:scriptBlockGetFileEvidence -LiteralPath $strArchivePath
            }
            $hashtableArguments = @{
                CheckoutRoot = $hashtableLayout.Checkout
                TrustedTemporaryRoot = $hashtableLayout.Trusted
                DownloadDirectory = $objContext.DownloadDirectoryPath
                CandidateDirectory = $objContext.CandidateDirectoryPath
                ExpectedDigest = $objArchiveEvidence.Sha256
            }
            if ($Case.Id -cin @('T1A-D-01', 'T1A-D-02', 'T1A-X-07')) {
                $hashtableArguments.ExpectedDigest = '0' * 64
            }
            if ($Case.Id -cin @('T1A-D-01', 'T1A-X-07')) {
                $hashtableSuppliedLabels.ArtifactId = '146'
                $hashtableSuppliedLabels.RunId = '9001'
                $hashtableSuppliedLabels.RunAttempt = '2'
            } elseif ($boolLabelsCase -or $boolOmittedCase) {
                $objLabels = if ($boolLabelsCase) { $Case.Fixture.Parameters.Labels } else { $Case.Fixture.Parameters.OtherLabels }
                foreach ($objProperty in $objLabels.PSObject.Properties) {
                    $hashtableSuppliedLabels[$objProperty.Name] = $objProperty.Value
                }
            }
            foreach ($strLabel in $hashtableSuppliedLabels.Keys) {
                $hashtableArguments[$strLabel] = $hashtableSuppliedLabels[$strLabel]
            }
            if ($boolDirectoryCase) {
                $hashtableArguments[$Case.Fixture.Parameters.Parameter] += [System.IO.Path]::DirectorySeparatorChar
            }
            foreach ($strParameter in @('CheckoutRoot', 'TrustedTemporaryRoot', 'DownloadDirectory', 'CandidateDirectory')) {
                if ($Case.Id -ceq 'T1A-P-02') { $hashtableArguments[$strParameter] = 'FileSystem::' + $hashtableArguments[$strParameter] }
                if ($Case.Id -ceq 'T1A-E-07') { $hashtableArguments[$strParameter] = $hashtableArguments[$strParameter].ToUpperInvariant() }
            }
            if ($Case.Id -cin $script:arrTerraformEnvironmentCase) {
                $objEnvironment = & $script:scriptBlockPrepareTerraformEnvironmentCase -CaseId $Case.Id `
                    -Layout $hashtableLayout -Context $objContext -Arguments $hashtableArguments -ArchivePath $strArchivePath
                $strObservedCandidate = $hashtableArguments.CandidateDirectory
                if ($Case.Id -cin @('T1A-L-01', 'T1A-L-02', 'T1A-L-03', 'T1A-L-04', 'T1A-AF-06')) {
                    $objPreexistingBefore = & $script:scriptBlockGetTerraformFixtureSnapshot -LiteralPath $strObservedCandidate
                    $strBeforeCleanup = 'preexisting-unchanged'
                }
            }
            try {
                $objResult = & $HelperLiteralPath @hashtableArguments
                $objCandidate = $objResult.CandidateOwnershipState
            } catch {
                $objFailure = $_
                $objCandidate = $objFailure.Exception.Data['CandidateOwnershipState']
                if ($null -eq $objPreexistingBefore -and $null -ne $objCandidate -and $objCandidate.OwnershipJournal.Count -gt 0) {
                    $strBeforeCleanup = 'owned-partial'
                }
            }
            if ($null -eq $objFailure) {
                & $script:scriptBlockAssertTerraformExpandedFiles -Result $objResult `
                    -CandidatePath $objContext.CandidateDirectoryPath -ArchivePath $strArchivePath
                $strBeforeCleanup = 'four-valid-files'
            }
            if ($null -ne $objCandidate) {
                if ($objCandidate.LifecycleState -ceq 'Active') {
                    $objCandidate = Remove-StyleGuideCandidateInvocationState -CandidateOwnershipState $objCandidate
                }
                if ($objCandidate.CleanupAttempt -gt 0) { $listCleanup.Add('candidate-cleanup') }
                if ($Case.Id -ceq 'T1A-AF-08') {
                    $objSummaryBeforeRepeat = $objCandidate.CleanupSummary
                    $uintAttemptsBeforeRepeat = $objCandidate.CleanupAttempt
                    $objRepeated = Remove-StyleGuideCandidateInvocationState -CandidateOwnershipState $objCandidate
                    if (-not [object]::ReferenceEquals($objRepeated, $objCandidate) -or
                        -not [object]::ReferenceEquals($objRepeated.CleanupSummary, $objSummaryBeforeRepeat) -or
                        $objRepeated.CleanupAttempt -ne $uintAttemptsBeforeRepeat) { throw 'primary-cleanup-repeat-identity' }
                }
            }
        }
        $arrCleanupErrors = @()
        $hashtableCleanupArguments = @{ Context = $objContext; ErrorAction = 'SilentlyContinue'; ErrorVariable = '+arrCleanupErrors' }
        if ($null -ne $strArchivePath -and $Case.Id -cne 'T1A-W-01') { $hashtableCleanupArguments.OwnedPaths = [object[]]@($strArchivePath) }
        if ($null -ne $objCandidate) { $hashtableCleanupArguments.CandidateOwnershipState = $objCandidate }
        if ($null -ne $objFailure) { $hashtableCleanupArguments.PrimaryFailure = $objFailure }
        [void](Remove-StyleGuideCandidateInvocationContext @hashtableCleanupArguments)
        $listCleanup.Add('context-cleanup')
        $strFinalCandidate = if ((& $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $strObservedCandidate) -ceq 'absent') { 'absent' } else { 'uncertain-retained' }
        if ($null -ne $objPreexistingBefore) {
            $objPreexistingAfter = & $script:scriptBlockGetTerraformFixtureSnapshot -LiteralPath $strObservedCandidate
            if (($objPreexistingBefore.Entries -join "`n") -ceq ($objPreexistingAfter.Entries -join "`n")) {
                $strFinalCandidate = 'preexisting-unchanged'
            }
        }
        $hashtableLabels = [ordered]@{ ArtifactId = 'not-emitted'; RunId = 'not-emitted'; RunAttempt = 'not-emitted' }
        if ($null -ne $objFailure -and $objFailure.Exception.Data.Contains('Diagnostics')) {
            foreach ($strLabel in @('ArtifactId', 'RunId', 'RunAttempt')) {
                $hashtableLabels[$strLabel] = $objFailure.Exception.Data['Diagnostics'].PSObject.Properties[$strLabel].Value
            }
        }
        $objObservation = [pscustomobject][ordered]@{
            ActualInitialState = 'NotCreated'
            InitialStateObservationScope = 'pre-invocation-no-candidate-capability'
            PrimaryFailureSupplied = $false
            ActualResult = if ($null -eq $objFailure) { 'success' } else { 'rejection' }
            ActualStatus = if ($null -eq $objFailure) { 0 } else { 1 }
            ActualPhase = if ($null -eq $objFailure) { 'complete' } else { $objFailure.Exception.Data['TerraformStyleGuidePhase'] }
            ActualSubreason = if ($null -eq $objFailure) { 'none' } else { $objFailure.Exception.Data['TerraformStyleGuideSubreason'] }
            ActualPreCleanupCandidateState = $strBeforeCleanup
            ActualCandidateState = $strFinalCandidate
            ActualContextState = $objContext.LifecycleState
            ActualCleanupSequence = $listCleanup.ToArray()
            ActualSentinelState = if (& $script:scriptBlockTestSentinelIntact -Layout $hashtableLayout) { 'unchanged' } else { 'changed' }
            ActualLabels = [pscustomobject]$hashtableLabels
            LabelExposure = if ($null -eq $objFailure) { 'not-emitted' } else { 'failure-diagnostics' }
            AcceptedSuppliedLabels = [pscustomobject]$hashtableSuppliedLabels
            RawArchiveSha256 = if ($strRecipe -ceq 'archive.raw-resource') { $objArchiveEvidence.Sha256 } else { $null }
            CleanupErrorCount = $arrCleanupErrors.Count
            PreCleanupEvidence = if ($null -ne $objPreexistingBefore) { 'direct-before-after-entry-snapshot' }
                elseif ($null -eq $objFailure) { 'direct-four-files-content-proof' }
                elseif ($strBeforeCleanup -ceq 'owned-partial') { 'authenticated-acquisition-journal-after-automatic-cleanup' }
                else { 'no-candidate-acquisition-recorded' }
        }
    } finally {
        if ($null -ne $objEnvironment -and $null -ne $objEnvironment.Lock) { $objEnvironment.Lock.Dispose() }
        & $script:scriptBlockRemoveTestTree -LiteralPath $hashtableLayout.CaseRoot -ApprovedParent $RunRoot
    }
    return $objObservation
}

$script:scriptBlockInvokeTerraformProductionGuardCase = {
    param ([object]$Case, [string]$RunRoot)

    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    $objContext = $null
    try {
        $objContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $hashtableLayout.Trusted
        $objModule = Microsoft.PowerShell.Core\Get-Module -Name 'TerraformStyleGuideCandidateArtifact_1_0_20260924_1'
        if (@($objModule).Count -ne 1) { throw 'guard-module-cardinality' }
        $objFailure = $null
        $objPredicate = $null
        try {
            $objPredicate = & $objModule {
                param ([string]$Id, [string]$Root)
                switch -Exact ($Id) {
                    'T1A-AF-01' {
                        $boolControl = & $script:scriptBlockTestCandidateHelperPathContained -Root $Root -Candidate ([System.IO.Path]::Combine($Root, 'child'))
                        $boolSibling = & $script:scriptBlockTestCandidateHelperPathContained -Root $Root -Candidate ($Root + '-sibling')
                        return [pscustomobject]@{ PositiveControl = $boolControl; SiblingContained = $boolSibling }
