        foreach ($strCategory in @('Provider', 'Path', 'Filesystem', 'Native')) {
            if ($objRepeat.Counts[$strCategory] -ne 0) { throw 'terminal-boundary-called' }
        }
        if (-not [object]::ReferenceEquals($objRepeat.Returned, $objCandidate) -or
            -not [object]::ReferenceEquals($objCandidate.OwnershipJournal, $objJournal) -or
            -not [object]::ReferenceEquals($objCandidate.CleanupSummary, $objSummary) -or
            $objCandidate.CleanupAttempt -ne $uintAttempt -or $objCandidate.LifecycleState -cne $strStateBefore) { throw 'terminal-capability-changed' }
        $objSnapshotAfter = & $script:scriptBlockGetTerraformFixtureSnapshot -LiteralPath $objContext.InvocationRootPath
        $strPresenceAfter = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $strPath
        $strLinkAfter = if ($boolLink) { @( (Microsoft.PowerShell.Management\Get-Item -LiteralPath $strPath -Force).Target) -join '|' } else { $null }
        if (($objSnapshotBefore.Entries -join "`n") -cne ($objSnapshotAfter.Entries -join "`n") -or
            $strPresenceBefore -cne $strPresenceAfter -or $strLinkBefore -cne $strLinkAfter) { throw 'terminal-name-changed' }
        $strPhysicalState = if ($strPresenceAfter -ceq 'absent') { 'absent' } elseif ($strPresenceAfter -ceq 'present') { 'preexisting-unchanged' } else { throw 'terminal-presence-uncertain' }
        return [pscustomobject][ordered]@{
            ActualInitialState = $strStateBefore
            InitialStateObservationScope = 'authenticated-candidate-lifecycle'
            PrimaryFailureSupplied = $false
            ActualResult = 'success'; ActualStatus = 0
            ActualPhase = 'cleanup'; ActualSubreason = 'candidate-already-disposed'
            ObservationScope = 'authenticated-terminal-outcome-projection'
            EmittedProductionDiagnostic = $false
            ActualPreCleanupCandidateState = $strPhysicalState
            ActualCandidateState = $strPhysicalState
            ActualContextState = $objContext.LifecycleState
            ActualCleanupSequence = [string[]]@('candidate-cleanup-noop')
            ActualSentinelState = if (& $script:scriptBlockTestSentinelIntact -Layout $hashtableLayout) { 'unchanged' } else { 'changed' }
            ActualLabels = [pscustomobject]@{ ArtifactId = 'not-emitted'; RunId = 'not-emitted'; RunAttempt = 'not-emitted' }
            LabelExposure = 'not-emitted'
            ProviderCalls = $objRepeat.Counts.Provider; PathCalls = $objRepeat.Counts.Path
            FilesystemCalls = $objRepeat.Counts.Filesystem; NativeCalls = $objRepeat.Counts.Native
            ZeroCallProofScope = 'finite-reviewed-static-closure-and-private-boundary-spies'
            UnreadableControlObserved = $boolUnreadable
            SameObject = [object]::ReferenceEquals($objRepeat.Returned, $objCandidate)
            SameJournal = [object]::ReferenceEquals($objCandidate.OwnershipJournal, $objJournal)
            SameSummary = [object]::ReferenceEquals($objCandidate.CleanupSummary, $objSummary)
            SameAttempt = $objCandidate.CleanupAttempt -eq $uintAttempt
            FixtureSnapshotUnchanged = $true
        }
    } finally {
        if ($null -ne $objLock) { $objLock.Dispose() }
        & $script:scriptBlockRemoveTestTree -LiteralPath $hashtableLayout.CaseRoot -ApprovedParent $RunRoot
    }
}

$script:scriptBlockInvokeTerraformNotCreatedCandidateCase = {
    param ([object]$Case, [string]$RunRoot)

    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    try {
        $objContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $hashtableLayout.Trusted
        $strCandidate = $objContext.CandidateDirectoryPath
        if ($Case.Id -ceq 'T1A-K-11') { [System.IO.File]::WriteAllBytes($strCandidate, [byte[]]@(110, 111, 116, 45, 111, 119, 110, 101, 100)) }
        elseif ($Case.Id -cne 'T1A-K-10') { throw 'not-created-case-id' }
        $objModule = Microsoft.PowerShell.Core\Get-Module -Name TerraformStyleGuideCandidateArtifact_1_0_20260924_1 -All
        $objCandidate = & $objModule {
            param ([string]$Trusted, [string]$Parent, [string]$Path)
            $objIssued = & $script:scriptBlockNewCandidateOwnershipState -TrustedRoot $Trusted -CandidateParent $Parent -CandidatePath $Path
            $objRegistration = & $script:scriptBlockAssertCandidateOwnershipState -Value $objIssued
            if (-not [object]::ReferenceEquals($objRegistration.Object, $objIssued) -or $objRegistration.State -cne 'NotCreated') { throw 'not-created-authentication' }
            return $objIssued
        } $hashtableLayout.Trusted $objContext.InvocationRootPath $strCandidate
        $strInitial = $objCandidate.LifecycleState
        $objBefore = & $script:scriptBlockGetTerraformFixtureSnapshot -LiteralPath $objContext.InvocationRootPath
        $strPresenceBefore = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $strCandidate
        $arrErrors = @()
        $objReturned = Remove-StyleGuideCandidateInvocationState -CandidateOwnershipState $objCandidate -ErrorAction SilentlyContinue -ErrorVariable +arrErrors
        if (-not [object]::ReferenceEquals($objReturned, $objCandidate) -or $objCandidate.CleanupSummary.RemovedPaths.Count -ne 0) { throw 'not-created-cleanup-identity' }
        $strRequiredLifecycle = if ($Case.Id -ceq 'T1A-K-10') { 'Disposed' } else { 'RetainedUncertain' }
        if ($objCandidate.LifecycleState -cne $strRequiredLifecycle -or $objCandidate.CleanupAttempt -ne 1 -or
            $objCandidate.OwnershipJournal.Count -ne 0 -or $objCandidate.CleanupSummary.PriorState -cne 'NotCreated' -or
            $objCandidate.CleanupSummary.FinalState -cne $strRequiredLifecycle -or $objCandidate.CleanupSummary.Attempt -ne 1) { throw 'not-created-lifecycle-transition' }
        $listCleanup = New-Object 'System.Collections.Generic.List[string]'
        $listCleanup.Add('candidate-cleanup')
        if ($arrErrors.Count -gt 0) {
            $arrContextErrors = @()
            [void](Remove-StyleGuideCandidateInvocationContext -Context $objContext -CandidateOwnershipState $objCandidate -PrimaryFailure $arrErrors[-1] -ErrorAction SilentlyContinue -ErrorVariable +arrContextErrors)
            $listCleanup.Add('context-cleanup')
            if ($arrContextErrors.Count -eq 0 -or $objContext.LifecycleState -cne 'RetainedUncertain' -or $objContext.CleanupSummary.RemovedPaths.Count -ne 0) { throw 'not-created-context-retention' }
        }
        $objAfter = & $script:scriptBlockGetTerraformFixtureSnapshot -LiteralPath $objContext.InvocationRootPath
        $strPresenceAfter = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $strCandidate
        if (($objBefore.Entries -join "`n") -cne ($objAfter.Entries -join "`n") -or $strPresenceBefore -cne $strPresenceAfter) { throw 'not-created-fixture-changed' }
        $strPhysical = if ($strPresenceAfter -ceq 'absent') { 'absent' } elseif ($strPresenceAfter -ceq 'present') { 'preexisting-unchanged' } else { throw 'not-created-presence-uncertain' }
        return [pscustomobject][ordered]@{
            ActualResult = if ($arrErrors.Count -eq 0) { 'success' } else { 'rejection' }
            ActualStatus = if ($arrErrors.Count -eq 0) { 0 } else { 1 }
            ActualPhase = if ($arrErrors.Count -eq 0) { 'cleanup' } else { $arrErrors[-1].Exception.Data['TerraformStyleGuidePhase'] }
            ActualSubreason = if ($arrErrors.Count -eq 0) { 'candidate-disposed' } else { $arrErrors[-1].Exception.Data['TerraformStyleGuideSubreason'] }
            PrimaryFailureSupplied = $false
            ActualInitialState = $strInitial
            InitialStateObservationScope = 'authenticated-candidate-lifecycle'
            ObservationScope = 'production-private-issuance/public-cleanup'
            ActualPreCleanupCandidateState = $strPhysical
            ActualCandidateState = $strPhysical
            ActualContextState = $objContext.LifecycleState
            ActualCleanupSequence = $listCleanup.ToArray()
            ActualSentinelState = if (& $script:scriptBlockTestSentinelIntact -Layout $hashtableLayout) { 'unchanged' } else { 'changed' }
            ActualLabels = [pscustomobject]@{ ArtifactId = 'not-emitted'; RunId = 'not-emitted'; RunAttempt = 'not-emitted' }
            LabelExposure = 'not-emitted'
            CandidateLifecycleState = $objCandidate.LifecycleState
            RemovedCount = $objCandidate.CleanupSummary.RemovedPaths.Count
            SameObject = [object]::ReferenceEquals($objReturned, $objCandidate)
            FixtureSnapshotUnchanged = $true
        }
    } finally {
        & $script:scriptBlockRemoveTestTree -LiteralPath $hashtableLayout.CaseRoot -ApprovedParent $RunRoot
    }
}

$script:scriptBlockInvokeTerraformContextCreationCase = {
    param ([object]$Case, [string]$RunRoot)

    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    try {
        $strParent = $hashtableLayout.Trusted
        switch -Exact ($Case.Id) {
            'T1A-AF-02' { $strParent = 'Registry::' + $hashtableLayout.Trusted }
            'T1A-AF-04' {
                $strParent = [System.IO.Path]::Combine($hashtableLayout.CaseRoot, 'parent-link')
                if (-not (& $script:scriptBlockNewSymbolicLink -LinkPath $strParent -TargetPath $hashtableLayout.Trusted -Directory $true)) {
                    & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'available-link-creation-failed'
                }
            }
            'T1A-AF-05' { $strParent = $hashtableLayout.SentinelFile }
            default { throw 'context-creation-case' }
        }
        $objBefore = & $script:scriptBlockGetTerraformFixtureSnapshot -LiteralPath $hashtableLayout.CaseRoot
        $objFailure = $null
        $objContext = $null
        try { $objContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $strParent }
        catch { $objFailure = $_ }
        if ($null -eq $objFailure -or $null -ne $objContext) { throw 'context-creation-refusal-missing' }
        $objAfter = & $script:scriptBlockGetTerraformFixtureSnapshot -LiteralPath $hashtableLayout.CaseRoot
        if (($objBefore.Entries -join "`n") -cne ($objAfter.Entries -join "`n")) { throw 'context-creation-fixture-changed' }
        $boolSourceDiagnostic = $Case.Id -cin @('T1A-AF-04', 'T1A-AF-05')
        $strSourceCode = $null
        if ($boolSourceDiagnostic) {
            $strSourceCode = $objFailure.Exception.Data['PSStyleGuideDiagnosticCode']
            if ($strSourceCode -cne 'root-invalid' -or
                $objFailure.Exception.Message -cne 'PSStyleGuide.ContextCreate.v1|category=root-invalid|cleanup=not-required') {
                throw 'source-create-diagnostic-mismatch'
            }
        }
        return [pscustomobject][ordered]@{
            ActualInitialState = 'NotCreated'
            InitialStateObservationScope = 'pre-invocation-no-candidate-capability'
            PrimaryFailureSupplied = $false
            ActualResult = 'rejection'; ActualStatus = 1
            ActualPhase = if ($boolSourceDiagnostic) { 'root' } else { $objFailure.Exception.Data['TerraformStyleGuidePhase'] }
            ActualSubreason = if ($boolSourceDiagnostic) { $strSourceCode } else { $objFailure.Exception.Data['TerraformStyleGuideSubreason'] }
            ActualPreCleanupCandidateState = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath ([System.IO.Path]::Combine($hashtableLayout.Trusted, 'candidate'))
            ActualCandidateState = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath ([System.IO.Path]::Combine($hashtableLayout.Trusted, 'candidate'))
            ActualContextState = if ($null -eq $objContext) { 'not-created' } else { $objContext.LifecycleState }
            ActualCleanupSequence = [string[]]@('none')
            ActualSentinelState = if (& $script:scriptBlockTestSentinelIntact -Layout $hashtableLayout) { 'unchanged' } else { 'changed' }
            ActualLabels = [pscustomobject]@{ ArtifactId = 'not-emitted'; RunId = 'not-emitted'; RunAttempt = 'not-emitted' }
            LabelExposure = 'not-emitted'
            FixtureSnapshotUnchanged = $true
            DiagnosticNamespace = if ($boolSourceDiagnostic) { 'PSStyleGuide.ContextCreate.v1' } else { 'TerraformStyleGuide' }
            DiagnosticProjection = if ($boolSourceDiagnostic) { 'preserved-source-code-semantic-projection' } else { 'emitted-production-diagnostic' }
            ObservationScope = if ($boolSourceDiagnostic) { 'preserved-source-code-semantic-projection' } else { 'public-context-creation' }
            EmittedTerraformDiagnostic = -not $boolSourceDiagnostic
        }
    } finally {
        & $script:scriptBlockRemoveTestTree -LiteralPath $hashtableLayout.CaseRoot -ApprovedParent $RunRoot
    }
}

$script:scriptBlockInvokeTerraformCatalogIntegrityCase = {
    param ([object]$Case, [string]$RunRoot, [string]$CatalogPath)

    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    try {
        $objCatalogBefore = & $script:scriptBlockGetFileEvidence -LiteralPath $CatalogPath
        $arrObserved = @(& $script:scriptBlockAssertTerraformCatalogMutationsRejected -LiteralPath $CatalogPath -RunRoot $hashtableLayout.Trusted -CaseId $Case.Id -EmitObservations)
        $objCatalogAfter = & $script:scriptBlockGetFileEvidence -LiteralPath $CatalogPath
        if ($arrObserved.Count -ne 1 -or $arrObserved[0].Id -cne $Case.Id -or
            $objCatalogBefore.Sha256 -cne $objCatalogAfter.Sha256 -or $objCatalogBefore.Length -ne $objCatalogAfter.Length) { throw 'catalog-integrity-observation' }
        $objObserved = $arrObserved[0]
        Add-Member -InputObject $objObserved -NotePropertyName ActualInitialState -NotePropertyValue 'not-applicable'
        Add-Member -InputObject $objObserved -NotePropertyName InitialStateObservationScope -NotePropertyValue 'catalog-validation-without-product-invocation'
        Add-Member -InputObject $objObserved -NotePropertyName PrimaryFailureSupplied -NotePropertyValue $false
        Add-Member -InputObject $objObserved -NotePropertyName ActualSentinelState -NotePropertyValue $(if (& $script:scriptBlockTestSentinelIntact -Layout $hashtableLayout) { 'unchanged' } else { 'changed' })
        Add-Member -InputObject $objObserved -NotePropertyName ActualLabels -NotePropertyValue ([pscustomobject]@{ ArtifactId = 'not-emitted'; RunId = 'not-emitted'; RunAttempt = 'not-emitted' })
        Add-Member -InputObject $objObserved -NotePropertyName LabelExposure -NotePropertyValue 'not-emitted'
        return $objObserved
    } finally {
        & $script:scriptBlockRemoveTestTree -LiteralPath $hashtableLayout.CaseRoot -ApprovedParent $RunRoot
    }
}

$script:scriptBlockAddTerraformDerivedFixtureState = {
    param ([string]$Source, [ValidateSet('helper', 'context')][string]$Role)

    # Only disposable derived test copies receive this private state. Its
    # creation precedes manager GetNewClosure captures, so all hooks and the
    # worker share one explicit reference without a global variable.
    $strNewline = if ($Source.Contains("`r`n")) { "`r`n" } else { "`n" }
    $strMarker = if ($Role -ceq 'helper') { '$scriptBlockCandidateModuleDefinition = {' }
        else { '    param ([string]$ManagerDirectory)' }
    if ($Source.Contains('$script:hashtableTask184FixtureState = @{}') -or
        $Source.Contains('$hashtableTask184FixtureState = @{}') -or
        $Source.Split([string[]]@($strMarker), [StringSplitOptions]::None).Count -ne 2) { throw 'fixture-state-transform-cardinality' }
    $strAssignment = if ($Role -ceq 'helper') { '    $script:hashtableTask184FixtureState = @{}' }
        else { '    $hashtableTask184FixtureState = @{}' }
    return $Source.Replace($strMarker, $strMarker + $strNewline + $strAssignment)
}

$script:scriptBlockGetTerraformDerivedFixtureState = {
    param ([string]$Roles, [ValidateSet('helper', 'context')][string]$Role)

    $strFile = if ($Role -ceq 'helper') { 'Expand-StyleGuideCandidateArtifact.ps1' } else { 'Manage-StyleGuideCandidateInvocationContext.ps1' }
    $strName = if ($Role -ceq 'helper') { 'TerraformStyleGuideCandidateArtifact_1_0_20260924_1' } else { 'TerraformStyleGuideCandidateContext_1_0_20260924_1' }
    $strVariable = if ($Role -ceq 'helper') { 'scriptBlockCandidateModuleDefinition' } else { 'scriptBlockContextModuleDefinition' }
    $arrErrors = $null
    $objAst = [Management.Automation.Language.Parser]::ParseFile([IO.Path]::Combine($Roles, $strFile), [ref]$null, [ref]$arrErrors)
    if ($arrErrors.Count -ne 0) { throw 'fixture-state-source-parse' }
    $arrDefinitions = @($objAst.FindAll({ param ($Node)
        $Node -is [Management.Automation.Language.AssignmentStatementAst] -and
        $Node.Left -is [Management.Automation.Language.VariableExpressionAst] -and
        $Node.Left.VariablePath.UserPath -ceq $strVariable
    }, $true))
    if ($arrDefinitions.Count -ne 1) { throw 'fixture-state-definition' }
    $arrLiterals = @($arrDefinitions[0].Right.FindAll({ param ($Node)
        $Node -is [Management.Automation.Language.ScriptBlockExpressionAst]
    }, $false))
    $arrModules = @(Microsoft.PowerShell.Core\Get-Module -Name $strName -All)
    if ($arrLiterals.Count -ne 1 -or $arrModules.Count -ne 1 -or
        $arrModules[0].Definition -cne $arrLiterals[0].ScriptBlock.Extent.Text) { throw 'fixture-state-module-identity' }
    $objState = & $arrModules[0] { $hashtableTask184FixtureState }
    if ($objState -isnot [hashtable]) { throw 'fixture-state-reference' }
    return $objState
}


$script:scriptBlockTerraformInProgressWorker = {
    param ([string]$Roles, [string]$FixtureRoot)

    Set-StrictMode -Version Latest
    $ErrorActionPreference = 'Stop'
    . ([System.IO.Path]::Combine($Roles, 'Manage-StyleGuideCandidateInvocationContext.ps1'))
    $strHelper = [System.IO.Path]::Combine($Roles, 'Expand-StyleGuideCandidateArtifact.ps1')
    $hashtableFixtureState = & $script:scriptBlockGetTerraformDerivedFixtureState -Roles $Roles -Role helper
    $scriptBlockTerminalProbe = $script:scriptBlockInvokeTerraformTerminalCandidateProbe
    $listResults = New-Object 'System.Collections.Generic.List[pscustomobject]'
    foreach ($strMode in @('control', 'in-progress')) {
        $strRoot = [System.IO.Path]::Combine($FixtureRoot, $strMode)
        $strCheckout = [System.IO.Path]::Combine($strRoot, 'checkout')
        $strTrusted = [System.IO.Path]::Combine($strRoot, 'trusted')
        [void][System.IO.Directory]::CreateDirectory($strCheckout)
        [void][System.IO.Directory]::CreateDirectory($strTrusted)
        $objContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $strTrusted
        $strArchive = [System.IO.Path]::Combine($objContext.DownloadDirectoryPath, 'artifact.zip')
        $objZip = [System.IO.Compression.ZipFile]::Open($strArchive, [System.IO.Compression.ZipArchiveMode]::Create)
        try {
            foreach ($strName in @('copilot-instructions.md', 'terraform.instructions.md', 'STYLE_GUIDE_CHAT.md', 'STYLE_GUIDE_FULL.md')) {
                $objStream = $objZip.CreateEntry($strName).Open()
                try {
                    $arrBytes = [System.Text.Encoding]::UTF8.GetBytes("fixture`n")
                    $objStream.Write($arrBytes, 0, $arrBytes.Length)
                } finally { $objStream.Dispose() }
            }
        } finally { $objZip.Dispose() }
        $strDigest = (Microsoft.PowerShell.Utility\Get-FileHash -LiteralPath $strArchive -Algorithm SHA256).Hash
        $objResult = & $strHelper -CheckoutRoot $strCheckout -TrustedTemporaryRoot $strTrusted `
            -DownloadDirectory $objContext.DownloadDirectoryPath -CandidateDirectory $objContext.CandidateDirectoryPath -ExpectedDigest $strDigest
        if ($objResult.CandidatePaths.Count -ne 4 -or $objResult.CandidateOwnershipState.LifecycleState -cne 'Active') { throw 'in-progress-expansion-control' }
        $hashtableFiles = @{}
        foreach ($strPath in $objResult.CandidatePaths) {
            $hashtableFiles[$strPath] = [System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes($strPath))
        }
        $hashtableFixtureState.Observation = $null
        $hashtableFixtureState.Hook = if ($strMode -ceq 'control') {
            { param ([object]$State)
                if ($State.LifecycleState -cne 'CleanupInProgress' -or $State.CleanupAttempt -ne 1) { throw 'in-progress-control-transition' }
            }
        } else {
            {
                param ([object]$State)
                if ($State.LifecycleState -cne 'CleanupInProgress' -or $State.CleanupAttempt -ne 1) { throw 'in-progress-transition-not-observed' }
                $objJournal = $State.OwnershipJournal
                $objSummary = $State.CleanupSummary
                $uintAttempt = $State.CleanupAttempt
                $objRepeated = & $scriptBlockTerminalProbe -State $State
                if ($objRepeated.Errors.Count -ne 1 -or
                    $objRepeated.Errors[0].Exception.Data['TerraformStyleGuidePhase'] -cne 'cleanup' -or
                    $objRepeated.Errors[0].Exception.Data['TerraformStyleGuideSubreason'] -cne 'candidate-state-retained') { throw 'in-progress-repeat-diagnostic' }
                foreach ($strCategory in @('Provider', 'Path', 'Filesystem', 'Native')) {
                    if ($objRepeated.Counts[$strCategory] -ne 0) { throw 'in-progress-repeat-boundary' }
                }
                $hashtableFixtureState.Observation = [pscustomobject]@{
                    ActualInitialState = $State.LifecycleState
                    Phase = $objRepeated.Errors[0].Exception.Data['TerraformStyleGuidePhase']
                    Subreason = $objRepeated.Errors[0].Exception.Data['TerraformStyleGuideSubreason']
                    SameObject = [object]::ReferenceEquals($objRepeated.Returned, $State)
                    SameJournal = [object]::ReferenceEquals($State.OwnershipJournal, $objJournal)
                    SameSummary = [object]::ReferenceEquals($State.CleanupSummary, $objSummary)
                    SameAttempt = $State.CleanupAttempt -eq $uintAttempt
                    ProviderCalls = $objRepeated.Counts.Provider; PathCalls = $objRepeated.Counts.Path
                    FilesystemCalls = $objRepeated.Counts.Filesystem; NativeCalls = $objRepeated.Counts.Native
                }
                if (-not $hashtableFixtureState.Observation.SameObject -or -not $hashtableFixtureState.Observation.SameJournal -or
                    -not $hashtableFixtureState.Observation.SameSummary -or -not $hashtableFixtureState.Observation.SameAttempt -or
                    $State.LifecycleState -cne 'CleanupInProgress') { throw 'in-progress-repeat-mutated' }
                throw 'in-progress-controlled-abort-before-deletion'
            }.GetNewClosure()
        }
        $arrErrors = @()
        $objCandidate = Remove-StyleGuideCandidateInvocationState -CandidateOwnershipState $objResult.CandidateOwnershipState -ErrorAction SilentlyContinue -ErrorVariable +arrErrors
        if ($strMode -ceq 'control') {
            if ($arrErrors.Count -ne 0 -or $objCandidate.LifecycleState -cne 'Disposed' -or $objCandidate.CleanupSummary.RemovedPaths.Count -ne 5) { throw 'in-progress-no-contention-control' }
        } else {
            # PowerShell ErrorVariable also receives caught errors from the
            # nested positive controls. The final emitted record identifies
            # the outer cleanup failure; it must preserve our exact abort.
            if ($null -eq $hashtableFixtureState.Observation -or $arrErrors.Count -lt 1 -or
                $objCandidate.LifecycleState -cne 'RetainedUncertain' -or $objCandidate.CleanupSummary.RemovedPaths.Count -ne 0 -or
                $arrErrors[-1].Exception.Data['TerraformStyleGuidePhase'] -cne 'cleanup' -or
                $arrErrors[-1].Exception.Data['TerraformStyleGuideSubreason'] -cne 'candidate-state-retained' -or
                $null -eq $arrErrors[-1].Exception.InnerException -or
                $arrErrors[-1].Exception.InnerException.Message -cne 'in-progress-controlled-abort-before-deletion') { throw 'in-progress-abort-outcome' }
            foreach ($strPath in $hashtableFiles.Keys) {
                if ([System.Convert]::ToBase64String([System.IO.File]::ReadAllBytes($strPath)) -cne $hashtableFiles[$strPath]) { throw 'in-progress-file-changed' }
            }
        }
        $arrContextErrors = @()
        [void](Remove-StyleGuideCandidateInvocationContext -Context $objContext -OwnedPaths ([object[]]@($strArchive)) `
            -CandidateOwnershipState $objCandidate -ErrorAction SilentlyContinue -ErrorVariable +arrContextErrors)
        $strExpectedContext = if ($strMode -ceq 'control') { 'Disposed' } else { 'RetainedUncertain' }
        if ($objContext.LifecycleState -cne $strExpectedContext) { throw 'in-progress-context-outcome' }
        if ($strMode -ceq 'control') {
            if ($arrContextErrors.Count -ne 0) { throw 'in-progress-context-control-error' }
        } elseif ($arrContextErrors.Count -lt 1 -or
            $arrContextErrors[-1].Exception.Data['TerraformStyleGuidePhase'] -cne 'cleanup' -or
            $arrContextErrors[-1].Exception.Data['TerraformStyleGuideSubreason'] -cne 'context-state-retained') { throw 'in-progress-context-retained-error' }
        $listResults.Add([pscustomobject]@{
            Mode = $strMode; ContextState = $objContext.LifecycleState; CandidateState = $objCandidate.LifecycleState
            RemovedCount = $objCandidate.CleanupSummary.RemovedPaths.Count
            ContextRemovedCount = $objContext.CleanupSummary.RemovedPaths.Count
            ReentrantObservation = $hashtableFixtureState.Observation
        })
    }
    [System.IO.File]::WriteAllText([System.IO.Path]::Combine($FixtureRoot, 'result.json'),
        (ConvertTo-Json -InputObject $listResults.ToArray() -Depth 8 -Compress), (New-Object System.Text.UTF8Encoding($false)))
}

$script:scriptBlockInvokeTerraformInProgressCandidateCase = {
    param ([object]$Case, [string]$RunRoot, [string]$HelperLiteralPath, [string]$ContextLiteralPath)

    if ($Case.Id -cne 'T1A-K-12') { throw 'in-progress-case-id' }
    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    $hashtableWorker = $null
    try {
        $arrSource = [System.IO.File]::ReadAllBytes($HelperLiteralPath)
        $objHasher = [System.Security.Cryptography.SHA256]::Create()
        try { $strSourceHash = [System.BitConverter]::ToString($objHasher.ComputeHash($arrSource)).Replace('-', '').ToLowerInvariant() }
        finally { $objHasher.Dispose() }
        $strSource = (New-Object System.Text.UTF8Encoding($false, $true)).GetString($arrSource)
        & $script:scriptBlockAssertTerminalCapabilityClosure -Source $strSource -Role helper
        $strNewline = if ($strSource.Contains("`r`n")) { "`r`n" } else { "`n" }
        $strMarker = "                `$CandidateOwnershipState.LifecycleState = 'CleanupInProgress'" + $strNewline +
            '                foreach ($objEntry in @($arrFiles | Sort-Object -Property Sequence -Descending)) {'
        if ([regex]::Matches($strSource, [regex]::Escape($strMarker)).Count -ne 1) { throw 'in-progress-transform-cardinality' }
        $strDerived = & $script:scriptBlockAddTerraformDerivedFixtureState -Source $strSource -Role helper
        $strDerived = $strDerived.Replace($strMarker, $strMarker.Replace($strNewline,
                $strNewline + '                & $script:hashtableTask184FixtureState.Hook $CandidateOwnershipState' + $strNewline))
        & $script:scriptBlockAssertTerminalCapabilityClosure -Source $strDerived -Role helper
        $arrDerived = (New-Object System.Text.UTF8Encoding($false, $true)).GetBytes($strDerived)
        $objHasher = [System.Security.Cryptography.SHA256]::Create()
        try { $strDerivedHash = [System.BitConverter]::ToString($objHasher.ComputeHash($arrDerived)).Replace('-', '').ToLowerInvariant() }
        finally { $objHasher.Dispose() }
        $strRoles = [System.IO.Path]::Combine($hashtableLayout.CaseRoot, 'roles')
        [void][System.IO.Directory]::CreateDirectory($strRoles)
        $strDerivedPath = [System.IO.Path]::Combine($strRoles, 'Expand-StyleGuideCandidateArtifact.ps1')
        [System.IO.File]::WriteAllBytes($strDerivedPath, $arrDerived)
        [System.IO.File]::WriteAllBytes([System.IO.Path]::Combine($strRoles, 'Manage-StyleGuideCandidateInvocationContext.ps1'), [System.IO.File]::ReadAllBytes($ContextLiteralPath))
        $strWorkerPath = [System.IO.Path]::Combine($hashtableLayout.CaseRoot, 'worker.ps1')
        $strWorkerSource = "param ([string]`$Roles, [string]`$FixtureRoot)`n" +
            '$script:scriptBlockInitializeTerraformWorkerCompression = {' + $script:scriptBlockInitializeTerraformWorkerCompression.ToString() + "}`n" +
            '& $script:scriptBlockInitializeTerraformWorkerCompression' + "`n" +
            '$script:scriptBlockGetTerraformDerivedFixtureState = {' + $script:scriptBlockGetTerraformDerivedFixtureState.ToString() + "}`n" +
            '$script:scriptBlockInvokeTerraformTerminalCandidateProbe = {' + $script:scriptBlockInvokeTerraformTerminalCandidateProbe.ToString() + "}`n" +
            '& {' + $script:scriptBlockTerraformInProgressWorker.ToString() + '} -Roles $Roles -FixtureRoot $FixtureRoot'
        [System.IO.File]::WriteAllText($strWorkerPath, $strWorkerSource, (New-Object System.Text.UTF8Encoding($false)))
        $hashtableWorker = & $script:scriptBlockStartTerraformProofProcess -ScriptPath $strWorkerPath `
            -WorkingDirectory $hashtableLayout.CaseRoot -Arguments @('-Roles', $strRoles, '-FixtureRoot', $hashtableLayout.Trusted)
        while (-not (& $script:scriptBlockReceiveTerraformProofProcess -Worker $hashtableWorker)) { [System.Threading.Thread]::Sleep(10) }
        if ($hashtableWorker.Process.ExitCode -ne 0) { throw 'in-progress-worker-failed' }
        $arrObserved = @(& $script:scriptBlockReadTerraformProofResult -LiteralPath ([System.IO.Path]::Combine($hashtableLayout.Trusted, 'result.json')))
        if ($arrObserved.Count -ne 2 -or $arrObserved[0].Mode -cne 'control' -or $arrObserved[0].CandidateState -cne 'Disposed' -or
            $arrObserved[1].Mode -cne 'in-progress' -or $arrObserved[1].CandidateState -cne 'RetainedUncertain' -or
            $arrObserved[1].ContextState -cne 'RetainedUncertain' -or $arrObserved[1].RemovedCount -ne 0 -or
            $arrObserved[1].ContextRemovedCount -ne 0) { throw 'in-progress-worker-observations' }
        $objObserved = $arrObserved[1].ReentrantObservation
        return [pscustomobject][ordered]@{
            ActualInitialState = $objObserved.ActualInitialState
            InitialStateObservationScope = 'authenticated-candidate-lifecycle'
            ObservationScope = 'actual-production-transition-with-reentrant-public-cleanup'
            PrimaryFailureSupplied = $false
            ActualResult = 'rejection'; ActualStatus = 1; ActualPhase = $objObserved.Phase; ActualSubreason = $objObserved.Subreason
            ActualPreCleanupCandidateState = 'uncertain-retained'; ActualCandidateState = 'uncertain-retained'
            ActualContextState = $arrObserved[1].ContextState
            ActualCleanupSequence = [string[]]@('candidate-cleanup', 'context-cleanup')
            ActualSentinelState = if (& $script:scriptBlockTestSentinelIntact -Layout $hashtableLayout) { 'unchanged' } else { 'changed' }
            ActualLabels = [pscustomobject]@{ ArtifactId = 'not-emitted'; RunId = 'not-emitted'; RunAttempt = 'not-emitted' }
            LabelExposure = 'not-emitted'
            CandidateLifecycleState = $arrObserved[1].CandidateState
            ProviderCalls = $objObserved.ProviderCalls; PathCalls = $objObserved.PathCalls
            FilesystemCalls = $objObserved.FilesystemCalls; NativeCalls = $objObserved.NativeCalls
            SameObject = $objObserved.SameObject; SameJournal = $objObserved.SameJournal
            SameSummary = $objObserved.SameSummary; SameAttempt = $objObserved.SameAttempt
            ZeroCallProofScope = 'finite-reviewed-static-closure-and-private-boundary-spies'
            HelperSourceSha256 = $strSourceHash
            DerivedHelperSha256 = $strDerivedHash
            WorkerExit = $hashtableWorker.Process.ExitCode
            TransformationId = 'private-module-state-and-active-transition-reentrant-hook-v2'
            ParserErrors = 0
            NoContentionControlPassed = $arrObserved[0].CandidateState -ceq 'Disposed' -and $arrObserved[0].RemovedCount -eq 5 -and $arrObserved[0].ContextState -ceq 'Disposed'
            OuterAbortRetainedWithoutDeletion = $arrObserved[1].CandidateState -ceq 'RetainedUncertain' -and $arrObserved[1].RemovedCount -eq 0 -and $arrObserved[1].ContextRemovedCount -eq 0
        }
    } finally {
        if ($null -ne $hashtableWorker) { & $script:scriptBlockStopTerraformProofProcess -Worker $hashtableWorker }
        & $script:scriptBlockRemoveTestTree -LiteralPath $hashtableLayout.CaseRoot -ApprovedParent $RunRoot
    }
}

$script:scriptBlockTerraformContextAdoptionWorker = {
    param ([string]$Roles, [string]$FixtureRoot, [string]$Mode)

    Set-StrictMode -Version Latest
    $ErrorActionPreference = 'Stop'
    . ([System.IO.Path]::Combine($Roles, 'Manage-StyleGuideCandidateInvocationContext.ps1'))
    $hashtableTask184FixtureState = & $script:scriptBlockGetTerraformDerivedFixtureState -Roles $Roles -Role context
    $listResults = New-Object 'System.Collections.Generic.List[pscustomobject]'
    $arrModes = if ($Mode -ceq 'unreadable') { @('control', 'identity', 'unreadable') } else { @('control', 'missing') }
    foreach ($strMode in $arrModes) {
        $strParent = [System.IO.Path]::Combine($FixtureRoot, $strMode)
        [void][System.IO.Directory]::CreateDirectory($strParent)
        $objContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $strParent
        $strArchive = [System.IO.Path]::Combine($objContext.DownloadDirectoryPath, 'artifact.zip')
        $arrOriginal = [System.Text.Encoding]::UTF8.GetBytes('original')
        [System.IO.File]::WriteAllBytes($strArchive, $arrOriginal)
        $hashtableTask184FixtureState.Mode = $strMode
        $hashtableTask184FixtureState.Lock = $null
        $hashtableTask184FixtureState.Adopted = $false
        $hashtableTask184FixtureState.Unreadable = $false
        $strInitial = $objContext.LifecycleState
        $arrErrors = @()
        try {
            $objReturned = Remove-StyleGuideCandidateInvocationContext -Context $objContext -OwnedPaths ([object[]]@($strArchive)) -ErrorAction SilentlyContinue -ErrorVariable +arrErrors
        } finally {
            if ($null -ne $hashtableTask184FixtureState.Lock) { $hashtableTask184FixtureState.Lock.Dispose(); $hashtableTask184FixtureState.Lock = $null }
        }
        if (-not $hashtableTask184FixtureState.Adopted -or -not [object]::ReferenceEquals($objReturned, $objContext) -or $objContext.OwnershipJournal.Count -ne 3) { throw 'context-adoption-not-proven' }
        $strPhase = if ($arrErrors.Count -eq 0) { 'cleanup' } else { $arrErrors[-1].Exception.Data['TerraformStyleGuidePhase'] }
        $strReason = if ($arrErrors.Count -eq 0) { 'context-disposed' } else { $arrErrors[-1].Exception.Data['TerraformStyleGuideSubreason'] }
        if ($strMode -ceq 'control') {
            if ($arrErrors.Count -ne 0 -or $objContext.LifecycleState -cne 'Disposed' -or
                $objContext.CleanupSummary.RemovedPaths.Count -ne 3 -or [System.IO.Directory]::Exists($objContext.InvocationRootPath)) { throw 'context-adoption-control-failed' }
        } else {
            $strExpectedReason = switch -Exact ($strMode) {
                'missing' { 'context-entry-missing' }
                'unreadable' { 'context-entry-unreadable' }
                'identity' { 'context-state-retained' }
            }
            if ($arrErrors.Count -lt 1 -or $strPhase -cne 'cleanup' -or $strReason -cne $strExpectedReason -or
                $objContext.LifecycleState -cne 'RetainedUncertain' -or $objContext.CleanupSummary.RemovedPaths.Count -ne 0 -or
                -not [System.IO.Directory]::Exists($objContext.InvocationRootPath) -or -not [System.IO.Directory]::Exists($objContext.DownloadDirectoryPath)) { throw 'context-adoption-retention-failed' }
            if ($strMode -ceq 'missing') {
                if ([System.IO.File]::Exists($strArchive)) { throw 'context-adoption-file-not-missing' }
            } else {
                $strExpected = if ($strMode -ceq 'identity') { 'changed!' } else { 'original' }
                if ([System.IO.File]::ReadAllText($strArchive) -cne $strExpected) { throw 'context-adoption-file-changed' }
                if ($strMode -ceq 'unreadable' -and -not $hashtableTask184FixtureState.Unreadable) { throw 'context-adoption-unreadable-control' }
            }
        }
        $listResults.Add([pscustomobject]@{
            Mode = $strMode; InitialState = $strInitial; ContextState = $objContext.LifecycleState
            Phase = $strPhase; Subreason = $strReason; RemovedCount = $objContext.CleanupSummary.RemovedPaths.Count
            JournalCount = $objContext.OwnershipJournal.Count; AdoptionObserved = $hashtableTask184FixtureState.Adopted
            UnreadableControlObserved = $hashtableTask184FixtureState.Unreadable
            CandidateAbsent = -not [System.IO.File]::Exists($objContext.CandidateDirectoryPath) -and -not [System.IO.Directory]::Exists($objContext.CandidateDirectoryPath)
        })
    }
    [System.IO.File]::WriteAllText([System.IO.Path]::Combine($FixtureRoot, 'result.json'),
        (ConvertTo-Json -InputObject $listResults.ToArray() -Depth 6 -Compress), (New-Object System.Text.UTF8Encoding($false)))
}

$script:scriptBlockInvokeTerraformContextAdoptionCase = {
    param ([object]$Case, [string]$RunRoot, [string]$HelperLiteralPath, [string]$ContextLiteralPath)

    if ($Case.Id -cnotin @('T1A-C-05', 'T1A-C-09')) { throw 'context-adoption-case-id' }
    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    $hashtableWorker = $null
    try {
        $arrSource = [System.IO.File]::ReadAllBytes($ContextLiteralPath)
        $objHasher = [System.Security.Cryptography.SHA256]::Create()
        try { $strSourceHash = [System.BitConverter]::ToString($objHasher.ComputeHash($arrSource)).Replace('-', '').ToLowerInvariant() }
        finally { $objHasher.Dispose() }
        $strSource = (New-Object System.Text.UTF8Encoding($false, $true)).GetString($arrSource)
        $strMarker = '$objCleanup = & $scriptBlockRemoveContextFunction -Context $objRegistration.PrivateContext'
        if ([regex]::Matches($strSource, [regex]::Escape($strMarker)).Count -ne 1) { throw 'context-adoption-transform-cardinality' }
        $strHook = @'
$arrTask184ArchiveRecords = @($objRegistration.PrivateContext.OwnershipJournal | Where-Object { $_.Kind -ceq 'DownloadFile' -and $_.EntryState -ceq 'Created' })
if ($arrTask184ArchiveRecords.Count -ne 1 -or $Context.OwnershipJournal.Count -ne 3) { throw 'context-adoption-journal-boundary' }
$hashtableTask184FixtureState.Adopted = $true
$strTask184Archive = $arrTask184ArchiveRecords[0].Path
switch -Exact ($hashtableTask184FixtureState.Mode) {
    'control' { }
    'missing' { [System.IO.File]::Delete($strTask184Archive) }
    'identity' { [System.IO.File]::WriteAllText($strTask184Archive, 'changed!') }
    'unreadable' {
        $hashtableTask184FixtureState.Lock = [System.IO.File]::Open($strTask184Archive, [System.IO.FileMode]::Open, [System.IO.FileAccess]::ReadWrite, [System.IO.FileShare]::None)
        $objTask184ReadControl = $null
        try { $objTask184ReadControl = [System.IO.File]::Open($strTask184Archive, [System.IO.FileMode]::Open, [System.IO.FileAccess]::Read, [System.IO.FileShare]::Read) }
        catch [System.IO.IOException] { $hashtableTask184FixtureState.Unreadable = $true }
        finally { if ($null -ne $objTask184ReadControl) { $objTask184ReadControl.Dispose() } }
        if (-not $hashtableTask184FixtureState.Unreadable) { throw 'context-adoption-lock-not-effective' }
    }
    default { throw 'context-adoption-hook-mode' }
}
'@
        $strDerived = $strSource.Replace($strMarker, $strHook + "`n" + $strMarker)
        $strDerived = & $script:scriptBlockAddTerraformDerivedFixtureState -Source $strDerived -Role context
        $arrParseErrors = $null
        [void][System.Management.Automation.Language.Parser]::ParseInput($strDerived, [ref]$null, [ref]$arrParseErrors)
        if ($arrParseErrors.Count -ne 0) { throw 'context-adoption-derived-parse' }
        $arrDerived = (New-Object System.Text.UTF8Encoding($false, $true)).GetBytes($strDerived)
        $objHasher = [System.Security.Cryptography.SHA256]::Create()
        try { $strDerivedHash = [System.BitConverter]::ToString($objHasher.ComputeHash($arrDerived)).Replace('-', '').ToLowerInvariant() }
        finally { $objHasher.Dispose() }
        $strRoles = [System.IO.Path]::Combine($hashtableLayout.CaseRoot, 'roles')
        [void][System.IO.Directory]::CreateDirectory($strRoles)
        [System.IO.File]::WriteAllBytes([System.IO.Path]::Combine($strRoles, 'Manage-StyleGuideCandidateInvocationContext.ps1'), $arrDerived)
        [System.IO.File]::WriteAllBytes([System.IO.Path]::Combine($strRoles, 'Expand-StyleGuideCandidateArtifact.ps1'), [System.IO.File]::ReadAllBytes($HelperLiteralPath))
        $strWorkerPath = [System.IO.Path]::Combine($hashtableLayout.CaseRoot, 'worker.ps1')
        $strWorkerSource = "param ([string]`$Roles, [string]`$FixtureRoot, [string]`$Mode)`n" +
            '$script:scriptBlockGetTerraformDerivedFixtureState = {' + $script:scriptBlockGetTerraformDerivedFixtureState.ToString() + "}`n" +
            '& {' + $script:scriptBlockTerraformContextAdoptionWorker.ToString() + '} -Roles $Roles -FixtureRoot $FixtureRoot -Mode $Mode'
        [System.IO.File]::WriteAllText($strWorkerPath, $strWorkerSource, (New-Object System.Text.UTF8Encoding($false)))
        $strMode = if ($Case.Id -ceq 'T1A-C-05') { 'missing' } else { 'unreadable' }
        $hashtableWorker = & $script:scriptBlockStartTerraformProofProcess -ScriptPath $strWorkerPath -WorkingDirectory $hashtableLayout.CaseRoot `
            -Arguments @('-Roles', $strRoles, '-FixtureRoot', $hashtableLayout.Trusted, '-Mode', $strMode)
        while (-not (& $script:scriptBlockReceiveTerraformProofProcess -Worker $hashtableWorker)) { [System.Threading.Thread]::Sleep(10) }
        if ($hashtableWorker.Process.ExitCode -ne 0) { throw 'context-adoption-worker-failed' }
        $arrObserved = @(& $script:scriptBlockReadTerraformProofResult -LiteralPath ([System.IO.Path]::Combine($hashtableLayout.Trusted, 'result.json')))
        $intCount = if ($strMode -ceq 'missing') { 2 } else { 3 }
        if ($arrObserved.Count -ne $intCount -or $arrObserved[0].Mode -cne 'control' -or $arrObserved[0].ContextState -cne 'Disposed' -or
            $arrObserved[0].RemovedCount -ne 3 -or $arrObserved[-1].Mode -cne $strMode -or
            $arrObserved[-1].ContextState -cne 'RetainedUncertain' -or $arrObserved[-1].RemovedCount -ne 0 -or
            -not $arrObserved[-1].AdoptionObserved -or -not $arrObserved[-1].CandidateAbsent) { throw 'context-adoption-observation' }
        if ($strMode -ceq 'unreadable' -and ($arrObserved[1].Mode -cne 'identity' -or $arrObserved[1].Subreason -cne 'context-state-retained' -or
            -not $arrObserved[-1].UnreadableControlObserved)) { throw 'context-adoption-adjacent-control' }
        $objObserved = $arrObserved[-1]
        return [pscustomobject][ordered]@{
            ActualInitialState = $objObserved.InitialState; InitialStateObservationScope = 'issued-context-lifecycle'
            ObservationScope = 'actual-post-adoption-context-cleanup'
            PrimaryFailureSupplied = $false
            ActualResult = 'rejection'; ActualStatus = 1; ActualPhase = $objObserved.Phase; ActualSubreason = $objObserved.Subreason
            ActualPreCleanupCandidateState = 'absent'; ActualCandidateState = 'absent'; ActualContextState = $objObserved.ContextState
            ActualCleanupSequence = [string[]]@('context-cleanup')
            ActualSentinelState = if (& $script:scriptBlockTestSentinelIntact -Layout $hashtableLayout) { 'unchanged' } else { 'changed' }
            ActualLabels = [pscustomobject]@{ ArtifactId = 'not-emitted'; RunId = 'not-emitted'; RunAttempt = 'not-emitted' }; LabelExposure = 'not-emitted'
            RemovedCount = $objObserved.RemovedCount; JournalCount = $objObserved.JournalCount
            AdoptionObserved = $objObserved.AdoptionObserved; UnreadableControlObserved = $objObserved.UnreadableControlObserved
            ContextSourceSha256 = $strSourceHash; DerivedContextSha256 = $strDerivedHash
            TransformationId = 'private-module-state-single-post-adoption-pre-source-cleanup-hook-v2'; ParserErrors = $arrParseErrors.Count
            WorkerExit = $hashtableWorker.Process.ExitCode
            NoContentionControlPassed = $arrObserved[0].ContextState -ceq 'Disposed' -and $arrObserved[0].RemovedCount -eq 3
        }
    } finally {
        if ($null -ne $hashtableWorker) { & $script:scriptBlockStopTerraformProofProcess -Worker $hashtableWorker }
        & $script:scriptBlockRemoveTestTree -LiteralPath $hashtableLayout.CaseRoot -ApprovedParent $RunRoot
    }
}

$script:scriptBlockTerraformPartialContextWorker = {
    param ([string]$Roles, [string]$FixtureRoot)

    Set-StrictMode -Version Latest
    $ErrorActionPreference = 'Stop'
    . ([System.IO.Path]::Combine($Roles, 'Manage-StyleGuideCandidateInvocationContext.ps1'))
    $hashtableTask184FixtureState = & $script:scriptBlockGetTerraformDerivedFixtureState -Roles $Roles -Role context
    $hashtableTask184FixtureState.Fail = $false
    $objControl = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $FixtureRoot
    $objControl = Remove-StyleGuideCandidateInvocationContext -Context $objControl
    if ($objControl.LifecycleState -cne 'Disposed' -or $objControl.CleanupSummary.RemovedPaths.Count -ne 2) { throw 'partial-context-public-control' }
    $hashtableTask184FixtureState.Observed = @{}
    $hashtableTask184FixtureState.Fail = $true
    $objPublic = $null
    $objCreationError = $null
    try { $objPublic = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $FixtureRoot }
    catch { $objCreationError = $_ }
    $hashtableObserved = $hashtableTask184FixtureState.Observed
    if ($null -ne $objPublic -or $null -eq $objCreationError -or
        $objCreationError.Exception.Data['PSStyleGuideDiagnosticCode'] -cne 'context-create-composite-failure' -or
        -not $hashtableObserved.CleanupSuccess -or $hashtableObserved.PreviousState -cne 'Active' -or
        $hashtableObserved.FinalState -cne 'Disposed' -or $hashtableObserved.DiagnosticCode -cne 'cleanup-succeeded' -or
        $hashtableObserved.RootRecordAfter -cne 'Deleted' -or $hashtableObserved.DownloadRecordAfter -cne 'ExpectedAbsent' -or
        -not $hashtableObserved.Deregistered -or [System.IO.Directory]::Exists($hashtableObserved.RootPath) -or
        [System.IO.File]::Exists($hashtableObserved.CandidatePath) -or [System.IO.Directory]::Exists($hashtableObserved.CandidatePath) -or
        [System.IO.File]::Exists($hashtableObserved.DownloadPath) -or [System.IO.Directory]::Exists($hashtableObserved.DownloadPath)) { throw 'partial-context-rollback-outcome' }
    $objResult = [pscustomobject]@{
        ActualInitialState = $hashtableObserved.InitialState
        ActualContextState = $hashtableObserved.FinalState
        SourceCleanupCode = $hashtableObserved.DiagnosticCode
        CleanupSuccess = $hashtableObserved.CleanupSuccess
        PublicContextIssued = $null -ne $objPublic
        OuterCreationRejected = $null -ne $objCreationError
        Deregistered = $hashtableObserved.Deregistered
        JournalCount = $hashtableObserved.JournalCount
        CreatedRecordCount = $hashtableObserved.CreatedRecordCount
        RemovedCount = [int]($hashtableObserved.RootRecordAfter -ceq 'Deleted')
        ReservedEntriesAbsent = $true
        NoContentionControlPassed = $objControl.LifecycleState -ceq 'Disposed'
    }
    [System.IO.File]::WriteAllText([System.IO.Path]::Combine($FixtureRoot, 'result.json'),
        (ConvertTo-Json -InputObject $objResult -Depth 5 -Compress), (New-Object System.Text.UTF8Encoding($false)))
}

$script:scriptBlockInvokeTerraformPartialContextCase = {
    param ([object]$Case, [string]$RunRoot, [string]$HelperLiteralPath, [string]$ContextLiteralPath)

    if ($Case.Id -cne 'T1A-C-07') { throw 'partial-context-case-id' }
    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    $hashtableWorker = $null
    try {
        $arrSource = [System.IO.File]::ReadAllBytes($ContextLiteralPath)
        $objHasher = [System.Security.Cryptography.SHA256]::Create()
        try { $strSourceHash = [System.BitConverter]::ToString($objHasher.ComputeHash($arrSource)).Replace('-', '').ToLowerInvariant() }
        finally { $objHasher.Dispose() }
        $strSource = (New-Object System.Text.UTF8Encoding($false, $true)).GetString($arrSource)
        $strCreate = '$null = [System.IO.Directory]::CreateDirectory($strDownloadDirectory)'
        $strRemove = '$objCleanupResult = & $scriptBlockRemoveContextFunction -Context $objContext'
        $strDeregister = '& $scriptBlockDeregisterCandidateContext -Context $objContext'
        foreach ($strMarker in @($strCreate, $strRemove)) {
            if ([regex]::Matches($strSource, [regex]::Escape($strMarker)).Count -ne 1) { throw 'partial-context-transform-cardinality' }
        }
        # Two deregistration sites exist. Only the first, following genuine
        # filesystem rollback, is the bounded target of this observation.
        $intDeregister = $strSource.IndexOf($strDeregister, $strSource.IndexOf($strRemove), [System.StringComparison]::Ordinal)
        if ($intDeregister -lt 0) { throw 'partial-context-deregister-anchor' }
        $strAfterDeregister = @'

if ($hashtableTask184FixtureState.Fail) {
    $hashtableTask184FixtureState.Observed.Deregistered = (& $scriptBlockCandidateContextIssuedIndex -Context $objContext) -eq -1
}
'@
        $strDerived = $strSource.Insert($intDeregister + $strDeregister.Length, $strAfterDeregister)
        $strBeforeCreate = @'
if ($hashtableTask184FixtureState.Fail) {
    if ($objContext.LifecycleState -cne 'Active' -or $objContext.OwnershipJournal.Count -ne 3 -or
        $objContext.OwnershipJournal[0].EntryState -cne 'Created' -or
        $objContext.OwnershipJournal[1].EntryState -cne 'ExpectedAbsent' -or
        $objContext.OwnershipJournal[2].EntryState -cne 'ExpectedAbsent' -or
        $arrClaimEntries.Count -ne 0) { throw 'partial-context-genuine-journal' }
    $hashtableTask184FixtureState.Observed.InitialState = $objContext.LifecycleState
    $hashtableTask184FixtureState.Observed.RootPath = $objContext.InvocationRootPath
    $hashtableTask184FixtureState.Observed.DownloadPath = $objContext.DownloadDirectoryPath
    $hashtableTask184FixtureState.Observed.CandidatePath = $objContext.CandidatePath
    $hashtableTask184FixtureState.Observed.JournalCount = $objContext.OwnershipJournal.Count
    $hashtableTask184FixtureState.Observed.CreatedRecordCount = @($objContext.OwnershipJournal | Where-Object EntryState -CEQ 'Created').Count
    throw 'partial-context-controlled-before-download-create'
}
'@
        $strDerived = $strDerived.Replace($strCreate, $strBeforeCreate + "`n" + $strCreate)
        $strAfterRemove = @'

if ($hashtableTask184FixtureState.Fail) {
    $hashtableTask184FixtureState.Observed.CleanupSuccess = $objCleanupResult.Success
    $hashtableTask184FixtureState.Observed.PreviousState = $objCleanupResult.PreviousState
    $hashtableTask184FixtureState.Observed.FinalState = $objCleanupResult.FinalState
    $hashtableTask184FixtureState.Observed.DiagnosticCode = $objCleanupResult.DiagnosticCode
    $hashtableTask184FixtureState.Observed.RootRecordAfter = $objContext.OwnershipJournal[0].EntryState
    $hashtableTask184FixtureState.Observed.DownloadRecordAfter = $objContext.OwnershipJournal[1].EntryState
}
'@
        $strDerived = $strDerived.Replace($strRemove, $strRemove + $strAfterRemove)
        $strDerived = & $script:scriptBlockAddTerraformDerivedFixtureState -Source $strDerived -Role context
        $arrParseErrors = $null
        [void][System.Management.Automation.Language.Parser]::ParseInput($strDerived, [ref]$null, [ref]$arrParseErrors)
        if ($arrParseErrors.Count -ne 0) { throw 'partial-context-derived-parse' }
