$script:scriptBlockInvokeTerraformTerminalContextProbe = {
    param ([object]$State)
        $objModule = Microsoft.PowerShell.Core\Get-Module -Name TerraformStyleGuideCandidateContext_1_0_20260924_1 -All
        return & $objModule {
            param ([object]$State)
            $hashtableCounts = @{ Provider = 0; Path = 0; Filesystem = 0; Native = 0 }
            $hashtableBoundaries = @{
                Provider = 'scriptBlockResolveCandidateExistingDirectory'
                Path = 'scriptBlockAssertCandidateCanonicalStoredPath'
                Filesystem = 'scriptBlockAssertCandidateOrdinaryDirectoryEnvelope'
                Native = 'scriptBlockResolveCandidateNativePath'
            }
            $hashtableSaved = @{}
            try {
                foreach ($strCategory in $hashtableBoundaries.Keys) {
                    $strName = $hashtableBoundaries[$strCategory]
                    $objVariable = Microsoft.PowerShell.Utility\Get-Variable -Name $strName -Scope Script -ErrorAction Stop
                    $hashtableSaved[$strName] = $objVariable.Value
                    $scriptBlockSpy = {
                        $hashtableCounts[$strCategory]++
                        throw 'terminal-boundary-spy-called'
                    }.GetNewClosure()
                    Microsoft.PowerShell.Utility\Set-Variable -Name $strName -Scope Script -Value $scriptBlockSpy
                    try { & $scriptBlockSpy } catch {
                        if ($_.Exception.Message -cne 'terminal-boundary-spy-called') { throw }
                    }
                    if ($hashtableCounts[$strCategory] -ne 1) { throw 'terminal-spy-control' }
                    $hashtableCounts[$strCategory] = 0
                }
                $arrErrors = @()
                $objReturned = Remove-StyleGuideCandidateInvocationContext -Context $State -ErrorAction SilentlyContinue -ErrorVariable +arrErrors
                [pscustomobject]@{ Returned = $objReturned; Counts = $hashtableCounts; Errors = [object[]]$arrErrors }
            } finally {
                foreach ($strName in $hashtableSaved.Keys) {
                    Microsoft.PowerShell.Utility\Set-Variable -Name $strName -Scope Script -Value $hashtableSaved[$strName]
                }
            }
        } $State
}

$script:scriptBlockInvokeTerraformCombinedCleanupCase = {
    param ([object]$Case, [string]$RunRoot, [string]$HelperLiteralPath, [string]$ContextLiteralPath)

    if ($Case.Id -cnotin @('T1A-C-08', 'T1A-AF-07')) { throw 'combined-cleanup-case-id' }
    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    try {
        $objContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $hashtableLayout.Trusted
        $strArchive = [System.IO.Path]::Combine($objContext.DownloadDirectoryPath, 'artifact.zip')
        $objArchive = & $script:scriptBlockNewZipFixture -LiteralPath $strArchive -SemanticCase 'archive.valid.exact'
        $objResult = & $HelperLiteralPath -CheckoutRoot $hashtableLayout.Checkout -TrustedTemporaryRoot $hashtableLayout.Trusted `
            -DownloadDirectory $objContext.DownloadDirectoryPath -CandidateDirectory $objContext.CandidateDirectoryPath -ExpectedDigest $objArchive.Sha256
        & $script:scriptBlockAssertTerraformExpandedFiles -Result $objResult -CandidatePath $objContext.CandidateDirectoryPath -ArchivePath $strArchive
        $strInitial = $objContext.LifecycleState
        $listCalls = New-Object 'System.Collections.Generic.List[string]'
        $listCalls.Add('candidate-cleanup')
        $objCandidate = Remove-StyleGuideCandidateInvocationState -CandidateOwnershipState $objResult.CandidateOwnershipState
        if ($objCandidate.LifecycleState -cne 'Disposed' -or $objCandidate.CleanupSummary.RemovedPaths.Count -ne 5) { throw 'combined-candidate-not-disposed' }
        $strBefore = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $objContext.CandidateDirectoryPath
        $listCalls.Add('context-cleanup')
        $objContext = Remove-StyleGuideCandidateInvocationContext -Context $objContext -OwnedPaths ([object[]]@($strArchive)) -CandidateOwnershipState $objCandidate
        if ($objContext.LifecycleState -cne 'Disposed' -or $objContext.CleanupSummary.RemovedPaths.Count -ne 3) { throw 'combined-context-not-disposed' }
        $objCandidateRepeat = $null
        $objContextRepeat = $null
        $boolIdentity = $true
        if ($Case.Id -ceq 'T1A-AF-07') {
            & $script:scriptBlockAssertTerminalCapabilityClosure -Source ([System.IO.File]::ReadAllText($HelperLiteralPath)) -Role helper
            & $script:scriptBlockAssertTerminalCapabilityClosure -Source ([System.IO.File]::ReadAllText($ContextLiteralPath)) -Role context
            $strInitial = $objContext.LifecycleState
            $objContextSummary = $objContext.CleanupSummary
            $objContextJournal = $objContext.OwnershipJournal
            $uintContextAttempt = $objContext.CleanupSummary.Attempts
            $objCandidateSummary = $objCandidate.CleanupSummary
            $objCandidateJournal = $objCandidate.OwnershipJournal
            $uintCandidateAttempt = $objCandidate.CleanupAttempt
            $listCalls.Clear()
            $listCalls.Add('candidate-cleanup-noop')
            $objCandidateRepeat = & $script:scriptBlockInvokeTerraformTerminalCandidateProbe -State $objCandidate
            $listCalls.Add('context-cleanup-noop')
            $objContextRepeat = & $script:scriptBlockInvokeTerraformTerminalContextProbe -State $objContext
            foreach ($strCategory in @('Provider', 'Path', 'Filesystem', 'Native')) {
                if ($objCandidateRepeat.Counts[$strCategory] -ne 0 -or $objContextRepeat.Counts[$strCategory] -ne 0) { throw 'combined-terminal-boundary-called' }
            }
            $boolIdentity = [object]::ReferenceEquals($objCandidateRepeat.Returned, $objCandidate) -and
                [object]::ReferenceEquals($objContextRepeat.Returned, $objContext) -and
                [object]::ReferenceEquals($objCandidate.CleanupSummary, $objCandidateSummary) -and
                [object]::ReferenceEquals($objContext.CleanupSummary, $objContextSummary) -and
                [object]::ReferenceEquals($objCandidate.OwnershipJournal, $objCandidateJournal) -and
                [object]::ReferenceEquals($objContext.OwnershipJournal, $objContextJournal) -and
                $objCandidate.CleanupAttempt -eq $uintCandidateAttempt -and $objContext.CleanupSummary.Attempts -eq $uintContextAttempt
            if (-not $boolIdentity -or $objCandidateRepeat.Errors.Count -ne 0 -or $objContextRepeat.Errors.Count -ne 0 -or
                $objContext.LifecycleState -cne 'Disposed' -or $objCandidate.LifecycleState -cne 'Disposed') { throw 'combined-terminal-capability-changed' }
        }
        $strAfter = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $objContext.CandidateDirectoryPath
        if ($strBefore -cne 'absent' -or $strAfter -cne 'absent' -or
            (& $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $objContext.InvocationRootPath) -cne 'absent') { throw 'combined-physical-state' }
        return [pscustomobject][ordered]@{
            ActualInitialState = $strInitial; InitialStateObservationScope = 'issued-context-lifecycle'
            PrimaryFailureSupplied = $false
            ActualResult = 'success'; ActualStatus = 0; ActualPhase = 'cleanup'
            ActualSubreason = if ($null -eq $objContextRepeat) { 'context-disposed' } else { 'context-already-disposed' }
            ActualPreCleanupCandidateState = $strBefore; ActualCandidateState = $strAfter
            ActualContextState = $objContext.LifecycleState; ActualCleanupSequence = $listCalls.ToArray()
            ActualSentinelState = if (& $script:scriptBlockTestSentinelIntact -Layout $hashtableLayout) { 'unchanged' } else { 'changed' }
            ActualLabels = [pscustomobject]@{ ArtifactId = 'not-emitted'; RunId = 'not-emitted'; RunAttempt = 'not-emitted' }; LabelExposure = 'not-emitted'
            PreCleanupObservationScope = 'before-context-cleanup-after-candidate-release'
            CandidateLifecycleState = $objCandidate.LifecycleState
            SameObject = if ($null -ne $objContextRepeat) { $boolIdentity } else { $null }
            SameJournal = if ($null -ne $objContextRepeat) { $boolIdentity } else { $null }
            SameSummary = if ($null -ne $objContextRepeat) { $boolIdentity } else { $null }
            SameAttempt = if ($null -ne $objContextRepeat) { $boolIdentity } else { $null }
            ProviderCalls = if ($null -ne $objContextRepeat) { $objContextRepeat.Counts.Provider + $objCandidateRepeat.Counts.Provider } else { $null }
            PathCalls = if ($null -ne $objContextRepeat) { $objContextRepeat.Counts.Path + $objCandidateRepeat.Counts.Path } else { $null }
            FilesystemCalls = if ($null -ne $objContextRepeat) { $objContextRepeat.Counts.Filesystem + $objCandidateRepeat.Counts.Filesystem } else { $null }
            NativeCalls = if ($null -ne $objContextRepeat) { $objContextRepeat.Counts.Native + $objCandidateRepeat.Counts.Native } else { $null }
            ZeroCallProofScope = if ($null -ne $objContextRepeat) { 'finite-reviewed-static-closure-and-private-boundary-spies' } else { $null }
        }
    } finally {
        & $script:scriptBlockRemoveTestTree -LiteralPath $hashtableLayout.CaseRoot -ApprovedParent $RunRoot
    }
}

$script:scriptBlockTerraformMissingArchiveWorker = {
    param ([string]$Roles, [string]$FixtureRoot)

    Set-StrictMode -Version Latest
    $ErrorActionPreference = 'Stop'
    . ([System.IO.Path]::Combine($Roles, 'Manage-StyleGuideCandidateInvocationContext.ps1'))
