        $strCheckout = [System.IO.Path]::Combine($strRoot, 'checkout')
        $strTrusted = [System.IO.Path]::Combine($strRoot, 'trusted')
        [void][System.IO.Directory]::CreateDirectory($strCheckout)
        [void][System.IO.Directory]::CreateDirectory($strTrusted)
        $objContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $strTrusted
        $strArchive = [System.IO.Path]::Combine($objContext.DownloadDirectoryPath, 'artifact.zip')
        $objZip = [System.IO.Compression.ZipFile]::Open($strArchive, [System.IO.Compression.ZipArchiveMode]::Create)
        try {
            foreach ($strName in @('copilot-instructions.md', 'terraform.instructions.md', 'STYLE_GUIDE_CHAT.md', 'STYLE_GUIDE_FULL.md')) {
                $objStream = $objZip.CreateEntry($strName).Open()
                try {
                    $arrBytes = [System.Text.Encoding]::UTF8.GetBytes("fixture`n")
                    $objStream.Write($arrBytes, 0, $arrBytes.Length)
                } finally { $objStream.Dispose() }
            }
        } finally { $objZip.Dispose() }
        $strDigest = (Microsoft.PowerShell.Utility\Get-FileHash -LiteralPath $strArchive -Algorithm SHA256).Hash
        $hashtableTask184FixtureState.RemoveArchive = $boolMissing
        $hashtableTask184FixtureState.Captured = $false
        $objFailure = $null
        $objResult = $null
        try {
            $objResult = & $strHelper -CheckoutRoot $strCheckout -TrustedTemporaryRoot $strTrusted `
                -DownloadDirectory $objContext.DownloadDirectoryPath -CandidateDirectory $objContext.CandidateDirectoryPath -ExpectedDigest $strDigest
        } catch { $objFailure = $_ }
        $hashtableCleanup = @{ Context = $objContext }
        if ($boolMissing) {
            if (-not $hashtableTask184FixtureState.Captured -or $null -eq $objFailure -or
                $objFailure.Exception.Data['TerraformStyleGuidePhase'] -cne 'download' -or
                $objFailure.Exception.Data['TerraformStyleGuideSubreason'] -cne 'archive-missing' -or
                [System.IO.File]::Exists($strArchive)) { throw 'missing-archive-refusal' }
            $objCandidate = $objFailure.Exception.Data['CandidateOwnershipState']
            if ($objCandidate.LifecycleState -cne 'Disposed' -or $objCandidate.CleanupAttempt -ne 1 -or
                $objCandidate.OwnershipJournal.Count -ne 0 -or
                -not [object]::ReferenceEquals($objCandidate.CleanupSummary.PrimaryFailure, $objFailure.Exception.Data['PrimaryFailure'])) { throw 'missing-archive-candidate-cleanup' }
            $hashtableCleanup.PrimaryFailure = $objFailure
        } else {
            if ($null -ne $objFailure -or $objResult.CandidatePaths.Count -ne 4) { throw 'missing-archive-valid-control' }
            $objCandidate = Remove-StyleGuideCandidateInvocationState -CandidateOwnershipState $objResult.CandidateOwnershipState
            $hashtableCleanup.OwnedPaths = [object[]]@($strArchive)
        }
        $hashtableCleanup.CandidateOwnershipState = $objCandidate
        $objContext = Remove-StyleGuideCandidateInvocationContext @hashtableCleanup
        if ($objContext.LifecycleState -cne 'Disposed' -or [System.IO.Directory]::Exists($objContext.InvocationRootPath)) { throw 'missing-archive-context-cleanup' }
        if ($boolMissing -and -not [object]::ReferenceEquals($objContext.CleanupSummary.PrimaryFailure, $objFailure)) { throw 'missing-archive-primary-not-preserved' }
        $hashtableLabels = [ordered]@{ ArtifactId = 'not-emitted'; RunId = 'not-emitted'; RunAttempt = 'not-emitted' }
        if ($null -ne $objFailure) {
            foreach ($strLabel in @($hashtableLabels.Keys)) { $hashtableLabels[$strLabel] = $objFailure.Exception.Data['Diagnostics'].PSObject.Properties[$strLabel].Value }
        }
        $listResults.Add([pscustomobject]@{
            Missing = $boolMissing; ContextState = $objContext.LifecycleState; CandidateState = $objCandidate.LifecycleState
            Phase = if ($null -eq $objFailure) { 'complete' } else { $objFailure.Exception.Data['TerraformStyleGuidePhase'] }
            Subreason = if ($null -eq $objFailure) { 'none' } else { $objFailure.Exception.Data['TerraformStyleGuideSubreason'] }
            Labels = [pscustomobject]$hashtableLabels
            RetainedArchiveCaptured = $hashtableTask184FixtureState.Captured
            CandidateAcquiredCount = $objCandidate.OwnershipJournal.Count
            AutomaticPrimaryPreserved = if ($null -eq $objFailure) { $false } else { [object]::ReferenceEquals($objCandidate.CleanupSummary.PrimaryFailure, $objFailure.Exception.Data['PrimaryFailure']) }
        })
    }
    [System.IO.File]::WriteAllText([System.IO.Path]::Combine($FixtureRoot, 'result.json'),
        (ConvertTo-Json -InputObject $listResults.ToArray() -Depth 6 -Compress), (New-Object System.Text.UTF8Encoding($false)))
