        if ($objCandidate.LifecycleState -cne 'Disposed' -or $objContext.LifecycleState -cne 'Disposed' -or -not $boolFourFiles) { throw 'accepted-script-cleanup' }
        $strPhysical = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $objContext.CandidateDirectoryPath
        $objHelperAfter = & $script:scriptBlockGetFileEvidence -LiteralPath $strHelper
        $objContextAfter = & $script:scriptBlockGetFileEvidence -LiteralPath $strContext
