        $strDerived = $strSource.Replace($strMarker, $strMarker + $strBridge)
        $strDerivedPath = [System.IO.Path]::Combine($strRoles, 'Expand-StyleGuideCandidateArtifact.ps1')
        $strManagerPath = [System.IO.Path]::Combine($strRoles, 'Manage-StyleGuideCandidateInvocationContext.ps1')
        [System.IO.File]::WriteAllText($strDerivedPath, $strDerived, (New-Object System.Text.UTF8Encoding($false)))
        [System.IO.File]::WriteAllBytes($strManagerPath, [System.IO.File]::ReadAllBytes($ContextLiteralPath))
        $strWorkerPath = [System.IO.Path]::Combine($strRoot, 'worker.ps1')
        $strWorkerSource = "param ([string]`$Roles, [string]`$FixtureRoot)`n" +
            '$script:scriptBlockInitializeTerraformWorkerCompression = {' + $script:scriptBlockInitializeTerraformWorkerCompression.ToString() + "}`n" +
            '& $script:scriptBlockInitializeTerraformWorkerCompression' + "`n" +
            '& {' + $script:scriptBlockTerraformH02Worker.ToString() + '} -Roles $Roles -FixtureRoot $FixtureRoot'
        [System.IO.File]::WriteAllText($strWorkerPath, $strWorkerSource, (New-Object System.Text.UTF8Encoding($false)))
        $arrSentinel = [System.Text.Encoding]::UTF8.GetBytes("h02-competing-sentinel`n")
        $listRecords = New-Object 'System.Collections.Generic.List[pscustomobject]'
        foreach ($strCase in @('control', 'perturbation')) {
            $strCaseRoot = [System.IO.Path]::Combine($strRoot, $strCase)
            [void][System.IO.Directory]::CreateDirectory($strCaseRoot)
            [System.IO.File]::Delete($strReady)
            [System.IO.File]::Delete($strRelease)
            $hashtableWorker = & $script:scriptBlockStartTerraformProofProcess -ScriptPath $strWorkerPath `
                -WorkingDirectory $strCaseRoot -Arguments @('-Roles', $strRoles, '-FixtureRoot', $strCaseRoot)
            while (-not [System.IO.File]::Exists($strReady)) {
                if (& $script:scriptBlockReceiveTerraformProofProcess -Worker $hashtableWorker) {
                    & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'h02-worker-before-ready'
                }
                [System.Threading.Thread]::Sleep(10)
            }
            $objSetup = & $script:scriptBlockReadTerraformProofResult -LiteralPath ([System.IO.Path]::Combine($strCaseRoot, 'setup.json'))
            $strCandidate = [System.IO.Path]::GetFullPath([string]$objSetup.Candidate)
            if (-not $strCandidate.StartsWith($strCaseRoot + [System.IO.Path]::DirectorySeparatorChar, $script:objCandidatePathComparison) -or
                [System.IO.Path]::GetFileName($strCandidate) -cne 'candidate' -or
                $objSetup.ProcessId -ne $hashtableWorker.Process.Id -or $objSetup.ProcessId -eq $PID) {
                & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'h02-worker-setup'
            }
            $objAttributes = [System.IO.File]::GetAttributes($strCandidate)
            if (($objAttributes -band [System.IO.FileAttributes]::ReparsePoint) -ne 0 -or
                ($objAttributes -band [System.IO.FileAttributes]::Directory) -eq 0 -or
                [System.IO.Directory]::GetFileSystemEntries($strCandidate).Count -ne 0) {
                & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'h02-not-empty-at-ready'
            }
            if ($strCase -ceq 'perturbation') {
                $objStream = New-Object System.IO.FileStream(
                    [System.IO.Path]::Combine($strCandidate, 'competing-sentinel'),
                    [System.IO.FileMode]::CreateNew, [System.IO.FileAccess]::Write, [System.IO.FileShare]::None)
                try { $objStream.Write($arrSentinel, 0, $arrSentinel.Length) }
                finally { $objStream.Dispose() }
            }
            [System.IO.File]::WriteAllText($strRelease, 'release')
            while (-not (& $script:scriptBlockReceiveTerraformProofProcess -Worker $hashtableWorker)) {
                [System.Threading.Thread]::Sleep(10)
            }
            if ($hashtableWorker.Process.ExitCode -ne 0) {
                & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'h02-worker-failed'
            }
            $objObserved = & $script:scriptBlockReadTerraformProofResult -LiteralPath ([System.IO.Path]::Combine($strCaseRoot, 'result.json'))
            if ($objObserved.ParserErrors -ne 0 -or $objObserved.WorkerProcessId -ne $hashtableWorker.Process.Id) {
                & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'h02-result-identity'
            }
            if ($strCase -ceq 'control') {
                if ($objObserved.Phase -cne 'complete' -or $objObserved.Subreason -cne 'none' -or
                    $objObserved.CandidateState -cne 'Disposed' -or $objObserved.ContextState -cne 'Disposed' -or
                    $null -ne $objObserved.SentinelBytes) {
                    & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'h02-control'
                }
            } elseif ($objObserved.Phase -cne 'destination' -or $objObserved.Subreason -cne 'pre-journal-populated' -or
                $objObserved.CandidateState -cne 'RetainedUncertain' -or $objObserved.ContextState -cne 'RetainedUncertain' -or
                $objObserved.SentinelBytes -cne [System.Convert]::ToBase64String($arrSentinel) -or
                $objObserved.CandidateRemovedPaths.Count -ne 0 -or $objObserved.ContextRemovedPaths.Count -ne 0) {
                & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'h02-perturbation'
            }
            $listRecords.Add([pscustomobject][ordered]@{
                Case = $strCase; ReadyObserved = $true; ReleasedAfterWrite = $strCase -ceq 'perturbation'
                WriterProcessId = $PID; WorkerProcessId = $hashtableWorker.Process.Id; WorkerExit = $hashtableWorker.Process.ExitCode
                Observation = $objObserved
            })
            & $script:scriptBlockStopTerraformProofProcess -Worker $hashtableWorker
            $hashtableWorker = $null
        }
        $objResult = [pscustomobject][ordered]@{
            Id = 'T1A-H-02'; SemanticCase = 'harness.race.pre-journal-population-retained'
            ActualStatus = 0; ActualPhase = 'harness-proof'; SourceIdentity = $SourceIdentity
            HelperSourceSha256 = (& $script:scriptBlockGetFileEvidence -LiteralPath $HelperLiteralPath).Sha256
            ContextSourceSha256 = (& $script:scriptBlockGetFileEvidence -LiteralPath $ContextLiteralPath).Sha256
            DerivedHelperSha256 = (& $script:scriptBlockGetFileEvidence -LiteralPath $strDerivedPath).Sha256
            DerivedContextSha256 = (& $script:scriptBlockGetFileEvidence -LiteralPath $strManagerPath).Sha256
            Transformation = 'one-candidate-create-anchor-append-ready-release-before-next-statement-v1'
            Records = $listRecords.ToArray()
        }
    } finally {
        & $script:scriptBlockStopTerraformProofProcess -Worker $hashtableWorker
        & $script:scriptBlockRemoveTestTree -LiteralPath $strRoot -ApprovedParent $RunRoot
    }
    return $objResult
}

$script:scriptBlockNewTerraformCaseResult = {
    param (
        [object]$Case,
        [object]$Observation,
        [System.Collections.IDictionary]$Runtime,
        [bool]$SourceIntegrityVerified
    )

    if ($null -ne $Observation -and $Observation.ActualResult -ceq 'skip') {
        return & $script:scriptBlockNewTerraformPrimitiveSkipResult -Case $Case -Observation $Observation -Runtime $Runtime -SourceIntegrityVerified $SourceIntegrityVerified
    }
    $listFailures = New-Object 'System.Collections.Generic.List[string]'
    $hashtableActual = [ordered]@{}
    $hashtableFields = [ordered]@{
        InitialState = 'ActualInitialState'
        ExpectedResult = 'ActualResult'
        ExpectedStatus = 'ActualStatus'
        ExpectedPhase = 'ActualPhase'
        ExpectedSubreason = 'ActualSubreason'
        PreCleanupCandidateState = 'ActualPreCleanupCandidateState'
        FinalCandidateState = 'ActualCandidateState'
        FinalContextState = 'ActualContextState'
        CleanupSequence = 'ActualCleanupSequence'
        SentinelState = 'ActualSentinelState'
    }
    foreach ($strExpected in $hashtableFields.Keys) {
        $strActual = $hashtableFields[$strExpected]
        $objProperty = if ($null -eq $Observation) { $null } else { $Observation.PSObject.Properties[$strActual] }
        if ($null -eq $objProperty) {
            $listFailures.Add('missing-' + $strActual)
            $hashtableActual[$strActual] = $null
            continue
        }
        $hashtableActual[$strActual] = $objProperty.Value
        $strActualJson = & $script:scriptBlockConvertToCanonicalCatalogJson -Value $objProperty.Value
        $strExpectedJson = & $script:scriptBlockConvertToCanonicalCatalogJson -Value $Case.PSObject.Properties[$strExpected].Value
        if ($strActualJson -cne $strExpectedJson) { $listFailures.Add('mismatch-' + $strActual) }
    }
    $hashtableDiagnostics = [ordered]@{}
    $hashtableDiagnosticFields = @{
        Phase = 'ActualPhase'; Subreason = 'ActualSubreason'; Code = 'ActualDiagnosticCode'
        Labels = 'ActualLabels'; LabelExposure = 'LabelExposure'
        AttackerToStringCalls = 'AttackerToStringCalls'
        DiagnosticNamespace = 'DiagnosticNamespace'; Projection = 'DiagnosticProjection'
        EmittedProductionDiagnostic = 'EmittedProductionDiagnostic'
        EmittedTerraformDiagnostic = 'EmittedTerraformDiagnostic'
    }
    foreach ($objExpected in $Case.ExpectedDiagnostics.PSObject.Properties) {
        $strName = $objExpected.Name
        if ($strName -ceq 'SuppliedPrimaryFailure') {
            $objSupplied = if ($null -eq $Observation) { $null } else { $Observation.PSObject.Properties['PrimaryFailureSupplied'] }
            $objPreserved = if ($null -eq $Observation) { $null } else { $Observation.PSObject.Properties['PrimaryFailureIdentityPreserved'] }
            $strValue = if ($null -eq $objSupplied) { $null } elseif ($objSupplied.Value -ceq $true) { 'controlled-primary' } elseif ($objSupplied.Value -ceq $false) { 'none' } else { $null }
            $hashtableDiagnostics[$strName] = $strValue
            if ($strValue -cne $objExpected.Value -or
                ($strValue -ceq 'controlled-primary' -and ($null -eq $objPreserved -or $objPreserved.Value -cne $true))) {
                $listFailures.Add('mismatch-primary-failure')
            }
            continue
        }
        if (-not $hashtableDiagnosticFields.ContainsKey($strName)) { throw 'result-unknown-expected-diagnostic' }
        $objActual = if ($null -eq $Observation) { $null } else { $Observation.PSObject.Properties[$hashtableDiagnosticFields[$strName]] }
        if ($null -eq $objActual) {
            $hashtableDiagnostics[$strName] = $null
            $listFailures.Add('missing-diagnostic-' + $strName)
        } else {
            $hashtableDiagnostics[$strName] = $objActual.Value
            if ((& $script:scriptBlockConvertToCanonicalCatalogJson -Value $objActual.Value) -cne
                (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $objExpected.Value)) { $listFailures.Add('mismatch-diagnostic-' + $strName) }
        }
    }
    if (-not $SourceIntegrityVerified) { $listFailures.Add('source-integrity-unverified') }
    $hashtableEvidence = [ordered]@{}
    $hashtableScopeValues = @{
        InitialStateObservationScope = [string[]]@('pre-invocation-no-candidate-capability', 'issued-context-lifecycle',
            'issued-fixture-lifecycle-before-claim-mutation', 'authenticated-candidate-lifecycle',
            'identity-validation-without-product-invocation', 'catalog-validation-without-product-invocation')
        ObservationScope = [string[]]@('boolean-predicate-semantic-projection', 'actual-private-production-counter-guard',
            'preserved-source-code-semantic-projection', 'public-context-creation',
            'identity-private-metadata-guard-with-real-git-control', 'identity-validation-without-product-invocation',
            'authenticated-terminal-outcome-projection', 'production-private-issuance/public-cleanup',
            'actual-production-transition-with-reentrant-public-cleanup', 'actual-post-adoption-context-cleanup',
            'source-private-production-cleanup/creation-rollback', 'actual-retained-archive-disappearance-before-metadata',
            'production-script-claim-and-identity-with-public-expansion', 'owned-paths-container-public-boundary', 'catalog-parser-without-product-invocation')
        ZeroCallProofScope = [string[]]@('finite-reviewed-static-closure-and-private-boundary-spies')
        CandidateLifecycleState = [string[]]@('NotCreated', 'Active', 'CleanupInProgress', 'Disposed', 'RetainedUncertain')
        TransformationId = [string[]]@('private-module-state-and-active-transition-reentrant-hook-v2',
            'private-module-state-single-post-adoption-pre-source-cleanup-hook-v2', 'private-module-state-partial-root-acquisition-rollback-v2',
            'private-module-state-retained-archive-pre-metadata-disappearance-v2')
        SourceCleanupCode = [string[]]@('cleanup-succeeded')
        PreCleanupObservationScope = [string[]]@('before-context-cleanup-after-candidate-release')
    }
    foreach ($strName in $hashtableScopeValues.Keys) {
        $objProperty = if ($null -eq $Observation) { $null } else { $Observation.PSObject.Properties[$strName] }
        if ($null -eq $objProperty -or $null -eq $objProperty.Value) {
            if ($strName -ceq 'InitialStateObservationScope') { $listFailures.Add('missing-initial-state-scope') }
            continue
        }
        if ($objProperty.Value -isnot [string] -or $objProperty.Value -cnotin $hashtableScopeValues[$strName]) { throw 'result-evidence-scope' }
        $hashtableEvidence[$strName] = $objProperty.Value
    }
    # Only fixed bounded scalar observations may cross the final JSON boundary.
    # Raw exceptions, arbitrary Data, paths, source text and native stderr are
    # never copied from a runner into a result.
    $arrBooleanEvidence = [string[]]@(
        'CallbackPositiveControl', 'FilesystemSnapshotUnchanged', 'FixtureSnapshotUnchanged', 'LinkedTargetUnchanged',
        'ProductScriptLoaded', 'SameObject', 'SameJournal', 'SameSummary', 'SameAttempt',
        'UnreadableControlObserved', 'PrimaryFailureIdentityPreserved', 'PublicArchiveInvocation',
        'NoContentionControlPassed', 'OuterAbortRetainedWithoutDeletion', 'AdoptionObserved',
        'PublicContextIssued', 'OuterCreationRejected', 'Deregistered', 'ReservedEntriesAbsent',
        'AutomaticPrimaryPreserved', 'RetainedArchiveCaptured', 'HelperProviderQualified', 'ContextProviderQualified',
        'FourFileContentProof', 'BothRoleIdentityBeforeLoad', 'FixtureRoleBytesUnchanged'
    )
    $arrCountEvidence = [string[]]@(
        'AttackerToStringCalls', 'ShadowGetTypeCalls', 'ShadowToStringCalls', 'ShadowCountCalls',
        'FixtureEntriesBefore', 'FixtureEntriesAfter', 'ContextCleanupAttemptsBefore',
        'ContextCleanupAttemptsAfter', 'IssuedCandidateCleanupAttempts', 'CleanupAttemptDelta',
        'CleanupErrorCount', 'CandidateErrorCount', 'ContextErrorCount', 'RemovedCount',
        'ProviderCalls', 'PathCalls', 'FilesystemCalls', 'NativeCalls',
        'NativeResponsePerturbations', 'RepositoryStateMutations', 'WorkerExit', 'ParserErrors', 'JournalCount', 'CreatedRecordCount', 'CandidateAcquiredCount'
    )
    foreach ($strName in $arrBooleanEvidence + $arrCountEvidence) {
        $objProperty = if ($null -eq $Observation) { $null } else { $Observation.PSObject.Properties[$strName] }
        if ($null -eq $objProperty -or $null -eq $objProperty.Value) { continue }
        if ($strName -cin $arrBooleanEvidence) {
            if ($objProperty.Value -isnot [bool]) { throw 'result-evidence-boolean' }
            $hashtableEvidence[$strName] = $objProperty.Value
        } else {
            if ($objProperty.Value -isnot [int] -and $objProperty.Value -isnot [uint32] -and $objProperty.Value -isnot [long]) { throw 'result-evidence-count' }
            if ($objProperty.Value -lt 0 -or $objProperty.Value -gt 1000000) { throw 'result-evidence-count-bound' }
            $hashtableEvidence[$strName] = [long]$objProperty.Value
        }
        if ($strName -cin @('AttackerToStringCalls', 'ShadowGetTypeCalls', 'ShadowToStringCalls', 'ShadowCountCalls') -and $objProperty.Value -ne 0) {
            $listFailures.Add('caller-callback-observed')
        }
    }
    $objRawSpecification = $Case.Fixture.Parameters.PSObject.Properties['Raw']
    if ($null -ne $objRawSpecification -and $objRawSpecification.Value.Class -cne 'omitted') {
        if (-not $hashtableEvidence.Contains('FilesystemSnapshotUnchanged') -or
            $hashtableEvidence.FilesystemSnapshotUnchanged -cne $true) { $listFailures.Add('missing-or-changed-raw-filesystem-snapshot') }
        if ($objRawSpecification.Value.Class -cin @('shadow-actual-type', 'shadow-string-type')) {
            foreach ($strName in @('ShadowGetTypeCalls', 'ShadowToStringCalls')) {
                if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -ne 0) {
                    $listFailures.Add('missing-or-nonzero-raw-shadow-' + $strName)
                }
            }
        }
    }
    if ($Case.Fixture.Invocation -ceq 'context-owned-container') {
        foreach ($strName in @('ShadowGetTypeCalls', 'ShadowCountCalls')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -ne 0) { $listFailures.Add('missing-or-nonzero-container-' + $strName) }
        }
        foreach ($strName in @('SameObject', 'CallbackPositiveControl')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -cne $true) { $listFailures.Add('missing-or-false-container-' + $strName) }
        }
        $boolDisposed = $Case.Fixture.Parameters.ContainerClass -ceq 'empty-object-array-shadow-count'
        if (-not $hashtableEvidence.Contains('RemovedCount') -or $hashtableEvidence.RemovedCount -ne $(if ($boolDisposed) { 2 } else { 0 }) -or
            -not $hashtableEvidence.Contains('ContextCleanupAttemptsAfter') -or $hashtableEvidence.ContextCleanupAttemptsAfter -ne $(if ($boolDisposed) { 1 } else { 0 })) { $listFailures.Add('missing-or-incorrect-container-cleanup') }
        if (-not $boolDisposed -and (-not $hashtableEvidence.Contains('FilesystemSnapshotUnchanged') -or $hashtableEvidence.FilesystemSnapshotUnchanged -cne $true)) { $listFailures.Add('missing-or-changed-container-snapshot') }
    }
    if ($Case.Id -cin @('T1A-K-03', 'T1A-K-05', 'T1A-K-06', 'T1A-K-07', 'T1A-K-08', 'T1A-K-09', 'T1A-K-12', 'T1A-K-13', 'T1A-AF-07')) {
        foreach ($strName in @('ProviderCalls', 'PathCalls', 'FilesystemCalls', 'NativeCalls')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -ne 0) { $listFailures.Add('missing-or-nonzero-terminal-' + $strName) }
        }
        foreach ($strName in @('SameObject', 'SameJournal', 'SameSummary', 'SameAttempt')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -cne $true) { $listFailures.Add('missing-or-false-terminal-' + $strName) }
        }
        if (-not $hashtableEvidence.Contains('ZeroCallProofScope')) { $listFailures.Add('missing-terminal-static-closure') }
    }
    if ($Case.Id -cin @('T1A-K-10', 'T1A-K-11', 'T1A-K-13')) {
        $strLifecycle = if ($Case.Id -ceq 'T1A-K-10') { 'Disposed' } else { 'RetainedUncertain' }
        if (-not $hashtableEvidence.Contains('CandidateLifecycleState') -or $hashtableEvidence.CandidateLifecycleState -cne $strLifecycle) {
            $listFailures.Add('missing-or-incorrect-candidate-lifecycle')
        }
    }
    if ($Case.Id -cin @('T1A-K-10', 'T1A-K-11')) {
        foreach ($strName in @('SameObject', 'FixtureSnapshotUnchanged')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -cne $true) { $listFailures.Add('missing-or-false-not-created-' + $strName) }
        }
        if (-not $hashtableEvidence.Contains('RemovedCount') -or $hashtableEvidence.RemovedCount -ne 0) { $listFailures.Add('missing-or-nonzero-not-created-removal') }
    }
    if ($Case.Id -cin @('T1A-C-08', 'T1A-AF-07') -and (-not $hashtableEvidence.Contains('PreCleanupObservationScope') -or
        -not $hashtableEvidence.Contains('CandidateLifecycleState') -or $hashtableEvidence.CandidateLifecycleState -cne 'Disposed')) {
        $listFailures.Add('missing-or-incorrect-combined-cleanup-lifecycle')
    }
    if ($Case.Id -ceq 'T1A-K-12') {
        foreach ($strName in @('NoContentionControlPassed', 'OuterAbortRetainedWithoutDeletion')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -cne $true) { $listFailures.Add('missing-or-false-in-progress-' + $strName) }
        }
        foreach ($strName in @('WorkerExit', 'ParserErrors')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -ne 0) { $listFailures.Add('missing-or-failed-in-progress-' + $strName) }
        }
        if (-not $hashtableEvidence.Contains('TransformationId')) { $listFailures.Add('missing-in-progress-transform') }
    }
    if ($Case.Id -cin @('T1A-C-05', 'T1A-C-07', 'T1A-C-09')) {
        foreach ($strName in @('WorkerExit', 'ParserErrors')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -ne 0) { $listFailures.Add('missing-or-failed-context-worker-' + $strName) }
        }
        if (-not $hashtableEvidence.Contains('NoContentionControlPassed') -or -not $hashtableEvidence.NoContentionControlPassed -or
            -not $hashtableEvidence.Contains('TransformationId')) { $listFailures.Add('missing-context-transform-control') }
        if ($Case.Id -ceq 'T1A-C-07') {
            foreach ($strName in @('OuterCreationRejected', 'Deregistered', 'ReservedEntriesAbsent')) {
                if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -cne $true) { $listFailures.Add('missing-or-false-partial-context-' + $strName) }
            }
            if (-not $hashtableEvidence.Contains('PublicContextIssued') -or $hashtableEvidence.PublicContextIssued -cne $false -or
                -not $hashtableEvidence.Contains('SourceCleanupCode') -or $hashtableEvidence.SourceCleanupCode -cne 'cleanup-succeeded' -or
                -not $hashtableEvidence.Contains('CreatedRecordCount') -or $hashtableEvidence.CreatedRecordCount -ne 1 -or
                -not $hashtableEvidence.Contains('RemovedCount') -or $hashtableEvidence.RemovedCount -ne 1) { $listFailures.Add('missing-or-invalid-partial-cleanup-evidence') }
        } else {
            if (-not $hashtableEvidence.Contains('AdoptionObserved') -or -not $hashtableEvidence.AdoptionObserved -or
                -not $hashtableEvidence.Contains('RemovedCount') -or $hashtableEvidence.RemovedCount -ne 0) { $listFailures.Add('missing-or-invalid-adoption-evidence') }
            if ($Case.Id -ceq 'T1A-C-09' -and (-not $hashtableEvidence.Contains('UnreadableControlObserved') -or
                -not $hashtableEvidence.UnreadableControlObserved)) { $listFailures.Add('missing-actual-unreadable-control') }
        }
    }
    if ($Case.Id -ceq 'T1A-E-20') {
        foreach ($strName in @('NoContentionControlPassed', 'AutomaticPrimaryPreserved', 'RetainedArchiveCaptured')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -cne $true) { $listFailures.Add('missing-or-false-archive-race-' + $strName) }
        }
        foreach ($strName in @('WorkerExit', 'ParserErrors', 'CandidateAcquiredCount')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -ne 0) { $listFailures.Add('missing-or-failed-archive-race-' + $strName) }
        }
        if (-not $hashtableEvidence.Contains('TransformationId')) { $listFailures.Add('missing-archive-race-transform') }
    }
    if ($Case.Id -cin @('T1A-S-11', 'T1A-AF-15', 'T1A-AF-16')) {
        foreach ($strName in @('FourFileContentProof', 'BothRoleIdentityBeforeLoad', 'FixtureRoleBytesUnchanged', 'PublicArchiveInvocation')) {
            if (-not $hashtableEvidence.Contains($strName) -or $hashtableEvidence[$strName] -cne $true) { $listFailures.Add('missing-or-false-accepted-script-' + $strName) }
        }
        if (-not $hashtableEvidence.Contains('HelperProviderQualified') -or
            $hashtableEvidence.HelperProviderQualified -cne ($Case.Id -cne 'T1A-AF-16') -or
            -not $hashtableEvidence.Contains('ContextProviderQualified') -or
            $hashtableEvidence.ContextProviderQualified -cne ($Case.Id -cne 'T1A-AF-15')) { $listFailures.Add('incorrect-qualified-script-role') }
    }
    foreach ($strName in @('ControlObjectId', 'RawArchiveSha256', 'HelperSourceSha256', 'DerivedHelperSha256', 'ContextSourceSha256', 'DerivedContextSha256', 'HelperControlObjectId', 'ContextControlObjectId')) {
        $objProperty = if ($null -eq $Observation) { $null } else { $Observation.PSObject.Properties[$strName] }
        if ($null -eq $objProperty -or $null -eq $objProperty.Value) { continue }
        if ($objProperty.Value -isnot [string] -or $objProperty.Value -cnotmatch '^(?:[0-9a-f]{40}|[0-9a-f]{64})$') { throw 'result-evidence-hash' }
        $hashtableEvidence[$strName] = $objProperty.Value
    }
    if ($Case.Id -cin @('T1A-K-12', 'T1A-E-20') -and (-not $hashtableEvidence.Contains('HelperSourceSha256') -or
        -not $hashtableEvidence.Contains('DerivedHelperSha256'))) { $listFailures.Add('missing-in-progress-source-hashes') }
    if ($Case.Id -cin @('T1A-C-05', 'T1A-C-07', 'T1A-C-09') -and (-not $hashtableEvidence.Contains('ContextSourceSha256') -or
        -not $hashtableEvidence.Contains('DerivedContextSha256'))) { $listFailures.Add('missing-context-source-hashes') }
    if ($Case.Id -cin @('T1A-S-11', 'T1A-AF-15', 'T1A-AF-16') -and (-not $hashtableEvidence.Contains('HelperControlObjectId') -or
        -not $hashtableEvidence.Contains('ContextControlObjectId'))) { $listFailures.Add('missing-accepted-script-object-ids') }
    $objPredicate = if ($null -eq $Observation) { $null } else { $Observation.PSObject.Properties['PredicateEvidence'] }
    if ($null -ne $objPredicate -and $null -ne $objPredicate.Value) {
        $objValue = $objPredicate.Value
        if ($objValue.PositiveControl -isnot [bool] -or $objValue.SiblingContained -isnot [bool]) { throw 'result-predicate-evidence' }
        $hashtableEvidence.Predicate = [pscustomobject]@{ PositiveControl = $objValue.PositiveControl; SiblingContained = $objValue.SiblingContained }
        if (-not $objValue.PositiveControl -or $objValue.SiblingContained) { $listFailures.Add('predicate-control-failed') }
    }
    $hashtableResult = [ordered]@{}
    foreach ($strField in @('Id', 'SemanticCase', 'Applicability', 'Fixture', 'InitialState', 'OracleProfile',
        'ExpectedResult', 'ExpectedStatus', 'ExpectedPhase', 'ExpectedSubreason', 'PreCleanupCandidateState',
        'FinalCandidateState', 'FinalContextState', 'CleanupSequence', 'ExpectedDiagnostics', 'SentinelState', 'SourceRepositoryState')) {
        $hashtableResult[$strField] = $Case.PSObject.Properties[$strField].Value
    }
    foreach ($strField in $hashtableActual.Keys) { $hashtableResult[$strField] = $hashtableActual[$strField] }
    $hashtableResult.ActualDiagnostics = [pscustomobject]$hashtableDiagnostics
    $hashtableResult.ActualSourceRepositoryState = if ($SourceIntegrityVerified) { 'unchanged' } else { 'unverified' }
    $hashtableResult.Runtime = [pscustomobject][ordered]@{
        Id = $Runtime.Id; PowerShellVersion = $Runtime.PowerShellVersion
        Edition = $Runtime.Edition; Platform = $Runtime.Platform
    }
    $hashtableResult.StatusSemantics = 'in-process-operation-or-explicit-semantic-projection'
    $hashtableResult.Evidence = [pscustomobject]$hashtableEvidence
    $hashtableResult.HarnessVerdict = if ($listFailures.Count -eq 0) { 'pass' } else { 'fail' }
    $hashtableResult.FailureReasons = $listFailures.ToArray()
    return [pscustomobject]$hashtableResult
}

$script:scriptBlockAssertTerraformRawEvidenceMutants = {
    param ([object]$Case, [object]$Observation, [System.Collections.IDictionary]$Runtime)

    if ($Case.Fixture.Parameters.Raw.Class -cnotin @('shadow-actual-type', 'shadow-string-type')) { throw 'raw-evidence-mutation-case' }
    $objPositive = & $script:scriptBlockNewTerraformCaseResult -Case $Case -Observation $Observation -Runtime $Runtime -SourceIntegrityVerified $true
    if ($objPositive.HarnessVerdict -cne 'pass') { throw 'raw-evidence-positive-control' }
    foreach ($strField in @('ShadowGetTypeCalls', 'ShadowToStringCalls', 'FilesystemSnapshotUnchanged')) {
        foreach ($strMode in @('missing', 'wrong')) {
            $hashtableClone = [ordered]@{}
            foreach ($objProperty in $Observation.PSObject.Properties) {
                if ($objProperty.Name -cne $strField) { $hashtableClone[$objProperty.Name] = $objProperty.Value }
            }
            if ($strMode -ceq 'wrong') {
                $hashtableClone[$strField] = if ($strField -ceq 'FilesystemSnapshotUnchanged') { $false } else { [int]1 }
            }
            $objNegative = & $script:scriptBlockNewTerraformCaseResult -Case $Case -Observation ([pscustomobject]$hashtableClone) -Runtime $Runtime -SourceIntegrityVerified $true
            $strReason = if ($strField -ceq 'FilesystemSnapshotUnchanged') { 'missing-or-changed-raw-filesystem-snapshot' }
                else { 'missing-or-nonzero-raw-shadow-' + $strField }
            if ($objNegative.HarnessVerdict -cne 'fail' -or $objNegative.FailureReasons -cnotcontains $strReason) { throw 'raw-evidence-mutant-not-refused' }
        }
    }
}


$script:scriptBlockAssertTerminalCapabilityClosure = {
    param ([string]$Source, [ValidateSet('helper', 'context')][string]$Role)

    # This is a finite reviewed closure, not a general purity analyzer. It pins
    # the public prefix through the unconditional Disposed return, its exact
    # authentication callees, and each fixed CLR member binding. Public values
    # enter private captures only through exact NoteProperty CLR getters.
    # Private issuance snapshots remain private; global type-data or deliberate
    # module reflection are outside the ordinary public-claim threat model.
    $hashtablePins = @{
        helper = @{
            Prefix = '184887e99ad13a20e2e8c05eb2de013b418e8a16fac90efe15e0fad9ffbb0acc'
            Parameters = '03b578f9c44065eb135507f5cbb52f9644c367df9a8c83089372fe3ab593990d'
            TerminalPrefix = 'b47fb5d67233521af04878641ce1b0d6c92b84c6bf6f343692d947a708e248ae'
            objCandidateExactTypeMethod = '3c5c5699ccec298e9c7b92c81a8f3c00fb377a73b124e618e68a45df896bcc62'
            objCandidateArrayLengthGetter = '379a1042219e3fbe4f36950792b913e5b56a341d00ee1c2b9d6f89bf48e7ebac'
            objCandidatePropertiesGetter = 'da3317ab46ea928b97fb067dbf27e5ac44fddd613500b397458e3897486077ef'
            objCandidateTypeNamesGetter = '093f7f57766d67886001ccf6ff2a074b3fa470a409bfca5a9eb33daaaaed8a47'
            objCandidateTypeNameCountGetter = '501cd449a5ec11aa0eac427cf253522cda49a54cc6f75e052f90d5221105ce59'
            objCandidateTypeNameItemGetter = '58daa4d5035173dfec03f571f531bb43079303dfd8450f1e5db7b8460367fb6c'
            objCandidateNoteNameGetter = 'a8c163200bae360f24d35af9023a157dae6c5fd0e01377cfe72f37e4f6039dce'
            objCandidateNoteKindGetter = '3d20300df4b757c302458a45d15a904eb3724804119341e1912891efdc297eec'
            objCandidateNoteValueGetter = '38ecd6b953f7108f98ec733c8dd2d9f055af61e69ca83994385a8caf3aa78312'
            scriptBlockGetCandidateExactRuntimeType = '2382d7fa7d3207d69439aa505789754f4cbf672b2dbb1af021e5a33f99471cef'
            scriptBlockGetCandidatePublicArrayLength = '137c70466c6c2e9b34ae6a38436b2149e64645845bc15388b6e22be6b0bc0d94'
            scriptBlockTestCandidatePublicTypeName = '184b981d75cf61a5c2eea41be9c81bc9c2ecc12308e57d892c96dab825af67d7'
            scriptBlockCaptureCandidatePublicProperties = 'f0480d6a4a3d0aed4a5ea5dd7079ec27a653066ef7763741538cd737da70d9b4'
            scriptBlockAssertCandidateOwnershipState = '4c0a7bcf35acbbd2d40c3f601727611329f7e06a36c74863cf62085e3cc02bd9'
        }
        context = @{
            Prefix = 'd48565180ce9aec3bd78993815d0e47927a6b2e36c88295e34374a72995fd571'
            Parameters = 'ea46453214c8d28c40964253b1ad49119689b65a8e6f7a477352a00f94f2d4c6'
            objCandidateExactTypeMethod = '3c5c5699ccec298e9c7b92c81a8f3c00fb377a73b124e618e68a45df896bcc62'
            objCandidateArrayLengthGetter = '379a1042219e3fbe4f36950792b913e5b56a341d00ee1c2b9d6f89bf48e7ebac'
            objCandidatePropertiesGetter = 'da3317ab46ea928b97fb067dbf27e5ac44fddd613500b397458e3897486077ef'
            objCandidateTypeNamesGetter = '093f7f57766d67886001ccf6ff2a074b3fa470a409bfca5a9eb33daaaaed8a47'
            objCandidateTypeNameCountGetter = '501cd449a5ec11aa0eac427cf253522cda49a54cc6f75e052f90d5221105ce59'
            objCandidateTypeNameItemGetter = '58daa4d5035173dfec03f571f531bb43079303dfd8450f1e5db7b8460367fb6c'
            objCandidateNoteNameGetter = 'a8c163200bae360f24d35af9023a157dae6c5fd0e01377cfe72f37e4f6039dce'
            objCandidateNoteKindGetter = '3d20300df4b757c302458a45d15a904eb3724804119341e1912891efdc297eec'
            objCandidateNoteValueGetter = '38ecd6b953f7108f98ec733c8dd2d9f055af61e69ca83994385a8caf3aa78312'
            scriptBlockGetCandidateExactRuntimeType = '2382d7fa7d3207d69439aa505789754f4cbf672b2dbb1af021e5a33f99471cef'
            scriptBlockGetCandidatePublicArrayLength = '137c70466c6c2e9b34ae6a38436b2149e64645845bc15388b6e22be6b0bc0d94'
            scriptBlockTestCandidatePublicTypeName = '184b981d75cf61a5c2eea41be9c81bc9c2ecc12308e57d892c96dab825af67d7'
            scriptBlockCaptureCandidatePublicProperties = 'f0480d6a4a3d0aed4a5ea5dd7079ec27a653066ef7763741538cd737da70d9b4'
            scriptBlockAssertPublicContext = '458e310ba8f10f2553be90e8520cb46839af901bf6d11ce9c87bb029ecdabcce'
        }
    }
    $arrErrors = $null
    $objAst = [System.Management.Automation.Language.Parser]::ParseInput($Source, [ref]$null, [ref]$arrErrors)
    if ($arrErrors.Count -ne 0) { throw 'terminal-closure-parse' }
    $strFunction = if ($Role -ceq 'helper') { 'Remove-StyleGuideCandidateInvocationState' } else { 'Remove-StyleGuideCandidateInvocationContext' }
    $strModuleVariable = if ($Role -ceq 'helper') { 'scriptBlockCandidateModuleDefinition' } else { 'scriptBlockContextModuleDefinition' }
    $arrModules = @($objAst.FindAll({
        param ($Node)
        $Node -is [System.Management.Automation.Language.AssignmentStatementAst] -and
            $Node.Left -is [System.Management.Automation.Language.VariableExpressionAst] -and
            $Node.Left.VariablePath.UserPath -ceq $strModuleVariable
    }, $true))
    if ($arrModules.Count -ne 1) { throw 'terminal-closure-module' }
    $arrModuleBlocks = @($arrModules[0].Right.FindAll({ param ($Node) $Node -is [System.Management.Automation.Language.ScriptBlockExpressionAst] }, $false))
    if ($arrModuleBlocks.Count -ne 1) { throw 'terminal-closure-module' }
    $objModule = $arrModuleBlocks[0].ScriptBlock
    $arrFunctions = @($objAst.FindAll({ param ($Node) $Node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $Node.Name -ceq $strFunction }, $true))
    if ($arrFunctions.Count -ne 1 -or -not [object]::ReferenceEquals($arrFunctions[0].Parent, $objModule.EndBlock)) { throw 'terminal-closure-function' }
    $objFunction = $arrFunctions[0]
    if ($objFunction.IsFilter -or $objFunction.IsWorkflow -or
        $null -ne $objFunction.Body.BeginBlock -or $null -ne $objFunction.Body.ProcessBlock -or
        $null -ne $objFunction.Body.DynamicParamBlock -or $null -eq $objFunction.Body.EndBlock -or
        -not $objFunction.Body.EndBlock.Unnamed -or
        ($null -ne $objFunction.Body.PSObject.Properties['CleanBlock'] -and $null -ne $objFunction.Body.CleanBlock)) {
        throw 'terminal-closure-body-shape'
    }
    if ($objFunction.Body.EndBlock.Statements.Count -lt 5) { throw 'terminal-closure-prefix' }
    $hashtableParts = @{
        Prefix = ($objFunction.Body.EndBlock.Statements[0..4] | ForEach-Object { $_.Extent.Text }) -join "`n"
        Parameters = $objFunction.Body.ParamBlock.Extent.Text
    }
    if ($Role -ceq 'helper') { $hashtableParts.TerminalPrefix = ($objFunction.Body.EndBlock.Statements[0..5] | ForEach-Object { $_.Extent.Text }) -join "`n" }
    foreach ($strKey in $hashtablePins[$Role].Keys) {
        if ($strKey -cin @('Prefix', 'Parameters', 'TerminalPrefix')) { continue }
        $strQualified = 'script:' + $strKey
        $arrAssignments = @($objAst.FindAll({
            param ($Node)
            $Node -is [System.Management.Automation.Language.AssignmentStatementAst] -and
                $Node.Left -is [System.Management.Automation.Language.VariableExpressionAst] -and
                $Node.Left.VariablePath.UserPath -ceq $strQualified
        }, $true))
        if ($arrAssignments.Count -ne 1 -or
            -not [object]::ReferenceEquals($arrAssignments[0].Parent, $objModule.EndBlock) -or
            $arrAssignments[0].Extent.EndOffset -ge $objFunction.Extent.StartOffset) { throw 'terminal-closure-binding' }
        $hashtableParts[$strKey] = $arrAssignments[0].Extent.Text
    }
    foreach ($strKey in $hashtableParts.Keys) {
        $strCanonical = $hashtableParts[$strKey].Replace("`r`n", "`n")
        $strHash = & $script:scriptBlockGetByteArraySha256 -Bytes ([System.Text.Encoding]::UTF8.GetBytes($strCanonical))
        if ($strHash -cne $hashtablePins[$Role][$strKey]) { throw 'terminal-closure-content' }
    }
}

$script:scriptBlockAssertTerminalCapabilityClosureMutations = {
    param ([string]$Source, [ValidateSet('helper', 'context')][string]$Role)

    & $script:scriptBlockAssertTerminalCapabilityClosure -Source $Source -Role $Role
    $arrErrors = $null
    $objAst = [System.Management.Automation.Language.Parser]::ParseInput($Source, [ref]$null, [ref]$arrErrors)
    $strFunction = if ($Role -ceq 'helper') { 'Remove-StyleGuideCandidateInvocationState' } else { 'Remove-StyleGuideCandidateInvocationContext' }
    $objFunction = @($objAst.FindAll({ param ($Node) $Node -is [System.Management.Automation.Language.FunctionDefinitionAst] -and $Node.Name -ceq $strFunction }, $true))[0]
    $objType = @($objAst.FindAll({ param ($Node) $Node -is [System.Management.Automation.Language.AssignmentStatementAst] -and $Node.Left -is [System.Management.Automation.Language.VariableExpressionAst] -and $Node.Left.VariablePath.UserPath -ceq 'script:scriptBlockGetCandidateExactRuntimeType' }, $true))[0]
    $objBinding = @($objAst.FindAll({ param ($Node) $Node -is [System.Management.Automation.Language.AssignmentStatementAst] -and $Node.Left -is [System.Management.Automation.Language.VariableExpressionAst] -and $Node.Left.VariablePath.UserPath -ceq 'script:objCandidateExactTypeMethod' }, $true))[0]
    $listMutants = New-Object 'System.Collections.Generic.List[string]'
    $listMutants.Add($Source.Insert($objFunction.Body.EndBlock.Statements[0].Extent.StartOffset, "[void][System.IO.File]::Exists('terminal-direct-control')`n"))
    $strType = $objType.Extent.Text.Replace("if (`$null -eq `$Value)", "[void][System.IO.Directory]::Exists('terminal-indirect-control')`n        if (`$null -eq `$Value)")
    if ($strType -ceq $objType.Extent.Text) { throw 'terminal-mutant-anchor' }
    $listMutants.Add($Source.Remove($objType.Extent.StartOffset, $objType.Extent.EndOffset - $objType.Extent.StartOffset).Insert($objType.Extent.StartOffset, $strType))
    $listMutants.Add($Source.Remove($objBinding.Extent.StartOffset, $objBinding.Extent.EndOffset - $objBinding.Extent.StartOffset).Insert($objBinding.Extent.StartOffset, "if (`$false) { " + $objBinding.Extent.Text + ' }'))
    $listMutants.Add($Source.Insert($objBinding.Extent.EndOffset, "`n" + $objBinding.Extent.Text))
    $listMutants.Add($Source.Remove($objBinding.Extent.StartOffset, $objBinding.Extent.EndOffset - $objBinding.Extent.StartOffset).Insert($objBinding.Extent.StartOffset, $objBinding.Extent.Text.Replace("'GetType'", "'ToString'")))
    if ($Role -ceq 'helper') {
        $objTerminal = $objFunction.Body.EndBlock.Statements[5]
        $intInsertion = $objTerminal.Clauses[0].Item2.Statements[0].Extent.StartOffset
        $listMutants.Add($Source.Insert($intInsertion, "[void][System.IO.Path]::GetFullPath('static-only-retained-control')`n"))
    }
    foreach ($strMutant in $listMutants) {
        $objFailure = $null
        try { & $script:scriptBlockAssertTerminalCapabilityClosure -Source $strMutant -Role $Role }
        catch { $objFailure = $_ }
        if ($null -eq $objFailure -or $objFailure.Exception.Message -notin @('terminal-closure-binding', 'terminal-closure-content')) {
            throw 'terminal-closure-mutant-accepted'
        }
    }
    $arrShapes = [string[]]@('begin', 'process', 'dynamicparam', 'explicit-end-only')
    if ($null -ne $objFunction.Body.PSObject.Properties['CleanBlock']) { $arrShapes += 'clean' }
    foreach ($strShape in $arrShapes) {
        $strOther = if ($strShape -ceq 'explicit-end-only') { '' } else { $strShape + " { [void][System.IO.File]::Exists('static-only-never-run') }" }
        $strBody = "{`n" + $objFunction.Body.ParamBlock.Extent.Text + "`n" + $strOther + "`nend {`n" +
            (($objFunction.Body.EndBlock.Statements | ForEach-Object { $_.Extent.Text }) -join "`n") + "`n}`n}"
        $strMutant = $Source.Remove($objFunction.Body.Extent.StartOffset, $objFunction.Body.Extent.EndOffset - $objFunction.Body.Extent.StartOffset).Insert($objFunction.Body.Extent.StartOffset, $strBody)
        $arrShapeErrors = $null
        $null = [System.Management.Automation.Language.Parser]::ParseInput($strMutant, [ref]$null, [ref]$arrShapeErrors)
        if ($arrShapeErrors.Count -ne 0) { throw 'terminal-shape-mutant-parse' }
        $objFailure = $null
        try { & $script:scriptBlockAssertTerminalCapabilityClosure -Source $strMutant -Role $Role }
        catch { $objFailure = $_ }
        if ($null -eq $objFailure -or $objFailure.Exception.Message -cne 'terminal-closure-body-shape') { throw 'terminal-shape-mutant-accepted' }
    }
    return [pscustomobject]@{
        Assertion = 'TerminalCapabilityClosure'; Role = $Role; PositiveSourceAccepted = $true
        MutantsRefusedBeforeExecution = $listMutants.Count + $arrShapes.Count
        SupportedShapeMutants = $arrShapes
    }
}

# Installs only the hostile Count fixture member on the original instance.
# Desktop arrays inherit a Count alias from type data, so isolate this instance's
# type names during ordinary Add-Member and restore them before any observation.
$script:scriptBlockInstallTerraformFixtureCount = {
    param ([object]$Target, [scriptblock]$Getter)

    $objOriginalTarget = $Target
    $objTypeNames = $Target.PSObject.TypeNames
    $arrOriginalNames = [string[]]@($objTypeNames)
    $arrSibling = [object[]]@(7, 8)
    $arrSiblingNames = [string[]]@($arrSibling.PSObject.TypeNames)
    $objTypeNames.Clear()
    try {
        Add-Member -InputObject $Target -MemberType ScriptProperty -Name Count -Force -Value $Getter
    } finally {
        foreach ($strTypeName in $arrOriginalNames) { $objTypeNames.Add($strTypeName) }
    }
    if (-not [object]::ReferenceEquals($objOriginalTarget, $Target) -or
        -not [object]::ReferenceEquals($objTypeNames, $Target.PSObject.TypeNames) -or
        $objTypeNames.Count -ne $arrOriginalNames.Length -or
        $arrSibling.PSObject.TypeNames.Count -ne $arrSiblingNames.Length -or $arrSibling.Count -ne 2) {
        throw 'fixture-count-instance-restoration'
    }
    for ($intIndex = 0; $intIndex -lt $arrOriginalNames.Length; $intIndex++) {
        if ($objTypeNames[$intIndex] -cne $arrOriginalNames[$intIndex]) { throw 'fixture-count-type-name-order' }
    }
    for ($intIndex = 0; $intIndex -lt $arrSiblingNames.Length; $intIndex++) {
        if ($arrSibling.PSObject.TypeNames[$intIndex] -cne $arrSiblingNames[$intIndex]) { throw 'fixture-count-sibling-type-name-order' }
    }
}

$script:scriptBlockAssertPublicCapabilityCaptureExecutes = {
    param ([string]$RunRoot, [string]$HelperLiteralPath)

    $hashtableCallbackState = @{}

    function Assert-TerraformPublicCapabilityCapture {
        # .SYNOPSIS
        # Checks captured capability claims and fixed CLR inspection controls.
        #
        # .DESCRIPTION
        # Mutates only the supplied disposable fixture and restores every claim.
        #
        # .PARAMETER State
        # Specifies an authentic disposed fixture capability.
        #
        # .PARAMETER Cleanup
        # Specifies its actual public cleanup callable.
        #
        # .PARAMETER Module
        # Specifies the already verified module containing the fixed capture guards.
        #
        # .EXAMPLE
        # Assert-TerraformPublicCapabilityCapture -State $objState -Cleanup $scriptBlockCleanup -Module $objModule
        #
        # # Checks the disposable capability using its captured public cleanup.
        #
        # .INPUTS
        # None. You can't pipe objects to this function.
        #
        # .OUTPUTS
        # [pscustomobject] Actual control counts and preserved identity predicates.
        #
        # .NOTES
        # PRIVATE/INTERNAL HELPER - This function is not part of the public API
        # surface. Parameters, return shape, and positional contract may change
        # without notice.
        #
        # Positional binding is disabled; all internal callers use parameter
        # names. This internal-caller contract is subject to change.
        #
        # Version: 1.0.20260924.1
        [CmdletBinding(PositionalBinding = $false)]
        [OutputType([pscustomobject])]
        param (
            [Parameter(Mandatory = $true)]
            [object]$State,

            [Parameter(Mandatory = $true)]
            [scriptblock]$Cleanup,

            [Parameter(Mandatory = $true)]
            [object]$Module
        )

        $hashtableCallbackState = @{}

        $arrNames = [string[]]@($State.PSObject.TypeNames)
        $objSummary = $State.CleanupSummary
        $arrJournal = $State.OwnershipJournal
        $strAttemptProperty = if ($null -ne $State.PSObject.Properties['CleanupAttempt']) { 'Attempt' } else { 'Attempts' }
        $objAttempt = $objSummary.PSObject.Properties[$strAttemptProperty].Value
        $intCases = 0
        foreach ($objMutation in @(
            @{ Target = $State; Name = 'SchemaVersion'; Value = [int]1 },
            @{ Target = $State; Name = 'SchemaVersion'; Value = $null },
            @{ Target = $State; Name = 'OwnershipJournal'; Value = [object[]]@() },
            @{ Target = $State; Name = 'OwnershipJournal'; Value = [object[]]@($arrJournal) },
            @{ Target = $State; Name = 'OwnershipJournal'; Value = [string[]]@('x') },
            @{ Target = $State; Name = 'CleanupSummary'; Value = $null },
            @{ Target = $arrJournal[0]; Name = 'Sequence'; Value = [int]1 },
            @{ Target = $objSummary; Name = 'RemovedPaths'; Value = [string[]]@() },
            @{ Target = $objSummary; Name = 'RetainedPaths'; Value = [object[]]@() }
        )) {
            $objDescriptor = $objMutation.Target.PSObject.Properties[$objMutation.Name]
            $objOriginal = $objDescriptor.Value
            $objDescriptor.Value = $objMutation.Value
            $objFailure = $null
            try { $null = & $Cleanup $State } catch { $objFailure = $_ }
            finally { $objDescriptor.Value = $objOriginal }
            if ($null -eq $objFailure -or $objFailure.Exception.Data['TerraformStyleGuidePhase'] -cne 'cleanup') { throw 'malformed-capability-accepted' }
            $intCases++
        }
        foreach ($strNameMode in @('empty', 'unknown')) {
            $State.PSObject.TypeNames.Clear()
            if ($strNameMode -ceq 'unknown') { $State.PSObject.TypeNames.Add('Unknown.Type') }
            $objFailure = $null
            try { $null = & $Cleanup $State } catch { $objFailure = $_ }
            finally { $State.PSObject.TypeNames.Clear(); foreach ($strName in $arrNames) { $State.PSObject.TypeNames.Add($strName) } }
            if ($null -eq $objFailure) { throw 'type-name-accepted' }
            $intCases++
        }
        foreach ($objTarget in @($State, $arrJournal[0], $objSummary)) {
            $arrDescriptors = @($objTarget.PSObject.Properties)
            $strMember = $arrDescriptors[0].Name
            $hashtableCallbackState.intTask184ShapeCallbacks = 0
            Add-Member -InputObject $objTarget -MemberType ScriptProperty -Name $strMember -Force -Value ({
                $hashtableCallbackState.intTask184ShapeCallbacks++
                return [uint32]1
            }.GetNewClosure())
            $null = $objTarget.$strMember
            if ($hashtableCallbackState.intTask184ShapeCallbacks -ne 1) { throw 'script-property-counter-control' }
            $hashtableCallbackState.intTask184ShapeCallbacks = 0
            $objFailure = $null
            try { $null = & $Cleanup $State } catch { $objFailure = $_ }
            finally {
                foreach ($strName in [string[]]@($objTarget.PSObject.Properties.Name)) { $objTarget.PSObject.Properties.Remove($strName) }
                foreach ($objDescriptor in $arrDescriptors) { $objTarget.PSObject.Properties.Add($objDescriptor) }
            }
            if ($null -eq $objFailure -or $hashtableCallbackState.intTask184ShapeCallbacks -ne 0) { throw 'script-property-callback' }
            $intCases++
        }
        foreach ($objTarget in @($arrJournal[0], $objSummary)) {
            $hashtableCallbackState.intTask184ShapeCallbacks = 0
            Add-Member -InputObject $objTarget -MemberType ScriptMethod -Name GetType -Force -Value ({
                $hashtableCallbackState.intTask184ShapeCallbacks++
                return [System.Management.Automation.PSCustomObject]
            }.GetNewClosure())
