$script:scriptBlockInvokeTerraformOwnedContainerCase = {
    param ([pscustomobject]$Case, [string]$RunRoot)

    $hashtableLayout = & $script:scriptBlockNewCaseFixtureLayout -RunRoot $RunRoot -CaseId $Case.Id
    $objContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $hashtableLayout.Trusted
    $objOriginal = $objContext
    $hashtableCounters = @{ GetType = 0; Count = 0 }
    $strClass = $Case.Fixture.Parameters.ContainerClass
    $objOwned = $null
    $boolControl = $false
    try {
        switch -Exact ($strClass) {
            'forged-object-array-type' {
                $objOwned = [pscustomobject]@{ Claim = 'object-array' }
                $scriptBlockType = { $hashtableCounters.GetType++; return [object[]] }.GetNewClosure()
                $objOwned | Add-Member -MemberType ScriptMethod -Name GetType -Value $scriptBlockType -Force
                [void]$objOwned.GetType()
                $boolControl = $hashtableCounters.GetType -eq 1
            }
            'actual-string-array' {
                $objOwned = [string[]]@()
                $boolControl = $objOwned -is [string[]] -and $objOwned -isnot [object[,]]
            }
            'empty-object-array-shadow-count' {
                $objOwned = New-Object object[] 0
                $scriptBlockCount = { $hashtableCounters.Count++; return 99 }.GetNewClosure()
                & $script:scriptBlockInstallTerraformFixtureCount -Target $objOwned -Getter $scriptBlockCount
                [void]$objOwned.Count
                $boolControl = $hashtableCounters.Count -eq 1
            }
            'null-element-shadow-count' {
                $objOwned = New-Object object[] 1
                $scriptBlockCount = { $hashtableCounters.Count++; return 99 }.GetNewClosure()
                & $script:scriptBlockInstallTerraformFixtureCount -Target $objOwned -Getter $scriptBlockCount
                [void]$objOwned.Count
                $boolControl = $hashtableCounters.Count -eq 1
            }
            'two-items-shadow-count' {
                $objOwned = [object[]]@([System.IO.Path]::Combine($objContext.DownloadDirectoryPath, 'one.zip'), [System.IO.Path]::Combine($objContext.DownloadDirectoryPath, 'two.zip'))
                $scriptBlockCount = { $hashtableCounters.Count++; return 0 }.GetNewClosure()
                & $script:scriptBlockInstallTerraformFixtureCount -Target $objOwned -Getter $scriptBlockCount
                [void]$objOwned.Count
                $boolControl = $hashtableCounters.Count -eq 1
            }
            'explicit-null' { $objOwned = $null; $boolControl = $null -eq $objOwned }
            default { throw 'owned-container-class' }
        }
        if (-not $boolControl) { throw 'owned-container-positive-control' }
        $hashtableCounters.GetType = 0
        $hashtableCounters.Count = 0
        $objBefore = & $script:scriptBlockGetTerraformFixtureSnapshot -LiteralPath $hashtableLayout.CaseRoot
        $strBefore = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $objContext.CandidateDirectoryPath
        $objFailure = $null
        try { $objContext = Remove-StyleGuideCandidateInvocationContext -Context $objContext -OwnedPaths $objOwned }
        catch { $objFailure = $_ }
        if ($null -eq $objContext) { $objContext = $objOriginal }
        $objAfter = & $script:scriptBlockGetTerraformFixtureSnapshot -LiteralPath $hashtableLayout.CaseRoot
        $strAfter = & $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $objContext.CandidateDirectoryPath
        $boolSame = [object]::ReferenceEquals($objContext, $objOriginal)
        $boolUnchanged = ($objBefore.Entries -join "`n") -ceq ($objAfter.Entries -join "`n")
        $uintAttempt = if ($null -eq $objContext.CleanupSummary) { [uint32]0 } else { $objContext.CleanupSummary.Attempts }
        $uintRemoved = if ($null -eq $objContext.CleanupSummary) { [uint32]0 } else { [uint32]$objContext.CleanupSummary.RemovedPaths.Count }
        $boolProjection = $strClass -cin @('forged-object-array-type', 'actual-string-array', 'two-items-shadow-count', 'explicit-null')
        $strPhase = 'cleanup'
        $strReason = 'context-disposed'
        if ($null -ne $objFailure) {
            if ($boolProjection) {
                if ($objFailure.Exception.Message -cne 'owned-paths-invalid' -or
                    $objFailure.Exception.Data.Contains('TerraformStyleGuidePhase') -or
                    $objFailure.Exception.Data.Contains('TerraformStyleGuideSubreason')) { throw 'owned-container-fixed-refusal' }
                $strPhase = 'parameter'
                $strReason = 'owned-paths-invalid'
