    param ([pscustomobject]$Case, [string]$RunRoot)

    if (-not $script:hashtableTerraformLinkCases.ContainsKey($Case.Id)) { return $null }
    $strKind = $script:hashtableTerraformLinkCases[$Case.Id]
    $strRoot = [System.IO.Path]::Combine($RunRoot, 'link-probe-' + [System.Guid]::NewGuid().ToString('N'))
    [void][System.IO.Directory]::CreateDirectory($strRoot)
    $strTarget = [System.IO.Path]::Combine($strRoot, 'target')
    $strLink = [System.IO.Path]::Combine($strRoot, 'link')
    try {
        if ($strKind -ceq 'file') {
            [System.IO.File]::WriteAllBytes($strTarget, [byte[]]@(112, 114, 111, 98, 101))
            & $script:scriptBlockAssertOrdinaryInputFileType -LiteralPath $strTarget
            $objBefore = & $script:scriptBlockGetFileEvidence -LiteralPath $strTarget
