            [void][System.IO.Directory]::CreateDirectory($strTarget)
            & $script:scriptBlockAssertOrdinaryDirectoryEnvelope -LiteralPath $strTarget
        } elseif ((& $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $strTarget) -cne 'absent') { throw 'link-probe-dangling-control' }
        $boolCreated = & $script:scriptBlockNewSymbolicLink -LinkPath $strLink -TargetPath $strTarget -Directory ($strKind -cne 'file')
        if ($strKind -ceq 'file') {
            $objAfter = & $script:scriptBlockGetFileEvidence -LiteralPath $strTarget
            if ($objBefore.Sha256 -cne $objAfter.Sha256 -or $objBefore.Length -ne $objAfter.Length) { throw 'link-probe-target-changed' }
        } elseif ($strKind -ceq 'directory') {
            & $script:scriptBlockAssertOrdinaryDirectoryEnvelope -LiteralPath $strTarget
            if ([System.IO.Directory]::GetFileSystemEntries($strTarget).Count -ne 0) { throw 'link-probe-target-changed' }
        } elseif ((& $script:scriptBlockGetTerraformCandidatePresence -LiteralPath $strTarget) -cne 'absent') { throw 'link-probe-target-created' }
        if ($boolCreated) { return $null }
        return [pscustomobject][ordered]@{
            ActualResult = 'skip'; ActualStatus = $null; ActualPhase = 'applicability'
            ActualSubreason = 'skip-link-primitive-unavailable'
            ActualInitialState = 'NotCreated'; ActualPreCleanupCandidateState = 'not-applicable'
            ActualCandidateState = 'not-applicable'; ActualContextState = 'not-created'
            ActualCleanupSequence = [string[]]@('none'); ActualSentinelState = 'unchanged'
            PrimitiveProbeAttempted = $true; PrimitiveTargetControlPassed = $true
            PrimitiveProbeSucceeded = $false; Primitive = $strKind
            ProbeFailureReason = 'ordinary-target-control-passed-link-create-or-reparse-verification-failed'
            ProductFixtureCreated = $false; ProductScriptInvoked = $false
        }
    } finally { & $script:scriptBlockRemoveTestTree -LiteralPath $strRoot -ApprovedParent $RunRoot }
}

$script:scriptBlockNewTerraformPrimitiveSkipResult = {
    param ([pscustomobject]$Case, [object]$Observation, [System.Collections.IDictionary]$Runtime, [bool]$SourceIntegrityVerified)

    & $script:scriptBlockAssertExactPropertyNames -Value $Observation -Names @(
        'ActualResult', 'ActualStatus', 'ActualPhase', 'ActualSubreason', 'ActualInitialState',
        'ActualPreCleanupCandidateState', 'ActualCandidateState', 'ActualContextState',
        'ActualCleanupSequence', 'ActualSentinelState', 'PrimitiveProbeAttempted',
        'PrimitiveTargetControlPassed', 'PrimitiveProbeSucceeded', 'Primitive',
        'ProbeFailureReason', 'ProductFixtureCreated', 'ProductScriptInvoked'
    ) -Detail 'primitive-skip-observation'
    foreach ($strName in @('PrimitiveProbeAttempted', 'PrimitiveTargetControlPassed', 'PrimitiveProbeSucceeded', 'ProductFixtureCreated', 'ProductScriptInvoked')) {
        if ($Observation.PSObject.Properties[$strName].Value -isnot [bool]) { throw 'functional-skip-invalid' }
    }
    if (-not $SourceIntegrityVerified -or -not $script:hashtableTerraformLinkCases.ContainsKey($Case.Id) -or
        $Observation.ActualResult -cne 'skip' -or $null -ne $Observation.ActualStatus -or
        $Observation.ActualPhase -cne 'applicability' -or $Observation.ActualSubreason -cne 'skip-link-primitive-unavailable' -or
        $Observation.PrimitiveProbeAttempted -cne $true -or $Observation.PrimitiveTargetControlPassed -cne $true -or
        $Observation.PrimitiveProbeSucceeded -cne $false -or $Observation.Primitive -cne $script:hashtableTerraformLinkCases[$Case.Id] -or
        $Observation.ProductFixtureCreated -cne $false -or $Observation.ProductScriptInvoked -cne $false -or
        $Observation.ActualInitialState -cne 'NotCreated' -or $Observation.ActualPreCleanupCandidateState -cne 'not-applicable' -or
        $Observation.ActualContextState -cne 'not-created' -or $Observation.ActualCandidateState -cne 'not-applicable' -or
        $Observation.ActualSentinelState -cne 'unchanged' -or ($Observation.ActualCleanupSequence -join ',') -cne 'none' -or
        $Observation.ProbeFailureReason -cne 'ordinary-target-control-passed-link-create-or-reparse-verification-failed') { throw 'functional-skip-invalid' }
    $hashtableResult = [ordered]@{}
    foreach ($objProperty in $Case.PSObject.Properties) { $hashtableResult[$objProperty.Name] = $objProperty.Value }
    $hashtableResult.DeclaredCase = $Case
    $hashtableResult.AppliedApplicabilityProfile = 'OP-SKIP-PRIMITIVE'
    $hashtableResult.ExpectedResult = 'skip'; $hashtableResult.ExpectedStatus = $null
    $hashtableResult.ExpectedPhase = 'applicability'; $hashtableResult.ExpectedSubreason = 'skip-link-primitive-unavailable'
    $hashtableResult.InitialState = 'NotCreated'; $hashtableResult.PreCleanupCandidateState = 'not-applicable'
    $hashtableResult.FinalCandidateState = 'not-applicable'; $hashtableResult.FinalContextState = 'not-created'
    $hashtableResult.CleanupSequence = [string[]]@('none')
    $hashtableResult.ExpectedDiagnostics = [pscustomobject]@{ Phase = 'applicability'; Subreason = 'skip-link-primitive-unavailable' }
    foreach ($strName in @('ActualResult', 'ActualStatus', 'ActualPhase', 'ActualSubreason', 'ActualInitialState', 'ActualPreCleanupCandidateState', 'ActualCandidateState', 'ActualContextState', 'ActualCleanupSequence', 'ActualSentinelState')) {
        $hashtableResult[$strName] = $Observation.PSObject.Properties[$strName].Value
    }
    $hashtableResult.ActualFixture = $null
    $hashtableResult.ActualDiagnostics = [pscustomobject]@{ Phase = $Observation.ActualPhase; Subreason = $Observation.ActualSubreason }
    $hashtableResult.ActualSourceRepositoryState = 'unchanged'
    $hashtableResult.Runtime = [pscustomobject]$Runtime
    $hashtableResult.PrimitiveEvidence = [pscustomobject][ordered]@{
        CaseId = $Case.Id; Platform = $Runtime.Platform; Primitive = $Observation.Primitive
        ProbeAttempted = $Observation.PrimitiveProbeAttempted; TargetControlPassed = $Observation.PrimitiveTargetControlPassed
        ProbeSucceeded = $Observation.PrimitiveProbeSucceeded; Reason = $Observation.ProbeFailureReason
        ProductFixtureCreated = $Observation.ProductFixtureCreated; ProductScriptInvoked = $Observation.ProductScriptInvoked
    }
    $hashtableResult.HarnessVerdict = 'skip'; $hashtableResult.FailureReasons = [string[]]@()
    return [pscustomobject]$hashtableResult
}

$script:scriptBlockInvokeTerraformCase = {
    param (
        [pscustomobject]$Case, [string]$RunRoot, [string]$HelperLiteralPath,
        [string]$ContextLiteralPath, [string]$CatalogPath, [string]$GitPath
    )

    $objPrimitiveSkip = & $script:scriptBlockTestTerraformLinkPrimitive -Case $Case -RunRoot $RunRoot
    if ($null -ne $objPrimitiveSkip) { return $objPrimitiveSkip }
    $hashtableCommon = @{ Case = $Case; RunRoot = $RunRoot }
    if ($Case.Id -ceq 'T1A-DN-05') { return & $script:scriptBlockInvokeTerraformExpansionCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath }
    $objRaw = $Case.Fixture.Parameters.PSObject.Properties['Raw']
    if ($null -ne $objRaw -and $objRaw.Value.Class -cne 'omitted') {
        return & $script:scriptBlockInvokeTerraformRawCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath
    }
    if ($Case.Id -cin @('T1A-K-03', 'T1A-K-05', 'T1A-K-06', 'T1A-K-07', 'T1A-K-08', 'T1A-K-09')) {
        return & $script:scriptBlockInvokeTerraformTerminalCandidateCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath
    }
    if ($Case.Id -cin @('T1A-K-10', 'T1A-K-11')) {
        return & $script:scriptBlockInvokeTerraformNotCreatedCandidateCase @hashtableCommon
    }
    if ($Case.Id -ceq 'T1A-K-12') {
        return & $script:scriptBlockInvokeTerraformInProgressCandidateCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath -ContextLiteralPath $ContextLiteralPath
    }
    if ($Case.Id -cin @('T1A-C-05', 'T1A-C-09')) {
        return & $script:scriptBlockInvokeTerraformContextAdoptionCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath -ContextLiteralPath $ContextLiteralPath
    }
    if ($Case.Id -ceq 'T1A-C-07') {
        return & $script:scriptBlockInvokeTerraformPartialContextCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath -ContextLiteralPath $ContextLiteralPath
    }
    if ($Case.Id -cin @('T1A-C-08', 'T1A-AF-07')) {
        return & $script:scriptBlockInvokeTerraformCombinedCleanupCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath -ContextLiteralPath $ContextLiteralPath
    }
    if ($Case.Id -ceq 'T1A-E-20') {
        return & $script:scriptBlockInvokeTerraformMissingArchiveCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath -ContextLiteralPath $ContextLiteralPath
    }
    if ($Case.Id -cin @('T1A-S-11', 'T1A-AF-15', 'T1A-AF-16')) {
        return & $script:scriptBlockInvokeTerraformAcceptedScriptCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath -ContextLiteralPath $ContextLiteralPath -GitPath $GitPath
    }
    switch -Exact ($Case.Fixture.Invocation) {
        'script-identity' {
            return & $script:scriptBlockInvokeTerraformNativeIdentityCase @hashtableCommon -GitPath $GitPath -HelperSourcePath $HelperLiteralPath -ContextSourcePath $ContextLiteralPath
        }
        'catalog' { return & $script:scriptBlockInvokeTerraformCatalogIntegrityCase @hashtableCommon -CatalogPath $CatalogPath }
        'production-guard' { return & $script:scriptBlockInvokeTerraformProductionGuardCase @hashtableCommon }
        'context-owned-container' { return & $script:scriptBlockInvokeTerraformOwnedContainerCase @hashtableCommon }
        'context-create' { return & $script:scriptBlockInvokeTerraformContextCreationCase @hashtableCommon }
        'context-cleanup' { return & $script:scriptBlockInvokeTerraformContextCleanupCase @hashtableCommon }
        'candidate-cleanup' { return & $script:scriptBlockInvokeTerraformCandidateCleanupCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath }
        'helper' { return & $script:scriptBlockInvokeTerraformExpansionCase @hashtableCommon -HelperLiteralPath $HelperLiteralPath }
        default { & $script:scriptBlockStopHarness -Code 'fixture-failed' -Detail 'terraform-dispatch-unknown' }
    }
}

$script:scriptBlockAssertTerraformNegativeZip64Fallback = {
    param ([string]$RunRoot, [string]$HelperLiteralPath, [string]$ContextLiteralPath, [switch]$EmitObservations)

    $strRoot = [IO.Path]::Combine($RunRoot, 'negative-zip64-controls')
    [void][IO.Directory]::CreateDirectory($strRoot)
    try {
        $hashtableBindings = & $script:scriptBlockGetTerraformPrivatePredicates -HelperLiteralPath $HelperLiteralPath -ContextLiteralPath $ContextLiteralPath
        $strArchive = [IO.Path]::Combine($strRoot, 'negative.zip')
        $null = & $script:scriptBlockNewTerraformRawZip -LiteralPath $strArchive -CaseId 'T1A-R-11'
        $arrOriginal = [IO.File]::ReadAllBytes($strArchive)
        $intEnd = $arrOriginal.Length - 22
        $intCentral = [int][BitConverter]::ToUInt32($arrOriginal, $intEnd + 16)
        $intExtra = $intCentral + 46 + [BitConverter]::ToUInt16($arrOriginal, $intCentral + 28)
        $intSecond = $intExtra + 12
        if ($arrOriginal[$intCentral + 46] -ne 99) { throw 'negative-zip64-original-name-byte' }
        $listControls = New-Object 'System.Collections.Generic.List[object]'
        $listControls.Add(@{ Id = 'negative'; Bytes = $arrOriginal; Expected = $true })
        foreach ($strVariant in @('high-bit', 'nonnegative', 'missing-marker', 'wrong-id', 'short-field', 'oversized-field',
            'compressed-field-missing', 'offset-field-missing', 'disk-field-missing', 'later-broken-record', 'bad-name', 'non-ascii-name', 'case-changed-name', 'fifth-count')) {
            $arrMutant = [byte[]]$arrOriginal.Clone()
            switch -Exact ($strVariant) {
                'high-bit' { for ($intByte = 0; $intByte -lt 7; $intByte++) { $arrMutant[$intExtra + 4 + $intByte] = 0 }; $arrMutant[$intExtra + 11] = 128 }
                'nonnegative' { $arrMutant[$intExtra + 11] = 127 }
                'missing-marker' { [Array]::Copy([BitConverter]::GetBytes([uint32]2), 0, $arrMutant, $intCentral + 24, 4) }
                'wrong-id' { $arrMutant[$intExtra] = 2 }
                'short-field' { $arrMutant[$intExtra + 2] = 7 }
                'oversized-field' { $arrMutant[$intExtra + 2] = 13 }
                'compressed-field-missing' { for ($intByte = 20; $intByte -le 23; $intByte++) { $arrMutant[$intCentral + $intByte] = 255 } }
                'offset-field-missing' { for ($intByte = 42; $intByte -le 45; $intByte++) { $arrMutant[$intCentral + $intByte] = 255 } }
                'disk-field-missing' { $arrMutant[$intCentral + 34] = 255; $arrMutant[$intCentral + 35] = 255 }
                'later-broken-record' { $arrMutant[$intSecond] = 0 }
                'bad-name' { $arrMutant[$intCentral + 46] = 120 }
                'non-ascii-name' { $arrMutant[$intCentral + 46] = 128 }
                'case-changed-name' { $arrMutant[$intCentral + 46] = 67 }
                'fifth-count' { $arrMutant[$intEnd + 8] = 5; $arrMutant[$intEnd + 10] = 5 }
            }
            $listControls.Add(@{ Id = $strVariant; Bytes = $arrMutant; Expected = ($strVariant -ceq 'high-bit') })
        }
        $arrDuplicate = New-Object byte[] ($arrOriginal.Length + 12)
        [Array]::Copy($arrOriginal, 0, $arrDuplicate, 0, $intSecond)
        [Array]::Copy($arrOriginal, $intExtra, $arrDuplicate, $intSecond, 12)
        [Array]::Copy($arrOriginal, $intSecond, $arrDuplicate, $intSecond + 12, $arrOriginal.Length - $intSecond)
        $arrDuplicate[$intCentral + 30] = 24
        [Array]::Copy([BitConverter]::GetBytes([uint32]([BitConverter]::ToUInt32($arrOriginal, $intEnd + 12) + 12)), 0, $arrDuplicate, $intEnd + 24, 4)
        $listControls.Add(@{ Id = 'duplicate-zip64'; Bytes = $arrDuplicate; Expected = $false })
        foreach ($hashtableControl in $listControls) {
            $objActual = & $hashtableBindings.HelperNegativeZip64Length -ArchiveByte $hashtableControl.Bytes
            if ($objActual -isnot [bool] -or $objActual -ne $hashtableControl.Expected) { throw ('negative-zip64-classifier-' + $hashtableControl.Id) }
            if ($EmitObservations) { [pscustomobject]@{ Scope = 'negative-zip64-classifier'; Id = $hashtableControl.Id; Actual = $objActual; Expected = $hashtableControl.Expected } }
        }
        $objReader = [IO.Compression.ZipFile]::OpenRead($strArchive)
        $boolReaderRefused = $false
        try { $null = $objReader.get_Entries() } catch { $boolReaderRefused = $true } finally { $objReader.Dispose() }
        $arrHonest = & $script:scriptBlockNewArchiveByte -EntryName ([string[]]@($script:arrCandidateExpectedName))
        $strSource = [IO.File]::ReadAllText($HelperLiteralPath)
        $strNeedle = '$objMaterializedEntries = $objZipArchive.get_Entries()'
        if ($strSource.Split([string[]]@($strNeedle), [StringSplitOptions]::None).Count -ne 2) { throw 'negative-zip64-getter-site' }
        $strInvalidData = [IO.Path]::Combine($strRoot, 'helper-invalid-data.ps1')
        $strOtherError = [IO.Path]::Combine($strRoot, 'helper-other-error.ps1')
        [IO.File]::WriteAllText($strInvalidData, $strSource.Replace($strNeedle, "throw [IO.InvalidDataException]::new('negative-zip64-reader-control')"), [Text.UTF8Encoding]::new($false))
        [IO.File]::WriteAllText($strOtherError, $strSource.Replace($strNeedle, "throw [IO.InvalidOperationException]::new('negative-zip64-reader-control')"), [Text.UTF8Encoding]::new($false))
        foreach ($hashtableControl in @(
            @{ Id = 'public-negative'; Bytes = $arrOriginal; Helper = $HelperLiteralPath; Expected = 'negative-length' },
            @{ Id = 'count-before-negative'; Bytes = @($listControls | Where-Object { $_.Id -ceq 'fifth-count' })[0].Bytes; Helper = $HelperLiteralPath; Expected = 'entry-count' },
            @{ Id = 'name-before-length'; Bytes = @($listControls | Where-Object { $_.Id -ceq 'bad-name' })[0].Bytes; Helper = $HelperLiteralPath; Expected = $(if ($boolReaderRefused) { 'entry-count' } else { 'entry-name' }) },
            @{ Id = 'invalid-data-without-negative'; Bytes = $arrHonest; Helper = $strInvalidData; Expected = 'entry-count' },
            @{ Id = 'other-error-with-negative'; Bytes = $arrOriginal; Helper = $strOtherError; Expected = 'entry-count' }
        )) {
            $objResult = & $script:scriptBlockInvokeTerraformSourceExpansion -RunRoot $strRoot -HelperLiteralPath $hashtableControl.Helper -ContextLiteralPath $ContextLiteralPath -ArchiveBytes $hashtableControl.Bytes
            if ($objResult.Accepted -or $objResult.Code -cne 'manifest-invalid' -or $objResult.Phase -cne 'manifest' -or
                $objResult.Subreason -cne $hashtableControl.Expected -or $objResult.ContextState -cne 'Disposed' -or
                $objResult.CandidateState -cne 'Disposed') { throw ('negative-zip64-public-' + $hashtableControl.Id) }
            if ($EmitObservations) { [pscustomobject]@{ Scope = 'negative-zip64-public'; Id = $hashtableControl.Id; Subreason = $objResult.Subreason; ContextState = $objResult.ContextState; CandidateState = $objResult.CandidateState; ReaderRefused = $boolReaderRefused } }
        }
    } finally { & $script:scriptBlockRemoveTestTree -LiteralPath $strRoot -ApprovedParent $RunRoot }
}


$script:scriptBlockAssertTerraformLateLinkFailures = {
    param (
        [pscustomobject]$Catalog, [string]$RunRoot, [string]$HelperLiteralPath,
        [string]$ContextLiteralPath, [string]$CatalogPath, [string]$GitPath,
        [System.Collections.IDictionary]$Runtime, [switch]$EmitObservations
    )

    if ($script:hashtableTerraformLinkCases['T1A-K-02'] -cne 'file') { throw 'late-link-preflight-kind' }
    $strControlRoot = [System.IO.Path]::Combine($RunRoot, 'late-link-' + [guid]::NewGuid().ToString('N'))
    [void][System.IO.Directory]::CreateDirectory($strControlRoot)
    $scriptBlockOriginalLink = $script:scriptBlockNewSymbolicLink
    $scriptBlockOriginalRemove = $script:scriptBlockRemoveTestTree
    $scriptBlockSnapshot = $script:scriptBlockGetTerraformFixtureSnapshot
    try {
        foreach ($strCaseId in @('T1A-S-05', 'T1A-E-09', 'T1A-C-04', 'T1A-K-02', 'T1A-K-07', 'T1A-AF-04')) {
            $arrCases = @($Catalog.Cases | Where-Object { $_.Id -ceq $strCaseId })
            if ($arrCases.Count -ne 1) { throw 'late-link-case-cardinality' }
            $objCase = $arrCases[0]
            $hashtableArguments = @{
                Case = $objCase; RunRoot = $strControlRoot; HelperLiteralPath = $HelperLiteralPath
                ContextLiteralPath = $ContextLiteralPath; CatalogPath = $CatalogPath; GitPath = $GitPath
            }
            # The ordinary case and its frozen oracle are the positive control.
            # Genuine unavailable preflight observations retain the strict skip
            # contract; no failure is injected without a real successful link.
            $objPositive = & $script:scriptBlockInvokeTerraformCase @hashtableArguments
            $objPositiveResult = & $script:scriptBlockNewTerraformCaseResult -Case $objCase -Observation $objPositive -Runtime $Runtime -SourceIntegrityVerified $true
            if ($objPositiveResult.HarnessVerdict -ceq 'skip') {
                if ($EmitObservations) {
                    [pscustomobject]@{ Id = $strCaseId; PositiveVerdict = 'skip'; NegativeExecuted = $false; PrimitiveEvidence = $objPositiveResult.PrimitiveEvidence }
                }
                continue
            }
            if ($objPositiveResult.HarnessVerdict -cne 'pass') { throw 'late-link-positive-oracle' }
            if ([System.IO.Directory]::GetFileSystemEntries($strControlRoot).Count -ne 0) { throw 'late-link-positive-teardown' }
            $hashtableControl = @{ Calls = 0; ProbeSucceeded = $false; Target = $null; Before = $null; TargetChecked = $false }
            $script:scriptBlockNewSymbolicLink = {
                param ([string]$LinkPath, [string]$TargetPath, [bool]$Directory)
                $hashtableControl.Calls++
                if ($hashtableControl.Calls -eq 1) {
                    $hashtableControl.ProbeSucceeded = & $scriptBlockOriginalLink -LinkPath $LinkPath -TargetPath $TargetPath -Directory $Directory
                    return $hashtableControl.ProbeSucceeded
                }
                if ($hashtableControl.Calls -ne 2 -or -not $hashtableControl.ProbeSucceeded) { throw 'late-link-injection-order' }
                $hashtableControl.Target = $TargetPath
                $hashtableControl.Before = & $scriptBlockSnapshot -LiteralPath $TargetPath
                return $false
            }.GetNewClosure()
            $script:scriptBlockRemoveTestTree = {
                param ([string]$LiteralPath, [string]$ApprovedParent)
                if ($null -ne $hashtableControl.Target -and -not $hashtableControl.TargetChecked) {
                    $objAfter = & $scriptBlockSnapshot -LiteralPath $hashtableControl.Target
                    if (($objAfter.Entries -join "`n") -cne ($hashtableControl.Before.Entries -join "`n")) { throw 'late-link-target-changed' }
                    $hashtableControl.TargetChecked = $true
                }
                & $scriptBlockOriginalRemove -LiteralPath $LiteralPath -ApprovedParent $ApprovedParent
            }.GetNewClosure()
            $objFailure = $null
            $arrReturned = @()
            try { $arrReturned = @(& $script:scriptBlockInvokeTerraformCase @hashtableArguments) }
            catch { $objFailure = $_ }
            finally {
                $script:scriptBlockNewSymbolicLink = $scriptBlockOriginalLink
                $script:scriptBlockRemoveTestTree = $scriptBlockOriginalRemove
            }
            if ($null -eq $objFailure -or $arrReturned.Count -ne 0 -or
                $objFailure.Exception.Data['TerraformStyleGuideHarnessCode'] -cne 'fixture-failed' -or
                $objFailure.Exception.Data['TerraformStyleGuideSubreason'] -cne 'available-link-creation-failed' -or
                $hashtableControl.Calls -ne 2 -or -not $hashtableControl.ProbeSucceeded -or
                -not $hashtableControl.TargetChecked) { throw 'late-link-failure-contract' }
            if ([System.IO.Directory]::GetFileSystemEntries($strControlRoot).Count -ne 0) { throw 'late-link-negative-teardown' }
            if ($EmitObservations) {
                [pscustomobject]@{ Id = $strCaseId; PositiveVerdict = 'pass'; NegativeExecuted = $true; LateFailureCode = 'fixture-failed'; LinkCalls = $hashtableControl.Calls; RealPreflightSucceeded = $hashtableControl.ProbeSucceeded; TargetUnchanged = $hashtableControl.TargetChecked; TeardownEmpty = $true }
            }
        }
    } finally {
        $script:scriptBlockNewSymbolicLink = $scriptBlockOriginalLink
        $script:scriptBlockRemoveTestTree = $scriptBlockOriginalRemove
        & $scriptBlockOriginalRemove -LiteralPath $strControlRoot -ApprovedParent $RunRoot
    }
}


$script:scriptBlockGetTerraformRunIdentity = {
    param (
        [string]$RepositoryRoot, [string]$GitPath, [string]$HelperLiteralPath,
        [string]$ContextLiteralPath, [string]$CatalogPath, [string]$HarnessPath
    )

    $hashtableIdentity = [ordered]@{}
    foreach ($strRole in @('Helper', 'Context', 'Catalog', 'Harness')) {
        $strPath = switch -Exact ($strRole) {
            'Helper' { $HelperLiteralPath }
            'Context' { $ContextLiteralPath }
            'Catalog' { $CatalogPath }
            'Harness' { $HarnessPath }
        }
        $strRelative = switch -Exact ($strRole) {
            'Helper' { $script:strCandidateHelperRelativePath }
            'Context' { $script:strCandidateContextRelativePath }
            'Catalog' { $script:strCandidateCatalogRelativePath }
            'Harness' { '.github/workflows/Test-Expand-StyleGuideCandidateArtifact.ps1' }
        }
        & $script:scriptBlockAssertOrdinaryInputFileType -LiteralPath $strPath
        $hashtableArguments = @{ RepositoryRoot = $RepositoryRoot; GitPath = $GitPath; LiteralPath = $strPath; RelativePath = $strRelative }
        $strObjectId = if ($strRole -ceq 'Helper') {
            & $script:scriptBlockAssertTrackedScriptIdentity @hashtableArguments -ExpectedVersion $script:strCandidateExpectedHelperVersion -ExpectedFunctionCount ([uint32]1)
        } elseif ($strRole -ceq 'Context') {
            & $script:scriptBlockAssertTrackedScriptIdentity @hashtableArguments -ExpectedVersion $script:strCandidateExpectedContextVersion -ExpectedFunctionCount ([uint32]2)
        } else { & $script:scriptBlockAssertTrackedBlobIdentity @hashtableArguments }
        $objEvidence = & $script:scriptBlockGetFileEvidence -LiteralPath $strPath
        $hashtableIdentity[$strRole + 'Blob'] = $strObjectId
        $hashtableIdentity[$strRole + 'Sha256'] = $objEvidence.Sha256
        $hashtableIdentity[$strRole + 'Length'] = $objEvidence.Length
    }
    foreach ($strKind in @('Commit', 'Tree')) {
        $strRevision = if ($strKind -ceq 'Commit') { 'HEAD^{commit}' } else { 'HEAD^{tree}' }
        $objNative = & $script:scriptBlockInvokeNativeRaw -FilePath $GitPath -WorkingDirectory $RepositoryRoot -ArgumentList @('rev-parse', '--verify', $strRevision)
        if ($objNative.ExitCode -ne 0) { & $script:scriptBlockStopHarness -Code 'script-identity-invalid' -Detail 'run-head-status' }
        $strValue = & $script:scriptBlockGetTrimmedAsciiLine -Bytes $objNative.StandardOutput
        if ($strValue -cnotmatch '^(?:[0-9a-f]{40}|[0-9a-f]{64})$') { & $script:scriptBlockStopHarness -Code 'script-identity-invalid' -Detail 'run-head-shape' }
        $hashtableIdentity['Source' + $strKind] = $strValue
    }
    return $hashtableIdentity
}

$script:scriptBlockAssertTerraformResultPairs = {
    param ([object[]]$Expected, [object[]]$Results, [string]$RuntimeId, [switch]$Proof)

    $objExpected = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    foreach ($objRow in $Expected) {
        if (-not $objExpected.Add($objRow.Id)) { throw 'result-pair-expected-duplicate' }
    }
    $objSeen = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
    foreach ($objResult in $Results) {
        if ($null -eq $objResult -or $null -eq $objResult.PSObject.Properties['Id'] -or
            $null -eq $objResult.PSObject.Properties['Runtime'] -or
            $objResult.Runtime.Id -cne $RuntimeId -or -not $objExpected.Contains($objResult.Id)) { throw 'result-pair-unknown-or-orphan' }
        if (-not $objSeen.Add($objResult.Id)) { throw 'result-pair-duplicate' }
        if ($null -eq $objResult.PSObject.Properties['HarnessVerdict'] -or $objResult.HarnessVerdict -cnotin @('pass', 'fail', 'skip')) { throw 'result-pair-verdict' }
        if ($objResult.HarnessVerdict -ceq 'skip') {
            if ($Proof) { throw 'result-pair-proof-skip' }
            try {
                $objRow = @($Expected | Where-Object { $_.Id -ceq $objResult.Id })[0]
                foreach ($strName in @('ProbeAttempted', 'TargetControlPassed', 'ProbeSucceeded', 'ProductFixtureCreated', 'ProductScriptInvoked')) {
                    if ($objResult.PrimitiveEvidence.PSObject.Properties[$strName].Value -isnot [bool]) { throw 'invalid-type' }
                }
                if (-not $script:hashtableTerraformLinkCases.ContainsKey($objResult.Id) -or
                    $objResult.AppliedApplicabilityProfile -cne 'OP-SKIP-PRIMITIVE' -or
                    (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $objResult.DeclaredCase) -cne
                    (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $objRow) -or
                    $objResult.ExpectedResult -cne 'skip' -or $null -ne $objResult.ExpectedStatus -or
                    $objResult.ActualResult -cne 'skip' -or $null -ne $objResult.ActualStatus -or
                    $objResult.ActualPhase -cne 'applicability' -or $objResult.ActualSubreason -cne 'skip-link-primitive-unavailable' -or
                    $objResult.ActualInitialState -cne 'NotCreated' -or $objResult.ActualPreCleanupCandidateState -cne 'not-applicable' -or
                    $objResult.ActualContextState -cne 'not-created' -or $objResult.ActualCandidateState -cne 'not-applicable' -or
                    $null -ne $objResult.ActualFixture -or $objResult.ActualSourceRepositoryState -cne 'unchanged' -or
                    $objResult.PrimitiveEvidence.CaseId -cne $objResult.Id -or
                    $objResult.PrimitiveEvidence.Platform -cne $objResult.Runtime.Platform -or
                    $objResult.PrimitiveEvidence.Primitive -cne $script:hashtableTerraformLinkCases[$objResult.Id] -or
                    $objResult.PrimitiveEvidence.ProbeAttempted -cne $true -or $objResult.PrimitiveEvidence.TargetControlPassed -cne $true -or
                    $objResult.PrimitiveEvidence.ProbeSucceeded -cne $false -or $objResult.PrimitiveEvidence.ProductFixtureCreated -cne $false -or
                    $objResult.PrimitiveEvidence.ProductScriptInvoked -cne $false -or
                    $objResult.PrimitiveEvidence.Reason -cne 'ordinary-target-control-passed-link-create-or-reparse-verification-failed') { throw 'invalid' }
            } catch { throw 'result-pair-functional-skip' }
        }
    }
    if ($objSeen.Count -ne $objExpected.Count) { throw 'result-pair-missing' }
}

$script:scriptBlockCopyTerraformResultRows = {
    param ([object[]]$Results)

    # A named property retains the array shape on both Desktop and Core.
    $objEnvelope = [pscustomobject]@{ Rows = [object[]]$Results } |
        ConvertTo-Json -Depth 100 -Compress | ConvertFrom-Json
    return ,([object[]]@($objEnvelope.Rows))
}

$script:scriptBlockAssertTerraformResultRowCloning = {
    param ([object[]]$FullResults, [switch]$EmitObservations)

    $objControl = [pscustomobject]@{
        Id = 'T1A-CLONE-CONTROL'
        Runtime = [pscustomobject]@{ Id = 'diagnostic-validator-input' }
        Text = 'literal-text'; Flag = $true; EmptyValue = $null
        Integer = [long]7
        Nested = [object[]]@([object[]]@(1, 2), [object[]]@(), [object[]]@(9))
    }
    foreach ($hashtableControl in @(
        @{ Id = 'empty'; Rows = [object[]]@() },
        @{ Id = 'singleton'; Rows = [object[]]@($objControl) },
        @{ Id = 'two'; Rows = [object[]]@($objControl, $objControl) },
        @{ Id = 'full'; Rows = $FullResults }
    )) {
        $arrOriginal = [object[]]$hashtableControl.Rows
        $strOriginal = & $script:scriptBlockConvertToCanonicalCatalogJson -Value $arrOriginal
        [object[]]$arrClone = & $script:scriptBlockCopyTerraformResultRows -Results $arrOriginal
        if ($arrClone.Length -ne $arrOriginal.Length -or
            (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $arrClone) -cne $strOriginal) { throw 'result-clone-values' }
        if ($arrClone.Length -gt 0) {
            if ([object]::ReferenceEquals($arrOriginal[0], $arrClone[0]) -or
                [object]::ReferenceEquals($arrOriginal[0].Runtime, $arrClone[0].Runtime)) { throw 'result-clone-alias' }
            if ($hashtableControl.Id -cne 'full') {
                if ($arrClone[0].Text -isnot [string] -or $arrClone[0].Flag -isnot [bool] -or
                    $null -ne $arrClone[0].EmptyValue -or
                    ($arrClone[0].Integer -isnot [int] -and $arrClone[0].Integer -isnot [long]) -or
                    $arrClone[0].Nested -isnot [Array] -or $arrClone[0].Nested.Length -ne 3 -or
                    $arrClone[0].Nested[0] -isnot [Array] -or $arrClone[0].Nested[0].Length -ne 2 -or
                    $arrClone[0].Nested[1] -isnot [Array] -or $arrClone[0].Nested[1].Length -ne 0 -or
                    $arrClone[0].Nested[2] -isnot [Array] -or $arrClone[0].Nested[2].Length -ne 1) { throw 'result-clone-json-shape' }
                $arrClone[0].Nested[0][0] = 99
            }
            $arrClone[0].Id = 'T1A-CLONE-MUTATED'
            $arrClone[0].Runtime.Id = 'mutated-validator-input'
            if ((& $script:scriptBlockConvertToCanonicalCatalogJson -Value $arrOriginal) -cne $strOriginal) { throw 'result-clone-input-mutated' }
        }
        if ($EmitObservations) { [pscustomobject]@{ Scope = 'result-row-clone'; Id = $hashtableControl.Id; Rows = $arrOriginal.Length; DeepValuesPreserved = $true; IndependentMutation = $true } }
    }
}

$script:scriptBlockAssertTerraformResultPairMutants = {
    param ([object[]]$Expected, [object[]]$Results, [string]$RuntimeId, [switch]$Proof, [switch]$EmitObservations)

    & $script:scriptBlockAssertTerraformResultPairs -Expected $Expected -Results $Results -RuntimeId $RuntimeId -Proof:$Proof
    foreach ($strMode in @('missing', 'duplicate', 'unknown', 'multiple', 'orphan', 'skip')) {
        [object[]]$arrChanged = & $script:scriptBlockCopyTerraformResultRows -Results $Results
        $strReason = switch -Exact ($strMode) {
            'missing' { $arrChanged = @($arrChanged | Select-Object -Skip 1); 'result-pair-missing' }
            'duplicate' { $arrChanged += $arrChanged[0]; 'result-pair-duplicate' }
            'multiple' { $arrChanged += @($arrChanged[0], $arrChanged[0]); 'result-pair-duplicate' }
            'unknown' { $arrChanged[0].Id = 'T1A-UNKNOWN-99'; 'result-pair-unknown-or-orphan' }
            'orphan' { $arrChanged[0].Runtime.Id = 'UnknownRuntime'; 'result-pair-unknown-or-orphan' }
            'skip' { $arrChanged[0].HarnessVerdict = 'skip'; if ($Proof) { 'result-pair-proof-skip' } else { 'result-pair-functional-skip' } }
        }
        $strObserved = ''
        try { & $script:scriptBlockAssertTerraformResultPairs -Expected $Expected -Results $arrChanged -RuntimeId $RuntimeId -Proof:$Proof }
        catch { $strObserved = $_.Exception.Message }
        if ($strObserved -cne $strReason) { throw 'result-pair-mutant-not-refused' }
        if ($EmitObservations) { [pscustomobject]@{ Scope = 'result-pair-mutation'; Mode = $strMode; Proof = [bool]$Proof; Expected = $strReason; Actual = $strObserved; InputRows = $Results.Length } }
    }
}

$script:scriptBlockAssertTerraformProofEvidence = {
    param ([object]$Observation, [string]$Id, [System.Collections.IDictionary]$SourceIdentity)

    try {
        $scriptBlockInteger = {
            param ([object]$Value, [long]$Minimum, [long]$Maximum)
            if (($Value -isnot [int] -and $Value -isnot [long] -and $Value -isnot [uint32]) -or
                $Value -lt $Minimum -or $Value -gt $Maximum) { throw 'proof-integer-type-or-bound' }
        }
        & $scriptBlockInteger -Value $Observation.ActualStatus -Minimum 0 -Maximum 0
        if ($Observation.Id -cne $Id -or $Observation.ActualStatus -cne 0 -or
            $Observation.ActualPhase -cne 'harness-proof' -or
            (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $Observation.SourceIdentity) -cne
                (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $SourceIdentity)) { throw 'header' }
        if ($Id -ceq 'T1A-H-01') {
            & $script:scriptBlockAssertExactPropertyNames -Value $Observation -Names @('Id', 'SemanticCase', 'ActualStatus', 'ActualPhase', 'SourceIdentity', 'SourceCopies', 'Trace', 'ProcessExit', 'ProcessId', 'CandidateState', 'ContextState') -Detail 'h01-observation'
            if ($Observation.SemanticCase -cne 'harness.resource.bounded-cardinality-enumeration' -or
                $Observation.ProcessExit -cne 0 -or $Observation.ProcessId -le 0 -or
                $Observation.CandidateState -cne 'not-applicable' -or $Observation.ContextState -cne 'not-created' -or
                $Observation.SourceCopies -isnot [System.Array] -or $Observation.SourceCopies.Count -ne 2) { throw 'h01-header' }
            $objRoles = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
            & $scriptBlockInteger -Value $Observation.ProcessExit -Minimum 0 -Maximum 0
            & $scriptBlockInteger -Value $Observation.ProcessId -Minimum 1 -Maximum ([int]::MaxValue)
            foreach ($objCopy in $Observation.SourceCopies) {
                & $script:scriptBlockAssertExactPropertyNames -Value $objCopy -Names @('Role', 'SourceSha256', 'DerivedSha256', 'MutantSha256', 'Transformation', 'EagerMutantExecuted', 'EagerMutantReason') -Detail 'h01-source-copy'
                foreach ($strName in @('Role', 'SourceSha256', 'DerivedSha256', 'MutantSha256', 'Transformation', 'EagerMutantReason')) {
                    if ($objCopy.PSObject.Properties[$strName].Value -isnot [string]) { throw 'h01-copy-string' }
                }
                if ($objCopy.Role -cnotin @('helper', 'context') -or -not $objRoles.Add($objCopy.Role) -or
                    $objCopy.SourceSha256 -cne $SourceIdentity[$objCopy.Role + 'Sha256'] -or
                    $objCopy.DerivedSha256 -cnotmatch '^[0-9a-f]{64}$' -or $objCopy.MutantSha256 -cnotmatch '^[0-9a-f]{64}$' -or
                    $objCopy.Transformation -cne 'one-unfiltered-enumerator-call-to-real-delegating-counter-v1' -or
                    $objCopy.EagerMutantExecuted -isnot [bool] -or $objCopy.EagerMutantExecuted -or
                    $objCopy.EagerMutantReason -cne 'enumeration-unfiltered-source-shape') { throw 'h01-copy' }
            }
            $objTrace = $Observation.Trace
            & $script:scriptBlockAssertExactPropertyNames -Value $objTrace -Names @('Runtime', 'ParserErrors', 'ProcessId', 'Records') -Detail 'h01-trace'
            & $scriptBlockInteger -Value $objTrace.ParserErrors -Minimum 0 -Maximum 0
            & $scriptBlockInteger -Value $objTrace.ProcessId -Minimum 1 -Maximum ([int]::MaxValue)
            if ($objTrace.Runtime -cne $PSVersionTable.PSVersion.ToString() -or $objTrace.ParserErrors -cne 0 -or
                $objTrace.ProcessId -ne $Observation.ProcessId -or $objTrace.Records -isnot [System.Array] -or $objTrace.Records.Count -ne 18) { throw 'h01-trace-header' }
            $objKeys = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
            foreach ($objRecord in $objTrace.Records) {
                & $script:scriptBlockAssertExactPropertyNames -Value $objRecord -Names @('Role', 'Existing', 'Expected', 'Maximum', 'Advances', 'Disposals', 'Returned') -Detail 'h01-trace-record'
                foreach ($strName in @('Existing', 'Expected', 'Maximum', 'Advances', 'Disposals', 'Returned')) {
                    $objValue = $objRecord.PSObject.Properties[$strName].Value
                    if (($objValue -isnot [int] -and $objValue -isnot [long]) -or $objValue -lt 0 -or $objValue -gt 64) { throw 'h01-counter-type' }
                }
                if ($objRecord.Role -cnotin @('helper', 'manager') -or $objRecord.Existing -notin @(0, 3, 12) -or
                    $objRecord.Expected -notin @(0, 1, 4) -or $objRecord.Maximum -ne ($objRecord.Expected + 1) -or
                    $objRecord.Advances -gt $objRecord.Maximum -or $objRecord.Disposals -ne 1 -or
                    $objRecord.Returned -ne [Math]::Min($objRecord.Existing, $objRecord.Maximum) -or
                    -not $objKeys.Add($objRecord.Role + ':' + $objRecord.Existing + ':' + $objRecord.Expected)) { throw 'h01-bound' }
            }
        } elseif ($Id -ceq 'T1A-H-02') {
            & $script:scriptBlockAssertExactPropertyNames -Value $Observation -Names @('Id', 'SemanticCase', 'ActualStatus', 'ActualPhase', 'SourceIdentity', 'HelperSourceSha256', 'ContextSourceSha256', 'DerivedHelperSha256', 'DerivedContextSha256', 'Transformation', 'Records') -Detail 'h02-observation'
            foreach ($strName in @('HelperSourceSha256', 'ContextSourceSha256', 'DerivedHelperSha256', 'DerivedContextSha256', 'Transformation')) {
                if ($Observation.PSObject.Properties[$strName].Value -isnot [string]) { throw 'h02-source-string' }
            }
            if ($Observation.DerivedContextSha256 -cne $Observation.ContextSourceSha256) { throw 'h02-context-copy-changed' }
            if ($Observation.SemanticCase -cne 'harness.race.pre-journal-population-retained' -or
                $Observation.HelperSourceSha256 -cne $SourceIdentity.HelperSha256 -or $Observation.ContextSourceSha256 -cne $SourceIdentity.ContextSha256 -or
                $Observation.DerivedHelperSha256 -cnotmatch '^[0-9a-f]{64}$' -or $Observation.DerivedContextSha256 -cnotmatch '^[0-9a-f]{64}$' -or
                $Observation.Transformation -cne 'one-candidate-create-anchor-append-ready-release-before-next-statement-v1' -or
                $Observation.Records -isnot [System.Array] -or $Observation.Records.Count -ne 2) { throw 'h02-header' }
            $objCases = New-Object 'System.Collections.Generic.HashSet[string]' ([System.StringComparer]::Ordinal)
            foreach ($objRecord in $Observation.Records) {
                & $script:scriptBlockAssertExactPropertyNames -Value $objRecord -Names @('Case', 'ReadyObserved', 'ReleasedAfterWrite', 'WriterProcessId', 'WorkerProcessId', 'WorkerExit', 'Observation') -Detail 'h02-record'
                & $scriptBlockInteger -Value $objRecord.WorkerExit -Minimum 0 -Maximum 0
                & $scriptBlockInteger -Value $objRecord.WriterProcessId -Minimum 1 -Maximum ([int]::MaxValue)
                & $scriptBlockInteger -Value $objRecord.WorkerProcessId -Minimum 1 -Maximum ([int]::MaxValue)
                if ($objRecord.Case -cnotin @('control', 'perturbation') -or -not $objCases.Add($objRecord.Case) -or
                    $objRecord.ReadyObserved -isnot [bool] -or -not $objRecord.ReadyObserved -or
                    $objRecord.ReleasedAfterWrite -isnot [bool] -or $objRecord.ReleasedAfterWrite -ne ($objRecord.Case -ceq 'perturbation') -or
                    $objRecord.WorkerExit -cne 0 -or $objRecord.WriterProcessId -le 0 -or $objRecord.WorkerProcessId -le 0 -or
                    $objRecord.WriterProcessId -eq $objRecord.WorkerProcessId) { throw 'h02-synchronization' }
                $objValue = $objRecord.Observation
                & $script:scriptBlockAssertExactPropertyNames -Value $objValue -Names @('Phase', 'Subreason', 'CandidateState', 'ContextState', 'SentinelBytes', 'CandidateJournalCount', 'CandidateRemovedPaths', 'ContextRemovedPaths', 'WorkerProcessId', 'CandidatePath', 'ParserErrors') -Detail 'h02-worker'
                & $scriptBlockInteger -Value $objValue.WorkerProcessId -Minimum 1 -Maximum ([int]::MaxValue)
                & $scriptBlockInteger -Value $objValue.ParserErrors -Minimum 0 -Maximum 0
                & $scriptBlockInteger -Value $objValue.CandidateJournalCount -Minimum 1 -Maximum 5
                if ($objValue.CandidatePath -isnot [string] -or $objValue.CandidatePath.Length -eq 0) { throw 'h02-candidate-path-type' }
                foreach ($objPaths in @($objValue.CandidateRemovedPaths, $objValue.ContextRemovedPaths)) {
                    if ($objPaths -isnot [System.Array]) { throw 'h02-path-array' }
                    foreach ($objPath in $objPaths) { if ($objPath -isnot [string] -or $objPath.Length -eq 0) { throw 'h02-path-type' } }
                }
                if ($objValue.WorkerProcessId -ne $objRecord.WorkerProcessId -or $objValue.ParserErrors -cne 0 -or
                    $objValue.CandidateRemovedPaths -isnot [System.Array] -or $objValue.ContextRemovedPaths -isnot [System.Array]) { throw 'h02-worker' }
                if ($objRecord.Case -ceq 'control') {
                    if ($objValue.Phase -cne 'complete' -or $objValue.Subreason -cne 'none' -or
                        $objValue.CandidateState -cne 'Disposed' -or $objValue.ContextState -cne 'Disposed' -or
                        $null -ne $objValue.SentinelBytes -or $objValue.CandidateJournalCount -ne 5 -or
                        $objValue.CandidateRemovedPaths.Count -ne 5 -or $objValue.ContextRemovedPaths.Count -ne 3) { throw 'h02-control' }
                } else {
                    $strSentinel = [System.Convert]::ToBase64String([System.Text.Encoding]::UTF8.GetBytes("h02-competing-sentinel`n"))
                    if ($objValue.Phase -cne 'destination' -or $objValue.Subreason -cne 'pre-journal-populated' -or
                        $objValue.CandidateState -cne 'RetainedUncertain' -or $objValue.ContextState -cne 'RetainedUncertain' -or
                        $objValue.SentinelBytes -cne $strSentinel -or $objValue.CandidateJournalCount -ne 1 -or
                        $objValue.CandidateRemovedPaths.Count -ne 0 -or $objValue.ContextRemovedPaths.Count -ne 0) { throw 'h02-perturbation' }
                }
            }
        } else { throw 'proof-id' }
    } catch { throw 'proof-evidence-invalid' }
}

$script:scriptBlockAssertTerraformProofEvidenceMutants = {
    param ([object]$Observation, [string]$Id, [System.Collections.IDictionary]$SourceIdentity)

    & $script:scriptBlockAssertTerraformProofEvidence -Observation $Observation -Id $Id -SourceIdentity $SourceIdentity
    $arrModes = if ($Id -ceq 'T1A-H-01') {
        @('missing-copies', 'copy-hash', 'executed-mutant', 'missing-counter', 'exceeded-bound', 'duplicate-trace', 'parser-error', 'source-identity', 'status-string', 'parser-string', 'pid-string')
    } else { @('missing-record', 'missing-sync', 'same-process', 'missing-state', 'sentinel-changed', 'sentinel-deleted', 'parser-error', 'source-identity', 'status-string', 'parser-string', 'pid-string', 'context-copy-changed', 'removed-path-type') }
    $intRefused = 0
    foreach ($strMode in $arrModes) {
        $objChanged = $Observation | ConvertTo-Json -Depth 30 -Compress | ConvertFrom-Json
        switch -Exact ($strMode) {
            'missing-copies' { $objChanged.PSObject.Properties.Remove('SourceCopies') }
            'copy-hash' { $objChanged.SourceCopies[0].SourceSha256 = '0' * 64 }
            'executed-mutant' { $objChanged.SourceCopies[0].EagerMutantExecuted = $true }
            'missing-counter' { $objChanged.Trace.Records[0].PSObject.Properties.Remove('Advances') }
            'exceeded-bound' { $objChanged.Trace.Records[0].Advances = 64 }
            'duplicate-trace' { $objChanged.Trace.Records[1] = $objChanged.Trace.Records[0] }
            'missing-record' { $objChanged.Records = @($objChanged.Records[0]) }
            'missing-sync' { $objChanged.Records[1].PSObject.Properties.Remove('ReadyObserved') }
            'same-process' { $objChanged.Records[1].WriterProcessId = $objChanged.Records[1].WorkerProcessId }
            'missing-state' { $objChanged.Records[1].Observation.PSObject.Properties.Remove('CandidateState') }
            'sentinel-changed' { $objChanged.Records[1].Observation.SentinelBytes = 'YQ==' }
            'sentinel-deleted' { $objChanged.Records[1].Observation.CandidateRemovedPaths = @('controlled-path') }
            'parser-error' { if ($Id -ceq 'T1A-H-01') { $objChanged.Trace.ParserErrors = 1 } else { $objChanged.Records[1].Observation.ParserErrors = 1 } }
            'source-identity' { $objChanged.SourceIdentity.HelperSha256 = '0' * 64 }
            'status-string' { $objChanged.ActualStatus = '0' }
            'parser-string' { if ($Id -ceq 'T1A-H-01') { $objChanged.Trace.ParserErrors = '0' } else { $objChanged.Records[1].Observation.ParserErrors = '0' } }
            'pid-string' { if ($Id -ceq 'T1A-H-01') { $objChanged.ProcessId = [string]$objChanged.ProcessId } else { $objChanged.Records[1].WorkerProcessId = [string]$objChanged.Records[1].WorkerProcessId } }
            'context-copy-changed' { $objChanged.DerivedContextSha256 = '0' * 64 }
            'removed-path-type' { $objChanged.Records[0].Observation.CandidateRemovedPaths[0] = 42 }
        }
        $strObserved = ''
        try { & $script:scriptBlockAssertTerraformProofEvidence -Observation $objChanged -Id $Id -SourceIdentity $SourceIdentity }
        catch { $strObserved = $_.Exception.Message }
        if ($strObserved -cne 'proof-evidence-invalid') { throw 'proof-evidence-mutant-not-refused' }
        $intRefused++
    }
    return [pscustomobject]@{ ProofId = $Id; PositiveControlPassed = $true; MutantsRefused = $intRefused }
}

$script:scriptBlockAssertTerraformSkipProjectionMutants = {
    param ([object]$Catalog, [System.Collections.IDictionary]$Runtime)

    # This is a metadata admission assertion, never a functional case or an
    # observation that a primitive was unavailable on this machine.
    $objCase = @($Catalog.Cases | Where-Object { $_.Id -ceq 'T1A-E-09' })[0]
    $objControl = [pscustomobject][ordered]@{
        ActualResult = 'skip'; ActualStatus = $null; ActualPhase = 'applicability'
        ActualSubreason = 'skip-link-primitive-unavailable'; ActualInitialState = 'NotCreated'
        ActualPreCleanupCandidateState = 'not-applicable'; ActualCandidateState = 'not-applicable'
        ActualContextState = 'not-created'; ActualCleanupSequence = [string[]]@('none')
        ActualSentinelState = 'unchanged'; PrimitiveProbeAttempted = $true
        PrimitiveTargetControlPassed = $true; PrimitiveProbeSucceeded = $false; Primitive = 'directory'
        ProbeFailureReason = 'ordinary-target-control-passed-link-create-or-reparse-verification-failed'
        ProductFixtureCreated = $false; ProductScriptInvoked = $false
    }
    $objResult = & $script:scriptBlockNewTerraformPrimitiveSkipResult -Case $objCase -Observation $objControl -Runtime $Runtime -SourceIntegrityVerified $true
    & $script:scriptBlockAssertTerraformResultPairs -Expected @($objCase) -Results @($objResult) -RuntimeId $Runtime.Id
    foreach ($strMode in @('missing-initial', 'wrong-initial', 'missing-precleanup', 'wrong-precleanup', 'boolean-string', 'unknown-property', 'product-invoked', 'control-failed')) {
        $objChanged = $objControl | ConvertTo-Json -Depth 8 -Compress | ConvertFrom-Json
        switch -Exact ($strMode) {
            'missing-initial' { $objChanged.PSObject.Properties.Remove('ActualInitialState') }
            'wrong-initial' { $objChanged.ActualInitialState = 'Active' }
            'missing-precleanup' { $objChanged.PSObject.Properties.Remove('ActualPreCleanupCandidateState') }
            'wrong-precleanup' { $objChanged.ActualPreCleanupCandidateState = 'four-valid-files' }
            'boolean-string' { $objChanged.PrimitiveProbeAttempted = 'True' }
            'unknown-property' { Add-Member -InputObject $objChanged -NotePropertyName Unexpected -NotePropertyValue $true }
            'product-invoked' { $objChanged.ProductScriptInvoked = $true }
            'control-failed' { $objChanged.PrimitiveTargetControlPassed = $false }
        }
        $boolRefused = $false
        try { [void](& $script:scriptBlockNewTerraformPrimitiveSkipResult -Case $objCase -Observation $objChanged -Runtime $Runtime -SourceIntegrityVerified $true) }
        catch {
            $boolRefused = $_.Exception.Message -ceq 'functional-skip-invalid' -or
                $_.Exception.Data['TerraformStyleGuideSubreason'] -cin @('primitive-skip-observation-property-count', 'primitive-skip-observation-property-order')
        }
        if (-not $boolRefused) { throw 'skip-projection-mutant-not-refused' }
    }
    foreach ($strMode in @('unknown-case', 'successful-probe', 'string-boolean', 'missing-evidence', 'wrong-platform')) {
        $objChanged = $objResult | ConvertTo-Json -Depth 30 -Compress | ConvertFrom-Json
        switch -Exact ($strMode) {
            'unknown-case' { $objChanged.Id = 'T1A-V-01' }
            'successful-probe' { $objChanged.PrimitiveEvidence.ProbeSucceeded = $true }
            'string-boolean' { $objChanged.PrimitiveEvidence.ProbeAttempted = 'True' }
            'missing-evidence' { $objChanged.PSObject.Properties.Remove('PrimitiveEvidence') }
            'wrong-platform' { $objChanged.PrimitiveEvidence.Platform = 'unknown' }
        }
        $strObserved = ''
        try { & $script:scriptBlockAssertTerraformResultPairs -Expected @($objCase) -Results @($objChanged) -RuntimeId $Runtime.Id }
        catch { $strObserved = $_.Exception.Message }
        if ($strObserved -cnotin @('result-pair-functional-skip', 'result-pair-unknown-or-orphan')) { throw 'skip-collector-mutant-not-refused' }
    }
}
$script:scriptBlockNewTerraformProofResult = {
    param ([object]$Row, [object]$Observation, [System.Collections.IDictionary]$Runtime, [System.Collections.IDictionary]$SourceIdentity)

    & $script:scriptBlockAssertTerraformProofEvidence -Observation $Observation -Id $Row.Id -SourceIdentity $SourceIdentity
    if ($Observation.Id -cne $Row.Id -or $Observation.SemanticCase -cne $Row.SemanticCase -or
        $Observation.ActualStatus -ne 0 -or $Observation.ActualPhase -cne 'harness-proof') { throw 'proof-result-observation' }
    $hashtableResult = [ordered]@{}
    foreach ($strField in @('Id', 'SemanticCase', 'Applicability', 'ProductionBoundary', 'Control', 'Perturbation', 'ExpectedStatus', 'ExpectedPhase', 'ExpectedPostcondition')) {
        $hashtableResult[$strField] = $Row.PSObject.Properties[$strField].Value
    }
    $hashtableResult.Runtime = [pscustomobject]$Runtime
    $hashtableResult.ActualStatus = $Observation.ActualStatus
    $hashtableResult.ActualPhase = $Observation.ActualPhase
    $hashtableResult.SourceIdentity = [pscustomobject]$Observation.SourceIdentity
    if ($Row.Id -ceq 'T1A-H-01') {
        $hashtableResult.SourceCopies = $Observation.SourceCopies
        $hashtableResult.Trace = $Observation.Trace
        $hashtableResult.ProcessExit = $Observation.ProcessExit
        $hashtableResult.ProcessId = $Observation.ProcessId
        $hashtableResult.ActualCandidateState = $Observation.CandidateState
        $hashtableResult.ActualContextState = $Observation.ContextState
    } else {
        foreach ($strField in @('HelperSourceSha256', 'ContextSourceSha256', 'DerivedHelperSha256', 'DerivedContextSha256', 'Transformation')) {
            $hashtableResult[$strField] = $Observation.PSObject.Properties[$strField].Value
        }
        $listRecords = New-Object 'System.Collections.Generic.List[pscustomobject]'
        foreach ($objRecord in $Observation.Records) {
            $objValue = $objRecord.Observation
            $listRecords.Add([pscustomobject][ordered]@{
                Case = $objRecord.Case; ReadyObserved = $objRecord.ReadyObserved
                ReleasedAfterWrite = $objRecord.ReleasedAfterWrite
                WriterProcessId = $objRecord.WriterProcessId; WorkerProcessId = $objRecord.WorkerProcessId
                WorkerExit = $objRecord.WorkerExit; ParserErrors = $objValue.ParserErrors
                ActualPhase = $objValue.Phase; ActualSubreason = $objValue.Subreason
                ActualCandidateState = $objValue.CandidateState; ActualContextState = $objValue.ContextState
                SentinelBytes = $objValue.SentinelBytes
                CandidateRemovedCount = @($objValue.CandidateRemovedPaths).Count
                ContextRemovedCount = @($objValue.ContextRemovedPaths).Count
            })
        }
        $hashtableResult.Records = $listRecords.ToArray()
    }
    $hashtableResult.HarnessVerdict = 'pass'
    return [pscustomobject]$hashtableResult
}


# Final failure output contains only fixed, reviewed diagnostic tokens. Source
# assertion details can include parsed source text, so even our own exception
# namespace is insufficient to admit arbitrary detail text to stderr.
$script:scriptBlockGetTerraformMainFailure = {
    param (
        [Parameter(Mandatory = $true)]
        [System.Management.Automation.ErrorRecord]$Failure,

        [string]$Stage = 'startup'
    )

    $strCode = 'unexpected-error'
    $strPhase = 'harness'
    $strReason = 'unexpected-error'
    $objCode = $Failure.Exception.Data['TerraformStyleGuideHarnessCode']
    if ($null -eq $objCode) {
        $objCode = $Failure.Exception.Data['TerraformStyleGuideDiagnosticCode']
    }
    $objPhase = $Failure.Exception.Data['TerraformStyleGuidePhase']
    $objReason = $Failure.Exception.Data['TerraformStyleGuideSubreason']
    $arrCodes = [string[]]@(
        'catalog-invalid', 'fixture-failed', 'git-tool-failure', 'harness-input',
        'invalid-version', 'orchestration-failed', 'parameter',
        'script-identity-invalid', 'unexpected-version'
    )
    $arrPhases = [string[]]@('catalog', 'harness-input', 'parameter', 'identity')
    $arrReasons = [string[]]@(
        'path-null', 'path-type', 'path-empty', 'path-whitespace', 'path-malformed',
        'path-wildcard', 'path-not-fully-qualified', 'path-provider',
        'HelperPath-length', 'ContextManagerPath-length',
        'HelperPath-normalization', 'ContextManagerPath-normalization',
        'HelperPath-fixed-path', 'ContextManagerPath-fixed-path',
        'script-missing', 'script-reparse', 'working-file-type',
        'directory-identity', 'directory-attribute', 'directory-component',
        'directory-mount', 'metadata-byte', 'record-termination',
        'record-cardinality', 'record-tab', 'literal-path', 'native-line',
        'tree-record', 'index-record', 'index-stage', 'index-status',
        'head-status', 'native-start', 'native-timeout', 'native-output-bound',
        'native-exit', 'git-missing', 'working-oid', 'index-oid', 'head-oid',
        'object-format', 'repository-root', 'repository-prefix',
        'run-head-status', 'run-head-shape', 'context-load-output',
        'helper-load-output', 'source-state-changed', 'unsupported-runtime',
        'temporary-inside-repository', 'observation-cardinality',
        'required-link-coverage', 'run-context-not-disposed', 'case-failure',
        'header', 'schema', 'duplicate-id', 'duplicate-semantic', 'canonical',
        'catalog-byte-sha256', 'catalog-canonical-sha256', 'allocation',
        'function', 'marker-count', 'marker-grammar', 'component', 'date',
        'binding', 'proof-evidence-invalid', 'proof-result-bound',
        'h01-worker-failed', 'h02-worker-failed', 'h02-control', 'h02-perturbation',
        'authoritative-catalog-mutated', 'canonical-value-type', 'catalog',
        'catalog-byte-identity', 'catalog-mutation-case-unknown',
        'counterpart-classification-missing', 'counterpart-set', 'counterpart-source',
        'counterpart-target', 'counterpart-target-missing', 'duplicate-local-id',
        'duplicate-semantic-key', 'equal-key-oracle-differs', 'file-type',
        'fixed-catalog-field-changed', 'function-count', 'head-object',
        'id-key-mapping-changed', 'intentional-difference-rationale-missing',
        'json', 'missing-local-id', 'missing-semantic-key', 'mutation-path-occupied',
        'object-format-status', 'oracle-profile-missing', 'oracle-profile-set',
        'parser', 'proof-allocation', 'proof-manifest', 'proof-row', 'proof-row-value',
        'repository-output', 'repository-status', 'script-untracked',
        'source-provenance', 'source-provenance-identity', 'target-only-classification',
        'target-only-row', 'terraform-catalog', 'terraform-cleanup-operation',
        'terraform-header', 'terraform-profile', 'terraform-result-status',
        'terraform-row', 'terraform-row-enum', 'tree-status', 'working-object',
        'working-status'
    )
    if ($objCode -is [string] -and $arrCodes -ccontains $objCode -and
        $objPhase -is [string] -and $arrPhases -ccontains $objPhase) {
        $strCode = $objCode
        $strPhase = $objPhase
        $strReason = 'validation-failed'
        if ($objReason -is [string] -and $arrReasons -ccontains $objReason) {
            $strReason = $objReason
        }
    }
    $strStage = if ($Stage -cin @('startup', 'source-assertions', 'functional-cases',
            'harness-proofs', 'download-leaf-assertion', 'result-sealing')) {
        $Stage
    } else {
        'unknown-stage'
    }
    return [pscustomobject][ordered]@{
        Schema = 'TerraformStyleGuide.CandidateHarnessFailure.v1'
        Stage = $strStage
        Code = $strCode
        Phase = $strPhase
        Subreason = $strReason
        Status = 1
    }
}

$script:scriptBlockAssertTerraformMainFailureProjection = {
    $objKnown = & $script:scriptBlockNewHarnessException -Code 'harness-input' -Detail 'script-missing'
    $objKnownRecord = New-Object System.Management.Automation.ErrorRecord(
        $objKnown, 'known', [System.Management.Automation.ErrorCategory]::InvalidData, $null)
    $objKnownResult = & $script:scriptBlockGetTerraformMainFailure -Failure $objKnownRecord
    if ($objKnownResult.Code -cne 'harness-input' -or $objKnownResult.Phase -cne 'harness-input' -or
        $objKnownResult.Subreason -cne 'script-missing' -or $objKnownResult.Status -ne 1) {
        throw 'main-failure-known-control'
    }
    $strHostile = 'DO-NOT-EMIT-PRIVATE-PATH-CONTENT-OR-STDERR'
    $objHostile = New-Object System.InvalidOperationException($strHostile)
    $objHostile.Data['TerraformStyleGuideHarnessCode'] = $strHostile
    $objHostile.Data['TerraformStyleGuidePhase'] = $strHostile
    $objHostile.Data['TerraformStyleGuideSubreason'] = $strHostile
    $objHostileRecord = New-Object System.Management.Automation.ErrorRecord(
        $objHostile, $strHostile, [System.Management.Automation.ErrorCategory]::InvalidData, $strHostile)
    $objHostileResult = & $script:scriptBlockGetTerraformMainFailure -Failure $objHostileRecord
    if ($objHostileResult.Code -cne 'unexpected-error' -or $objHostileResult.Phase -cne 'harness' -or
        $objHostileResult.Subreason -cne 'unexpected-error') {
        throw 'main-failure-unknown-control'
    }
    $objKnown.Data['TerraformStyleGuideSubreason'] = $strHostile
    $objDetailResult = & $script:scriptBlockGetTerraformMainFailure -Failure $objKnownRecord
    if ($objDetailResult.Code -cne 'harness-input' -or $objDetailResult.Phase -cne 'harness-input' -or
        $objDetailResult.Subreason -cne 'validation-failed') {
        throw 'main-failure-detail-control'
    }
    $objKnown.Data['TerraformStyleGuideSubreason'] = [object[]]@('script-missing')
    $objTypeResult = & $script:scriptBlockGetTerraformMainFailure -Failure $objKnownRecord
    if ($objTypeResult.Subreason -cne 'validation-failed') {
        throw 'main-failure-type-control'
    }
    $objStageResult = & $script:scriptBlockGetTerraformMainFailure -Failure $objKnownRecord -Stage $strHostile
    if ($objStageResult.Stage -cne 'unknown-stage') {
        throw 'main-failure-stage-control'
    }
}

function Invoke-StyleGuideCandidateHarness {
    # .SYNOPSIS
    # Executes the authenticated Terraform case and proof manifests.
    #
    # .DESCRIPTION
    # Authenticates the fixed production scripts, loads their public functions,
    # executes every applicable catalog row and both named harness proofs for
    # the current runtime, then emits canonical JSONL results and one run
    # envelope after final source identity verification. Opposite-platform
    # rows do not enter this runtime's result set.
    #
    # .EXAMPLE
    # Invoke-StyleGuideCandidateHarness
    #
    # # Emits applicable case results, both proof results, and one run envelope.
    #
    # .EXAMPLE
    # $arrCaseJson = @(Invoke-StyleGuideCandidateHarness)
    #
    # # Captures the complete canonical JSONL projection for further validation.
    #
    # .INPUTS
    # None. You can't pipe objects to this function.
    #
    # .OUTPUTS
    # [string] Canonical JSONL case results, proof results, and run envelope.
    #
    # .NOTES
    # PRIVATE/INTERNAL HELPER - This function is not part of the public API
    # surface. Parameters, return shape, and positional contract may change
    # without notice.
    #
    # Positional binding is disabled. This function accepts no parameters;
    # this is an internal-caller contract only, subject to change.
    #
    # This function consumes only the fixed script parameters and repository
    # paths established by the enclosing trusted harness.
    #
    # Version: 1.0.20260924.1
    [CmdletBinding(PositionalBinding = $false)]
    [OutputType([string])]
    param ()

    Set-StrictMode -Version Latest

    $strRepositoryRoot = [System.IO.Path]::GetFullPath(
        [System.IO.Path]::Combine($PSScriptRoot, '..', '..')
    )
    $strExpectedHelperPath = [System.IO.Path]::GetFullPath(
        [System.IO.Path]::Combine(
            $strRepositoryRoot,
            $script:strCandidateHelperRelativePath.Replace(
                '/',
                [System.IO.Path]::DirectorySeparatorChar
            )
        )
    )
    $strExpectedContextPath = [System.IO.Path]::GetFullPath(
        [System.IO.Path]::Combine(
            $strRepositoryRoot,
            $script:strCandidateContextRelativePath.Replace(
                '/',
                [System.IO.Path]::DirectorySeparatorChar
            )
        )
    )
    $strCatalogPath = [System.IO.Path]::GetFullPath(
        [System.IO.Path]::Combine(
            $strRepositoryRoot,
            $script:strCandidateCatalogRelativePath.Replace(
                '/',
                [System.IO.Path]::DirectorySeparatorChar
            )
        )
    )
    $strHelperLiteralPath = & $script:scriptBlockResolveFixedScriptClaim `
        -Value $script:objCandidateHelperPathClaim `
        -Name 'HelperPath' `
        -ExpectedPath $strExpectedHelperPath
    $strContextLiteralPath = & $script:scriptBlockResolveFixedScriptClaim `
        -Value $script:objCandidateContextManagerPathClaim `
        -Name 'ContextManagerPath' `
        -ExpectedPath $strExpectedContextPath

    [void](& $script:scriptBlockAssertOrdinaryDirectoryEnvelope `
        -LiteralPath $strRepositoryRoot)

    # Git is the root of this harness's trust: every HEAD, index, mode, and
    # working-object claim below is whatever this binary says it is. Resolving
    # it through PATH made that root as movable as PATH, and PATH is not a
    # trusted input. Get-Command -CommandType Application closes command
    # *precedence* -- no alias or function can shadow the name -- but -All
    # returns PATH order, so element zero is simply the earliest PATH match. On
    # a GitHub-hosted runner any earlier step, composite action, or third-party
    # action becomes that match by appending one line to $env:GITHUB_PATH,
    # which the platform documents as "Prepends a directory to the system PATH
    # variable and automatically makes it available to all subsequent actions
    # in the current job." No compromise is required, and a benign action that
    # ships its own bin directory would silently author the identity proof.
    #
    # Reproduced before this change: a shell script named git placed on PATH
    # resolved as element zero and passed through to the real binary
    # convincingly enough to look ordinary.
    #
    # The fixed locations below are read through GetFolderPath rather than
    # %ProgramFiles% so the Windows list does not depend on another environment
    # variable. What remains trusted is the resolved file itself: an attacker
    # who can write /usr/bin/git or the Program Files copy already owns the
    # runner, and no check here would survive that.
    $arrGitCandidatePath = if ($script:boolCandidateIsWindows) {
        $strProgramFiles = [System.Environment]::GetFolderPath(
            [System.Environment+SpecialFolder]::ProgramFiles)
        $strProgramFilesX86 = [System.Environment]::GetFolderPath(
            [System.Environment+SpecialFolder]::ProgramFilesX86)
        [string[]]@(
            [System.IO.Path]::Combine($strProgramFiles, 'Git', 'cmd', 'git.exe'),
            [System.IO.Path]::Combine($strProgramFiles, 'Git', 'bin', 'git.exe'),
            [System.IO.Path]::Combine($strProgramFilesX86, 'Git', 'cmd', 'git.exe'),
            [System.IO.Path]::Combine($strProgramFilesX86, 'Git', 'bin', 'git.exe')
        )
    } else {
        [string[]]@('/usr/bin/git', '/bin/git', '/usr/local/bin/git')
    }
    $strGitPath = ''
    foreach ($strGitCandidate in $arrGitCandidatePath) {
        if ($strGitCandidate.Length -eq 0) {
            continue
        }
        try {
            $objGitAttributes = [System.IO.File]::GetAttributes($strGitCandidate)
        } catch {
            continue
        }
        if (($objGitAttributes -band ([System.IO.FileAttributes]::Directory -bor
                    [System.IO.FileAttributes]::ReparsePoint)) -ne 0) {
            continue
        }
        try { & $script:scriptBlockAssertOrdinaryInputFileType -LiteralPath $strGitCandidate }
        catch { continue }
        $strGitPath = [string]$strGitCandidate
        break
    }
    if ($strGitPath.Length -eq 0) {
        & $script:scriptBlockStopHarness -Code 'script-identity-invalid' -Detail 'git-missing'
    }
    & $script:scriptBlockAssertOrdinaryScriptInput -LiteralPath $strHelperLiteralPath
    & $script:scriptBlockAssertOrdinaryScriptInput -LiteralPath $strContextLiteralPath
    $hashtableHelperEvidenceBefore = & $script:scriptBlockGetFileEvidence `
        -LiteralPath $strHelperLiteralPath
    $hashtableContextEvidenceBefore = & $script:scriptBlockGetFileEvidence `
        -LiteralPath $strContextLiteralPath
    & $script:scriptBlockAssertOrdinaryInputFileType -LiteralPath $strCatalogPath
    $hashtableCatalogEvidenceBefore = & $script:scriptBlockGetFileEvidence `
        -LiteralPath $strCatalogPath

    [void](& $script:scriptBlockAssertTrackedScriptIdentity `
        -RepositoryRoot $strRepositoryRoot `
        -GitPath $strGitPath `
        -LiteralPath $strHelperLiteralPath `
        -RelativePath $script:strCandidateHelperRelativePath `
        -ExpectedVersion $script:strCandidateExpectedHelperVersion `
        -ExpectedFunctionCount ([uint32]1))
    [void](& $script:scriptBlockAssertTrackedScriptIdentity `
        -RepositoryRoot $strRepositoryRoot `
        -GitPath $strGitPath `
        -LiteralPath $strContextLiteralPath `
        -RelativePath $script:strCandidateContextRelativePath `
        -ExpectedVersion $script:strCandidateExpectedContextVersion `
        -ExpectedFunctionCount ([uint32]2))

    # The catalog is the oracle. Authenticate it against HEAD, the index, and the
    # no-filter working object before consuming a single expectation, exactly as
    # the two production scripts are authenticated. The allocation hash binds only
    # case IDs, semantic names, and profile names, so without this a staged or
    # unstaged catalog edit could rewrite expected diagnostics, states, counts, or
    # closed sets and still be accepted as the oracle.
    [void](& $script:scriptBlockAssertTrackedBlobIdentity `
        -RepositoryRoot $strRepositoryRoot `
        -GitPath $strGitPath `
        -LiteralPath $strCatalogPath `
        -RelativePath $script:strCandidateCatalogRelativePath)
    $objCatalog = & $script:scriptBlockReadTerraformCandidateCatalog -LiteralPath $strCatalogPath
    $objSourceCatalog = $objCatalog.SourceProvenance.Catalog
    $hashtableIdentityArguments = @{
        RepositoryRoot = $strRepositoryRoot; GitPath = $strGitPath
        HelperLiteralPath = $strHelperLiteralPath; ContextLiteralPath = $strContextLiteralPath
        CatalogPath = $strCatalogPath; HarnessPath = $PSCommandPath
    }
    $hashtableSourceIdentity = & $script:scriptBlockGetTerraformRunIdentity @hashtableIdentityArguments
    if ($hashtableHelperEvidenceBefore.Sha256 -cne $hashtableSourceIdentity.HelperSha256 -or
        $hashtableHelperEvidenceBefore.Length -ne $hashtableSourceIdentity.HelperLength -or
        $hashtableContextEvidenceBefore.Sha256 -cne $hashtableSourceIdentity.ContextSha256 -or
        $hashtableContextEvidenceBefore.Length -ne $hashtableSourceIdentity.ContextLength -or
        $hashtableCatalogEvidenceBefore.Sha256 -cne $hashtableSourceIdentity.CatalogSha256 -or
        $hashtableCatalogEvidenceBefore.Length -ne $hashtableSourceIdentity.CatalogLength) {
        & $script:scriptBlockStopHarness -Code 'orchestration-failed' -Detail 'source-state-changed'
    }
    $strSourceIdentity = & $script:scriptBlockConvertToCanonicalCatalogJson -Value $hashtableSourceIdentity
    [void](& $script:scriptBlockAssertProductionTaxonomyClosed `
        -Catalog $objSourceCatalog `
        -LiteralPath ([string[]]@($strHelperLiteralPath, $strContextLiteralPath)))
    [void](& $script:scriptBlockAssertProductionValidateSetsClosed `
        -Catalog $objSourceCatalog `
        -HelperLiteralPath $strHelperLiteralPath `
        -ContextLiteralPath $strContextLiteralPath)
    [void](& $script:scriptBlockAssertVersionMarkersConsistent `
        -LiteralPath $strHelperLiteralPath `
        -ExpectedVersion $script:strCandidateExpectedHelperVersion `
        -ExpectedFunctionCount ([uint32]1) `
        -OwnVersionVariableName 'script:versionCandidateHelper' `
        -VersionConstantMap @{
            'script:versionCandidateHelper' =
                $script:strCandidateExpectedHelperVersion
            'script:versionCandidateExpectedContext' =
                $script:strCandidateExpectedContextVersion
        })
    [void](& $script:scriptBlockAssertVersionMarkersConsistent `
        -LiteralPath $strContextLiteralPath `
        -ExpectedVersion $script:strCandidateExpectedContextVersion `
        -ExpectedFunctionCount ([uint32]2) `
        -OwnVersionVariableName 'versionCandidateContext' `
        -VersionConstantMap @{
            'versionCandidateContext' =
                $script:strCandidateExpectedContextVersion
        })
    [void](& $script:scriptBlockAssertResourceGuardsWired -LiteralPath $strHelperLiteralPath)
    [void](& $script:scriptBlockAssertUtf8DecoderWired -LiteralPath $strHelperLiteralPath)
    [void](& $script:scriptBlockAssertContextReadsAreCaptured `
        -LiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath)
    $arrContextLoadOutput = @(. $strContextLiteralPath)
    if ($arrContextLoadOutput.Count -ne 0) {
        & $script:scriptBlockStopHarness -Code 'script-identity-invalid' -Detail 'context-load-output'
    }
    $arrHelperLoadOutput = @(. $strHelperLiteralPath -CheckoutRoot $null -TrustedTemporaryRoot $null -DownloadDirectory $null -CandidateDirectory $null -ExpectedDigest $null)
    if ($arrHelperLoadOutput.Count -ne 0) {
        & $script:scriptBlockStopHarness -Code 'script-identity-invalid' -Detail 'helper-load-output'
    }
    foreach ($strFunctionName in @(
        'New-StyleGuideCandidateInvocationContext',
        'Remove-StyleGuideCandidateInvocationContext',
        'Remove-StyleGuideCandidateInvocationState'
    )) {
        $arrFunctions = @(Get-Command -Name $strFunctionName -CommandType Function -All)
        if ($arrFunctions.Count -ne 1) {
            & $script:scriptBlockStopHarness `
                -Code 'script-identity-invalid' `
                -Detail 'loaded-function-cardinality'
        }
    }

    $strOperatingSystem = if ($script:boolCandidateIsWindows) { 'Windows' } else { 'Linux' }
    $strPowerShellEdition = if ($PSVersionTable.PSEdition -eq 'Desktop') {
        'Desktop'
    } else {
        'Core'
    }
    $versionPowerShell = [System.Version]$PSVersionTable.PSVersion
    $strRequiredRuntime = if ($strOperatingSystem -ceq 'Windows' -and
        $strPowerShellEdition -ceq 'Desktop') {
        'WindowsPowerShell5.1'
    } elseif ($strOperatingSystem -ceq 'Windows' -and
        $strPowerShellEdition -ceq 'Core') {
        'PowerShell7Windows'
    } elseif ($strOperatingSystem -ceq 'Linux' -and
        $strPowerShellEdition -ceq 'Core') {
        'PowerShell7Ubuntu'
    } else {
        & $script:scriptBlockStopHarness -Code 'orchestration-failed' -Detail 'unsupported-runtime'
    }
    $strTemporaryParent = [System.IO.Path]::GetFullPath([System.IO.Path]::GetTempPath())
    [void](& $script:scriptBlockAssertOrdinaryDirectoryEnvelope `
        -LiteralPath $strTemporaryParent)
    if ($strTemporaryParent.StartsWith(
        $strRepositoryRoot.TrimEnd(
            [System.IO.Path]::DirectorySeparatorChar,
            [System.IO.Path]::AltDirectorySeparatorChar
        ) + [System.IO.Path]::DirectorySeparatorChar,
        $script:objCandidatePathComparison
    )) {
        & $script:scriptBlockStopHarness -Code 'orchestration-failed' -Detail 'temporary-inside-repository'
    }
    $hashtableRuntime = [ordered]@{
        Id = $strRequiredRuntime; PowerShellVersion = $versionPowerShell.ToString()
        Edition = $strPowerShellEdition; Platform = $strOperatingSystem
    }
    $scriptBlockCheckSourceIdentity = {
        $hashtableCurrent = & $script:scriptBlockGetTerraformRunIdentity @hashtableIdentityArguments
        if ((& $script:scriptBlockConvertToCanonicalCatalogJson -Value $hashtableCurrent) -cne $strSourceIdentity) {
            & $script:scriptBlockStopHarness -Code 'orchestration-failed' -Detail 'source-state-changed'
        }
    }
    & $scriptBlockCheckSourceIdentity
    $objRunContext = New-StyleGuideCandidateInvocationContext -TrustedTemporaryRoot $strTemporaryParent
    $strRunRoot = [System.IO.Path]::Combine($objRunContext.DownloadDirectoryPath, 'fixtures')
    [void][System.IO.Directory]::CreateDirectory($strRunRoot)
    $listObservations = New-Object 'System.Collections.Generic.List[pscustomobject]'
    $listProofObservations = New-Object 'System.Collections.Generic.List[pscustomobject]'
    $arrApplicable = @($objCatalog.Cases | Where-Object { $_.Applicability -ceq 'All' -or $_.Applicability -ceq $strOperatingSystem })
    $boolRootDisposed = $false
    try {
        $script:strTerraformHarnessStage = 'source-assertions'
        & $script:scriptBlockAssertUtf8DecoderMutants `
            -LiteralPath $strHelperLiteralPath `
            -RunRoot $strRunRoot
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertUtf8DecoderStateIsolated `
            -RunRoot $strRunRoot
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertTerraformCatalogMutationsRejected -LiteralPath $strCatalogPath -RunRoot $strRunRoot
        & $script:scriptBlockAssertCatalogMutationsRejected -Catalog $objSourceCatalog -RunRoot $strRunRoot
        & $script:scriptBlockAssertUnauthorizedSkipsRejected -Catalog $objSourceCatalog -OperatingSystem $strOperatingSystem -PowerShellEdition $strPowerShellEdition -PowerShellVersion $versionPowerShell
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertCaptureMutantsRefused `
            -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath `
            -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertModuleBridgeMutantsRefused `
            -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath `
            -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertEnumerationBoundsDeclared `
            -HelperLiteralPath $strHelperLiteralPath `
            -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertEnumerationPrimitiveExclusive `
            -HelperLiteralPath $strHelperLiteralPath `
            -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertArchiveLengthReadOnce `
            -HelperLiteralPath $strHelperLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertStaticMembersResolve `
            -HelperLiteralPath $strHelperLiteralPath `
            -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertDownloadPathProvenance `
            -HelperLiteralPath $strHelperLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertRegularFileProofExecutes `
            -RunRoot $strRunRoot `
            -HelperLiteralPath $strHelperLiteralPath `
            -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertJournalSwapRefused -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertRetainedSequenceFromCapture -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertOrdinaryFileProofWired `
            -LiteralPath $strHelperLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertRound63JournalPlanWired `
            -LiteralPath $strHelperLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertCandidateRecordUnchangedRefused -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertPreexistingRecordReproofRefused -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertLifecycleRecordStatesRejected -RunRoot $strRunRoot -ContextLiteralPath $strContextLiteralPath `
            -HelperLiteralPath $strHelperLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertRound73RegisterLeakDeregistered -RunRoot $strRunRoot `
            -ContextLiteralPath $strContextLiteralPath -HelperLiteralPath $strHelperLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertRound73RefusedWriteToleranceNarrow -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertResourceGuardsReached `
            -ContextLiteralPath $strContextLiteralPath `
            -LiteralPath $strHelperLiteralPath `
            -RunRoot $strRunRoot
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertArchiveTrailerAgreementEnforced `
            -ContextLiteralPath $strContextLiteralPath `
            -LiteralPath $strHelperLiteralPath `
            -RunRoot $strRunRoot
        & $script:scriptBlockAssertTerraformFixtureClassification -Classification ([object[]]@($script:listCandidateFixtureClassification.ToArray()))
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertDirectoryReadsBounded `
            -LiteralPath $strHelperLiteralPath `
            -ContextLiteralPath $strContextLiteralPath `
            -RunRoot $strRunRoot
        & $scriptBlockCheckSourceIdentity
        & $script:scriptBlockAssertTerraformStaticAdaptationMutants -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath -RunRoot $strRunRoot -Catalog $objSourceCatalog
        & $script:scriptBlockAssertTerraformVersionLayoutControls -HelperSource ([System.IO.File]::ReadAllText($strHelperLiteralPath)) -ContextSource ([System.IO.File]::ReadAllText($strContextLiteralPath))
        [void](& $script:scriptBlockAssertTerminalCapabilityClosureMutations -Source ([System.IO.File]::ReadAllText($strHelperLiteralPath)) -Role helper)
        [void](& $script:scriptBlockAssertTerminalCapabilityClosureMutations -Source ([System.IO.File]::ReadAllText($strContextLiteralPath)) -Role context)
        & $scriptBlockCheckSourceIdentity
        [void](& $script:scriptBlockAssertPublicCapabilityCaptureExecutes -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath)
        & $script:scriptBlockAssertTerraformSkipProjectionMutants -Catalog $objCatalog -Runtime $hashtableRuntime
        & $script:scriptBlockAssertTerraformZipGetterMutants -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath
        & $script:scriptBlockAssertTerraformNegativeZip64Fallback -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath
        & $script:scriptBlockAssertTerraformLateLinkFailures -Catalog $objCatalog -RunRoot $strRunRoot `
            -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath `
            -CatalogPath $strCatalogPath -GitPath $strGitPath -Runtime $hashtableRuntime
        & $scriptBlockCheckSourceIdentity
        $script:strTerraformHarnessStage = 'functional-cases'
        foreach ($objCase in $arrApplicable) {
            & $scriptBlockCheckSourceIdentity
            $arrObservation = @(& $script:scriptBlockInvokeTerraformCase -Case $objCase -RunRoot $strRunRoot `
                -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath `
                -CatalogPath $strCatalogPath -GitPath $strGitPath)
            if ($arrObservation.Count -ne 1 -or $arrObservation[0] -isnot [System.Management.Automation.PSCustomObject]) {
                & $script:scriptBlockStopHarness -Code 'orchestration-failed' -Detail 'observation-cardinality'
            }
            $objObservation = $arrObservation[0]
            & $scriptBlockCheckSourceIdentity
            $objRaw = $objCase.Fixture.Parameters.PSObject.Properties['Raw']
            if ($null -ne $objRaw -and $objRaw.Value.Class -cin @('shadow-actual-type', 'shadow-string-type')) {
                & $script:scriptBlockAssertTerraformRawEvidenceMutants -Case $objCase -Observation $objObservation -Runtime $hashtableRuntime
            }
            $objMeasured = & $script:scriptBlockNewTerraformCaseResult -Case $objCase -Observation $objObservation -Runtime $hashtableRuntime -SourceIntegrityVerified $true
            if ($objMeasured.HarnessVerdict -cnotin @('pass', 'skip')) {
                & $script:scriptBlockStopHarness -Code 'orchestration-failed' -Detail ('case-oracle-' + $objCase.Id + '-' + ($objMeasured.FailureReasons -join '-'))
            }
            $listObservations.Add([pscustomobject]@{ Case = $objCase; Observation = $objObservation })
        }
        $script:strTerraformHarnessStage = 'harness-proofs'
        foreach ($objProof in $objCatalog.HarnessProofs.Rows) {
            & $scriptBlockCheckSourceIdentity
            $objObservation = if ($objProof.Id -ceq 'T1A-H-01') {
                & $script:scriptBlockInvokeTerraformH01Proof -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath -SourceIdentity $hashtableSourceIdentity
            } else {
                & $script:scriptBlockInvokeTerraformH02Proof -RunRoot $strRunRoot -HelperLiteralPath $strHelperLiteralPath -ContextLiteralPath $strContextLiteralPath -SourceIdentity $hashtableSourceIdentity
            }
            [void](& $script:scriptBlockAssertTerraformProofEvidenceMutants -Observation $objObservation -Id $objProof.Id -SourceIdentity $hashtableSourceIdentity)
            $listProofObservations.Add([pscustomobject]@{ Row = $objProof; Observation = $objObservation })
        }
        & $scriptBlockCheckSourceIdentity
        $script:strTerraformHarnessStage = 'download-leaf-assertion'
        & $script:scriptBlockAssertDownloadLeafGuardExecutes `
            -HelperLiteralPath $strHelperLiteralPath `
            -RunRoot $strRunRoot
        & $scriptBlockCheckSourceIdentity
        $script:strTerraformHarnessStage = 'result-sealing'
        $listResults = New-Object 'System.Collections.Generic.List[pscustomobject]'
        foreach ($objPair in $listObservations) {
            $listResults.Add((& $script:scriptBlockNewTerraformCaseResult -Case $objPair.Case -Observation $objPair.Observation -Runtime $hashtableRuntime -SourceIntegrityVerified $true))
        }
        $listProofResults = New-Object 'System.Collections.Generic.List[pscustomobject]'
        foreach ($objPair in $listProofObservations) {
            $listProofResults.Add((& $script:scriptBlockNewTerraformProofResult -Row $objPair.Row -Observation $objPair.Observation -Runtime $hashtableRuntime -SourceIdentity $hashtableSourceIdentity))
        }
        & $script:scriptBlockAssertTerraformResultRowCloning -FullResults $listResults.ToArray()
        & $script:scriptBlockAssertTerraformResultPairMutants -Expected $arrApplicable -Results $listResults.ToArray() -RuntimeId $strRequiredRuntime
        & $script:scriptBlockAssertTerraformResultPairMutants -Expected $objCatalog.HarnessProofs.Rows -Results $listProofResults.ToArray() -RuntimeId $strRequiredRuntime -Proof
        $hashtableLinkCoverage = @{ root = 0; 'below-root' = 0; candidate = 0; context = 0 }
        foreach ($objResult in $listResults) {
            if ($objResult.HarnessVerdict -cne 'pass' -or $objResult.ActualResult -cne 'rejection') { continue }
            $strCategory = switch -Exact ($objResult.Id) {
                'T1A-AF-04' { 'root' }; 'T1A-E-09' { 'root' }; 'T1A-E-10' { 'root' }; 'T1A-E-26' { 'root' }
                'T1A-W-04' { 'below-root' }; 'T1A-K-02' { 'candidate' }; 'T1A-L-03' { 'candidate' }; 'T1A-L-04' { 'candidate' }
                'T1A-C-04' { 'context' }; default { $null }
            }
            if ($null -ne $strCategory) { $hashtableLinkCoverage[$strCategory]++ }
        }
        foreach ($strCategory in $hashtableLinkCoverage.Keys) {
            if ($hashtableLinkCoverage[$strCategory] -lt 1) { & $script:scriptBlockStopHarness -Code 'orchestration-failed' -Detail 'required-link-coverage' }
        }
        $uintPassCount = @($listResults | Where-Object { $_.HarnessVerdict -ceq 'pass' }).Count
        $uintFailCount = @($listResults | Where-Object { $_.HarnessVerdict -ceq 'fail' }).Count
        $uintSkipCount = @($listResults | Where-Object { $_.HarnessVerdict -ceq 'skip' }).Count
        $objUtf8 = New-Object System.Text.UTF8Encoding($false)
        $strProofHash = & $script:scriptBlockGetByteArraySha256 -Bytes $objUtf8.GetBytes((& $script:scriptBlockConvertToCanonicalCatalogJson -Value $objCatalog.HarnessProofs))
        $arrRuntimeTotals = @('WindowsPowerShell5.1', 'PowerShell7Windows', 'PowerShell7Ubuntu') | ForEach-Object {
            $strCell = $_
            $strPlatform = if ($strCell -ceq 'PowerShell7Ubuntu') { 'Linux' } else { 'Windows' }
            [pscustomobject][ordered]@{ Runtime = $strCell; ExpectedFunctionalResults = @($objCatalog.Cases | Where-Object { $_.Applicability -ceq 'All' -or $_.Applicability -ceq $strPlatform }).Count; ExpectedProofResults = 2 }
        }
        $objEnvelope = [pscustomobject][ordered]@{
            Schema = 'TerraformStyleGuide.CandidateRunEnvelope.v1'
            SchemaVersion = [uint32]1
            HarnessVersion = $script:versionCandidateHarness.ToString()
            HelperVersion = $script:strCandidateExpectedHelperVersion
            ContextVersion = $script:strCandidateExpectedContextVersion
            StartedUtc = $script:strCandidateRunStartedUtc
            RuntimeVersion = [System.Environment]::Version.ToString()
            CatalogVersion = $objCatalog.CatalogVersion; OracleVersion = $objCatalog.OracleVersion
            CanonicalCatalogSha256 = $script:strTerraformCandidateCanonicalSha256
            CatalogByteSha256 = $script:strTerraformCandidateCatalogFileSha256
            ProfileCount = @($objCatalog.OracleProfiles.PSObject.Properties).Count
            FunctionalCaseCount = $objCatalog.CaseCount; ExpectedRuntimeResults = $arrApplicable.Count
            ExcludedOppositePlatformCount = $objCatalog.CaseCount - $arrApplicable.Count
            ExpectedPairTotals = $arrRuntimeTotals
            FunctionalResultCount = $listResults.Count
            ActualLinkRejectionCoverage = [pscustomobject]$hashtableLinkCoverage
            PassCount = $uintPassCount; FailCount = $uintFailCount; SkipCount = $uintSkipCount
            ProofManifestVersion = $objCatalog.HarnessProofs.ManifestVersion
            CanonicalProofManifestSha256 = $strProofHash
            ProofIds = [string[]]@('T1A-H-01', 'T1A-H-02')
            ExpectedAllRuntimeProofResults = 6; ExpectedRuntimeProofResults = 2
            ProofResultCount = $listProofResults.Count; ProofPassCount = $listProofResults.Count
            ProofFailCount = 0; ProofSkipCount = 0
            Runtime = [pscustomobject]$hashtableRuntime
            SourceIdentity = [pscustomobject]$hashtableSourceIdentity
            SourceIntegrityVerified = $true
            AdversarialFixtureClassification = [object[]]@($script:listCandidateFixtureClassification.ToArray())
            CompletedUtc = $null
            StatusSemantics = 'native-process-exit-is-captured-by-the-invoking-test-runner'
        }
        # The enclosing context owns only its ordinary root and download folder.
        # Case observations were captured before their fixture teardown. Remove
        # the separate fixture child before asking the real manager to dispose.
        & $script:scriptBlockRemoveTestTree -LiteralPath $strRunRoot -ApprovedParent $objRunContext.DownloadDirectoryPath
        $objRunContext = Remove-StyleGuideCandidateInvocationContext -Context $objRunContext
        if ($objRunContext.LifecycleState -cne 'Disposed' -or $objRunContext.CleanupSummary.RemovedPaths.Count -ne 2) {
            & $script:scriptBlockStopHarness -Code 'orchestration-failed' -Detail 'run-context-not-disposed'
        }
        $boolRootDisposed = $true
        & $scriptBlockCheckSourceIdentity
        $objEnvelope.CompletedUtc = [System.DateTime]::UtcNow.ToString('o', [System.Globalization.CultureInfo]::InvariantCulture)
        foreach ($objResult in $listResults) { Write-Output (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $objResult) }
        foreach ($objResult in $listProofResults) { Write-Output (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $objResult) }
        Write-Output (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $objEnvelope)
        if ($uintFailCount -ne 0) { & $script:scriptBlockStopHarness -Code 'orchestration-failed' -Detail 'case-failure' }
    } finally {
        if (-not $boolRootDisposed) {
            & $script:scriptBlockRemoveTestTree -LiteralPath $strRunRoot -ApprovedParent $objRunContext.DownloadDirectoryPath
            $objRunContext = Remove-StyleGuideCandidateInvocationContext -Context $objRunContext
        }
    }
}

$script:strTerraformHarnessStage = 'startup'
try {
    & $script:scriptBlockAssertTerraformMainFailureProjection
    & $script:scriptBlockAssertTerraformCanonicalNumericTypes
    Invoke-StyleGuideCandidateHarness
} catch {
    $objFailureProjection = & $script:scriptBlockGetTerraformMainFailure -Failure $_ -Stage $script:strTerraformHarnessStage
    [System.Console]::Error.WriteLine(
        (& $script:scriptBlockConvertToCanonicalCatalogJson -Value $objFailureProjection))
    exit 1
}
